INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C1','kor',4,2,'u2',2,'이 단원에서 배울 두 가지 — 한글을 사랑하는 마음 지니기(글자가 필요한 까닭·한글의 특성·한글을 지킨 사람들) · 우리말 사용에 대하여 조사해 보고하는 글 쓰기',ARRAY['[4국04-05][4국03-02]']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C2','kor',4,2,'u2',2,'한국어와 한글 — 날마다 입으로 하는 말은 우리말(한국어), 그 말을 눈에 보이게 적는 글자는 우리글(한글) — 말과 글자는 다름',ARRAY['[4국04-05][4국03-02]']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C3','kor',4,2,'u2',2,'한글날 — 10월 9일 — 세종 대왕이 만든 우리 글자를 널리 알린 것을 기념하고 한글의 소중함을 되새기는 날',ARRAY['[4국04-05][4국03-02]']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C4','kor',4,2,'u2',2,'글자 하나가 바꾸는 뜻 — 「않았다」와 「안았다」처럼 소리가 비슷해도 받침 하나가 다르면 읽는 사람이 전혀 다른 뜻으로 받아들일 수 있음',ARRAY['[4국04-05][4국03-02]']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C5','kor',4,2,'u2',2,'말과 문자 — 말(언어)은 소리로 생각을 주고받는 것, 문자는 말을 눈에 보이게 적는 약속된 기호 — 말을 대신하려고가 아니라 말을 붙잡아 두려고 생김',ARRAY['[4국04-05]']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C6','kor',4,2,'u2',2,'문자가 꼭 필요한 때 — 말을 못 할 때만이 아니라 할 말을 오래 남기거나 멀리 정확하게 전해야 할 때 — 말은 전해지는 동안 바뀌고 잊힘',ARRAY['[4국04-05]']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C7','kor',4,2,'u2',2,'글자 없던 때의 기록 — 매듭·금·그림으로 기록하면 보는 사람마다 뜻을 다르게 짐작하고, 까닭이나 마음처럼 눈에 안 보이는 것은 나타내기 어려움',ARRAY['[4국04-05]']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C8','kor',4,2,'u2',2,'문자가 하는 일 — 잊지 않고 정확하게 기억하게 돕고(조리 순서) · 멀리 있는 사람에게 생각을 전하고(전자 우편) · 지난 일을 알 수 있게 함(옛 일기)',ARRAY['[4국04-05]']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C9','kor',4,2,'u2',2,'시간과 거리를 넘어 쌓이는 지식 — 한 사람이 알아낸 것을 적어 두면 다음 사람이 이어받아 더 알아낼 수 있음 — 문자가 사람들의 지식과 생각을 쌓아 가게 함',ARRAY['[4국04-05]']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C10','kor',4,2,'u2',2,'조사할 거리 떠올리기 — 말 때문에 불편했거나 궁금했던 때를 떠올려 우리말에 대해 조사할 거리를 찾음',ARRAY['[4국04-05][4국03-02]']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C11','kor',4,2,'u2',3,'훈민정음을 만든 까닭 — 한자는 글자 수가 많아 익히기 어려워 자기 뜻을 적지 못하는 백성이 많았음 — 세종 대왕은 누구나 쉽게 익혀 쓰는 글자를 만들어 1446년에 널리 알림',ARRAY['[4국04-05][4국02-02]']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C12','kor',4,2,'u2',3,'본떠 만든 기본 글자 — 자음자 ㅁ은 입, ㅅ은 이, ㅇ은 목구멍의 모양 · 모음자 ㆍ는 둥근 하늘, ㅡ는 평평한 땅, ㅣ는 곧게 선 사람을 본뜸',ARRAY['[4국04-05][4국02-02]']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C13','kor',4,2,'u2',3,'획을 더해 만든 자음자 — ㅁ → ㅂ → ㅍ · ㅅ → ㅈ → ㅊ · ㄴ → ㄷ → ㅌ — 기본 글자에 획을 더할수록 소리가 더 세짐',ARRAY['[4국04-05][4국02-02]']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C14','kor',4,2,'u2',3,'닮았다고 모두 획을 더한 글자는 아님 — ㄹ은 모양이 ㄷ과 닮았지만 ㄷ에 획을 더한 글자가 아님(ㄷ에 획을 더한 글자는 ㅌ)',ARRAY['[4국04-05][4국02-02]']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C15','kor',4,2,'u2',3,'합쳐 만든 모음자 — ㅣ 오른쪽에 ㆍ를 붙이면 ㅏ, ㅡ 아래에 ㆍ를 붙이면 ㅜ — 기본 글자를 합쳐 만듦',ARRAY['[4국04-05][4국02-02]']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C16','kor',4,2,'u2',3,'소리와 모양의 짜임 — 비슷한 소리를 내는 글자는 모양도 닮았고(ㅂ·ㅍ·ㅃ), 한 글자는 대체로 같은 소리를 냄 — 적은 수의 글자로 우리말을 두루 읽고 씀',ARRAY['[4국04-05][4국02-02]']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C17','kor',4,2,'u2',3,'글자의 짜임과 말소리 — 「국물 → [궁물]」처럼 말소리가 이어지면 소리가 바뀌기도 함 — 글자의 짜임은 그대로이고, 그래서 바른 발음도 함께 익힘',ARRAY['[4국04-05][4국02-02]']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C18','kor',4,2,'u2',3,'한글의 소중함과 다른 글자 — 한글의 좋은 점은 한글 자체의 짜임새에 있음 — 다른 글자도 저마다 자기 말을 적어 왔으니 깎아내리지 않고, 한글을 낮추지도 않음',ARRAY['[4국04-05][4국02-02]']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C19','kor',4,2,'u2',3,'글에서 찾아 특성 설명하기 — 글에서 찾은 정보를 모아 한글의 특성을 정리하고, 예를 들어 설명함(글에 없는 말로 부풀리지 않음)',ARRAY['[4국04-05][4국02-02]']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C20','kor',4,2,'u2',5,'우리말과 한글을 지키고 가꾸는 사람들 — 국어사전을 만드는 사람 · 다른 나라에서 한글을 가르치는 사람 · 외국어를 쉬운 우리말로 다듬는 사람 — 하는 일은 달라도 같은 일을 함',ARRAY['[4국04-05]']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C21','kor',4,2,'u2',5,'「원고 상자를 지킨 사람들」 내용 — 우리말을 마음껏 쓰기 어려운 때에 조선어학회 사람들이 우리말이 사라지지 않도록 낱말과 뜻을 모아 사전 원고를 쌓음 — 빼앗겼다가 광복 뒤 되찾아 사전을 펴냄',ARRAY['[4국04-05]']::text[],21) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C22','kor',4,2,'u2',5,'글에 나온 낱말 — 원고(책으로 펴내려고 미리 쓴 글) · 광복(빼앗긴 나라를 되찾음) · 펴내다(책 따위를 만들어 세상에 내놓다)',ARRAY['[4국04-05]']::text[],22) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C23','kor',4,2,'u2',5,'일어난 일의 차례 — 낱말과 뜻을 모아 원고를 쌓음 → 1942년 원고를 빼앗기고 감옥에 갇힘 → 1945년 가을 서울역 창고에서 되찾아 사전을 펴내기 시작함',ARRAY['[4국04-05]']::text[],23) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C24','kor',4,2,'u2',5,'행동으로 마음 짐작하기 — 고생하면서도 멈추지 않은 행동에서, 우리말과 글을 잃지 않고 다음 사람들에게 물려주려는 마음을 짐작함',ARRAY['[4국04-05]']::text[],24) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C25','kor',4,2,'u2',5,'한글날이 생긴 날 — 1926년 조선어연구회가 훈민정음을 기리는 날을 정해 「가갸날」이라 부름(가, 갸, 거, 겨…… 하고 익히던 모습) → 2년 뒤 1928년 「한글날」로 바꿈',ARRAY['[4국04-05]']::text[],25) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C26','kor',4,2,'u2',5,'두 글의 공통점 — 사전 원고를 지킨 사람들은 우리말을 기록으로 남기고, 가갸날을 정한 사람들은 한글의 소중함을 되새기게 함 — 방법은 달라도 자기가 할 수 있는 일로 한글을 아낌',ARRAY['[4국04-05]']::text[],26) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C27','kor',4,2,'u2',5,'오늘의 내가 하는 한글 사랑 — 한글 사랑은 대단한 사람만의 일도, 무엇을 금지하는 일도 아님 — 받침까지 바르게 쓰기·모르는 낱말 사전 찾기처럼 내 생활에서 시작함',ARRAY['[4국04-05]']::text[],27) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C28','kor',4,2,'u2',5,'한글을 아낀 사람에게 편지 쓰기 — 알게 된 일 → 그때 든 생각 → 앞으로 내가 할 한글 사랑 차례로 씀',ARRAY['[4국04-05]']::text[],28) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C29','kor',4,2,'u2',7,'우리말을 바르게 써야 하는 까닭 — 뜻이 정확하게 통함 · 서로의 마음을 지킴 · 조상에게서 이어받아 다음 사람에게 물려줄 유산인 우리말을 아끼고 가꿈',ARRAY['[4국04-05]']::text[],29) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C30','kor',4,2,'u2',7,'외국어를 지나치게 쓰는 문제 — 「키즈 룸 이용 룰」처럼 우리말로 충분히 쓸 수 있는데도 외국어를 지나치게 쓰는 것이 문제 — 우리말로 고쳐 씀',ARRAY['[4국04-05]']::text[],30) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C31','kor',4,2,'u2',7,'우리말처럼 굳은 말 — 「버스·피아노」처럼 바꿔 쓸 알맞은 우리말이 없이 굳은 말은 써도 됨 — 외국에서 온 말이 다 나쁜 것은 아님',ARRAY['[4국04-05]']::text[],31) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C32','kor',4,2,'u2',7,'줄임말은 듣는 사람과 상황 — 듣는 사람이 모르는 줄임말은 뜻이 잘못 전해짐(「생선」) — 줄임말은 듣는 사람과 상황을 살펴 쓰고, 모를 수 있으면 풀어 씀',ARRAY['[4국04-05]']::text[],32) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C33','kor',4,2,'u2',7,'거친 말이 하는 일 — 거친 말은 상대의 마음을 다치게 하고 사이를 멀어지게 함 — 놀이 중이라도 쓰지 않음',ARRAY['[4국04-05]']::text[],33) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C34','kor',4,2,'u2',7,'다듬은 말 — 스크린 도어 → 안전문 · 내비게이션 → 길도우미 · 홈페이지 → 누리집 — 국립국어원은 외국어를 쉬운 우리말로 다듬은 말을 누리집에 모아 둠',ARRAY['[4국04-05]']::text[],34) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C35','kor',4,2,'u2',8,'보고 — 알아보거나 한 일의 과정과 결과를 있는 그대로 알리는 것',ARRAY['[4국03-02][4국06-03]']::text[],35) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C36','kor',4,2,'u2',8,'보고하는 글에 들어가는 것 — 조사 대상 · 기간 · 동기 · 방법 · 조사한 내용 · 조사 소감 · 참고 자료와 그 출처',ARRAY['[4국03-02][4국06-03]']::text[],36) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C37','kor',4,2,'u2',8,'조사 방법의 종류와 특징 — 설문 조사(여럿에게 같은 질문지) · 면담 조사(직접 만나 묻기) · 인터넷 조사(만든 이 확인·출처) · 책 조사 · 방문 조사',ARRAY['[4국03-02][4국06-03]']::text[],37) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C38','kor',4,2,'u2',8,'알아내려는 내용에 맞는 방법 — 「몇 명」은 설문, 「까닭」은 면담, 「뜻」은 사전 — 방법의 개수가 많다고 좋은 보고서도, 한 가지만 써야 하는 것도 아님',ARRAY['[4국03-02][4국06-03]']::text[],38) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C39','kor',4,2,'u2',8,'면담할 때 지킬 점 — 질문을 미리 준비하고, 끝까지 듣고, 들은 말을 그대로 적거나 허락을 받고 녹음함',ARRAY['[4국03-02][4국06-03]']::text[],39) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C40','kor',4,2,'u2',8,'매체 자료 활용 — 조사 결과에 맞는 표·그림·사진·그래프를 함께 쓰면 읽는 사람이 한눈에 알아봄',ARRAY['[4국03-02][4국06-03]']::text[],40) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C41','kor',4,2,'u2',8,'결과를 부풀리지 않기 — 수를 틀리게 적지 않아도 「대부분·거의 모두」 같은 낱말로 부풀리거나 한 명의 말을 「모두」로 넓히면 정확한 보고가 아님',ARRAY['[4국03-02][4국06-03]']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C42','kor',4,2,'u2',8,'출처 밝히기 — 옮겨 온 자료는 누가 만든 어떤 자료인지(누리집 이름·찾은 낱말·찾아본 날) 출처를 밝힘 — 「인터넷」만으로는 부족함',ARRAY['[4국03-02][4국06-03]']::text[],42) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C43','kor',4,2,'u2',8,'사실과 내 생각은 칸을 나누어 — 조사한 내용에는 알아낸 사실을 있는 그대로, 조사 소감에는 내 생각이나 다짐 — 보고하는 글에도 내 생각은 들어가되 섞지 않음',ARRAY['[4국03-02][4국06-03]']::text[],43) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C44','kor',4,2,'u2',10,'조사 주제 정하기 — 관심 있으면서 내가 직접 자료를 모을 수 있는 주제(우리 반 친구들이 아침에 쓰는 인사말) — 너무 큰 주제는 직접 조사할 수 없음',ARRAY['[4국03-02][4국06-03]']::text[],44) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C45','kor',4,2,'u2',10,'설문 질문 만들기 — 한 번에 한 가지만 묻고, 답을 한쪽으로 몰지 않게 물음',ARRAY['[4국03-02][4국06-03]']::text[],45) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C46','kor',4,2,'u2',10,'조사 결과 간추리기 — 부풀리지도 줄이지도 거꾸로 옮기지도 않고 조사한 그대로 간추림(수가 없는 문장도 결과와 맞는지 따짐)',ARRAY['[4국03-02][4국06-03]']::text[],46) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C47','kor',4,2,'u2',10,'처음 · 가운데 · 끝 — 처음 — 제목·조사 대상·기간·동기·방법 · 가운데 — 조사한 내용(사실)과 매체 자료 · 끝 — 조사 소감(내 생각)·참고 자료와 출처',ARRAY['[4국03-02][4국06-03]']::text[],47) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C48','kor',4,2,'u2',10,'점검하고 고쳐 쓰기 — 좋은 보고하는 글은 긴 글이 아니라 믿을 수 있는 글 — 길이를 늘리려고 하지 않은 조사나 말을 지어 넣지 않고, 사실대로 고치고 출처를 분명히 함',ARRAY['[4국03-02][4국06-03]']::text[],48) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C49','kor',4,2,'u2',12,'한글 사랑 시 — 좋은 한글 사랑 시는 행의 수나 낱말의 어려움이 아니라 한글에 대한 내 마음이 또렷하게 담긴 시',ARRAY['[4국04-05][4국03-02]']::text[],49) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C50','kor',4,2,'u2',12,'우리 둘레의 말 조사 계획 — 조사 대상·기간·동기·방법을 구체적으로 정하고, 동기는 우리말 사용과 이어지게 함',ARRAY['[4국04-05][4국03-02]']::text[],50) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C51','kor',4,2,'u2',12,'살펴보는 것은 물건이 아니라 쓰인 말 — 이름을 우리말을 살린 것과 우리말로 쓸 수 있는데 외국어로만 지은 것으로 조사한 그대로 나눔 — 외국어 이름이라고 나쁜 물건이 아님',ARRAY['[4국04-05][4국03-02]']::text[],51) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C52','kor',4,2,'u2',12,'ㄼ 받침의 소리 — ㄼ 받침 뒤에 자음이 오면 대부분 [ㄹ]로 소리 남 — 떫다 [떨따] · 엷고 [열꼬]',ARRAY['기초 다지기(발음·쓰기 — 성취기준 번호 확인 필요)']::text[],52) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C53','kor',4,2,'u2',12,'「밟-」은 [밥] — 「밟다」는 ㄼ 받침이지만 자음 앞에서 [ㅂ]으로 소리 내기로 정해 둔 말 — 밟다 [밥따] · 밟고 [밥꼬]',ARRAY['기초 다지기(발음·쓰기 — 성취기준 번호 확인 필요)']::text[],53) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C54','kor',4,2,'u2',12,'소리와 다르게 적는 까닭 — 「밟다 · 밟아 · 밟고」처럼 뜻을 알아보기 쉽게 글자는 원래 모양대로 적고 소리만 바뀌어 냄 — 소리대로 「밥고」라고 적지 않음',ARRAY['기초 다지기(발음·쓰기 — 성취기준 번호 확인 필요)']::text[],54) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C55','kor',4,2,'u2',12,'더 알아 둘 다듬은 말 — 리플 → 댓글 · 네티즌 → 누리꾼 · 팝업창 → 알림창',ARRAY['기초 다지기(발음·쓰기 — 성취기준 번호 확인 필요)']::text[],55) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K4-2-u2-C56','kor',4,2,'u2',12,'겹받침 낱말 바르게 쓰기 — 넋 · 앉다 · 괜찮다 · 값지다 · 흙처럼 두 받침을 함께 바르게 씀',ARRAY['기초 다지기(발음·쓰기 — 성취기준 번호 확인 필요)']::text[],56) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X01','kor',4,'u2',ARRAY['K4-2-u2-C2']::text[],'입으로 하는 말(한국어)과 그 말을 적는 글자(한글)를 섞어 부른다','말과 글자를 나누어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X02','kor',4,'u2',ARRAY['K4-2-u2-C4']::text[],'소리가 비슷하면 받침을 아무렇게나 적어도 뜻이 같다고 여긴다','받침 하나가 뜻을 바꿔요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X03','kor',4,'u2',ARRAY['K4-2-u2-C5','K4-2-u2-C6']::text[],'문자는 말을 할 수 없을 때만 쓰는, 말을 대신하는 것이라고 여긴다','오래 · 멀리 · 정확하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X04','kor',4,'u2',ARRAY['K4-2-u2-C7']::text[],'매듭·금·그림으로 한 기록도 누구나 같은 뜻으로 알아보고 복잡한 것도 쉽게 남긴다고 여긴다','보는 사람마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X05','kor',4,'u2',ARRAY['K4-2-u2-C8','K4-2-u2-C9']::text[],'문자가 한 역할(기억·멀리 전하기·지난 일 알기)을 엇갈리게 잇거나, 말만으로 충분한 일을 문자가 꼭 필요한 일로 고른다','잊지 않게 · 멀리 · 옛날') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X06','kor',4,'u2',ARRAY['K4-2-u2-C3']::text[],'한글날이나 한글의 뜻을 잘못 안다(세종 대왕이 태어난 날·옛날에만 쓰던 글자)','널리 알린 것을 기념해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X07','kor',4,'u2',ARRAY['K4-2-u2-C10','K4-2-u2-C44']::text[],'조사 주제를 내 생활·관심과 상관없이 아무거나 고르거나 남을 따라 정하고, 직접 조사할 수 없을 만큼 큰 주제를 고른다','내가 직접 모을 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X08','kor',4,'u2',ARRAY['K4-2-u2-C11']::text[],'훈민정음을 만든 까닭을 임금을 뽐내거나 다른 나라 글자를 없애려는 것으로 여긴다','백성 누구나 쉽게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X09','kor',4,'u2',ARRAY['K4-2-u2-C12']::text[],'기본 글자가 본뜬 것을 엇갈리게 안다','자음자는 몸 · 모음자는 하늘·땅·사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X10','kor',4,'u2',ARRAY['K4-2-u2-C13','K4-2-u2-C14']::text[],'모양이 닮았으면 획을 더한 글자라고 여기거나(ㄹ), 획이 늘면 소리가 약해진다고 여긴다','ㄷ에 획을 더하면 ㅌ') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X11','kor',4,'u2',ARRAY['K4-2-u2-C15']::text[],'기본 모음자를 합쳐 만든 글자를 엇갈리게 안다','ㅣ 오른쪽 · ㅡ 아래') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X12','kor',4,'u2',ARRAY['K4-2-u2-C16']::text[],'한글이 짜임새 있는 까닭을 모양이 둥글다·글자 수가 많다처럼 상관없는 것으로 든다','본뜸 · 더함 · 소리와 모양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X13','kor',4,'u2',ARRAY['K4-2-u2-C16','K4-2-u2-C17']::text[],'한글은 어떤 낱말에서도 언제나 적힌 대로만 소리 난다고 여긴다','국물 → [궁물]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X14','kor',4,'u2',ARRAY['K4-2-u2-C17']::text[],'소리가 바뀌는 말이 있으니 한글은 짜임새 없는 글자라고 여긴다','짜임은 그대로예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X15','kor',4,'u2',ARRAY['K4-2-u2-C17','K4-2-u2-C54']::text[],'소리가 바뀌는 말은 소리 나는 대로 고쳐 적어야 한다고 여긴다(궁물·밥고)','뜻을 알아보게 적어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X16','kor',4,'u2',ARRAY['K4-2-u2-C18']::text[],'한글이 가장 좋으니 다른 나라 글자는 형편없고 배울 필요가 없다고 여긴다','다른 글자도 자기 말을 적어 왔어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X17','kor',4,'u2',ARRAY['K4-2-u2-C18']::text[],'글자는 다 비슷하니 한글도 자랑하거나 아낄 까닭이 없다고 여긴다','한글 자체의 짜임새') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X18','kor',4,'u2',ARRAY['K4-2-u2-C21','K4-2-u2-C23','K4-2-u2-C25']::text[],'글에서 일어난 일의 내용이나 때, 차례를 잘못 읽는다','그 줄을 다시 읽기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X19','kor',4,'u2',ARRAY['K4-2-u2-C22','K4-2-u2-C34','K4-2-u2-C55']::text[],'낱말의 뜻이나 외국어와 다듬은 말의 짝을 엇갈리게 안다','문장에 넣어 읽어 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X20','kor',4,'u2',ARRAY['K4-2-u2-C24']::text[],'인물의 행동에서 마음을 짐작할 때 행동과 상관없이 유명해지고 싶은 마음 등으로 짐작한다','끝까지 한 일이 무엇?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X21','kor',4,'u2',ARRAY['K4-2-u2-C20','K4-2-u2-C27']::text[],'한글 사랑은 사전을 만드는 것처럼 대단한 사람만 하는 큰일이라 나와는 상관없다고 여긴다','내 생활에서 시작해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X22','kor',4,'u2',ARRAY['K4-2-u2-C27']::text[],'한글 사랑은 외국어를 한마디도 쓰지 않거나 외국어를 쓰는 사람을 꾸짖는 것이라고 여긴다','금지하는 일이 아니에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X23','kor',4,'u2',ARRAY['K4-2-u2-C19']::text[],'한글의 특성을 설명할 때 글에 없는 말로 부풀린다(세상 모든 소리·쓰는 사람이 가장 많음)','글에서 찾은 것만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X24','kor',4,'u2',ARRAY['K4-2-u2-C30','K4-2-u2-C31']::text[],'외국어가 한 글자라도 있으면 틀린 글이라고 여기거나, 굳은 말(버스·피아노)까지 새 우리말로 바꿔야 한다고 여긴다','바꿔 쓸 우리말이 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X25','kor',4,'u2',ARRAY['K4-2-u2-C30']::text[],'외국어는 멋지니 많이 쓸수록 좋다고 여기거나, 우리말이 있는데도 외국어를 지나치게 쓰는 것을 문제로 보지 않는다','우리말로 쓸 수 있나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X26','kor',4,'u2',ARRAY['K4-2-u2-C32']::text[],'내가 아는 줄임말은 듣는 사람이 누구든 써도 된다고 여긴다','누구에게 쓰나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X27','kor',4,'u2',ARRAY['K4-2-u2-C32']::text[],'줄임말은 친구끼리도 절대 쓰면 안 되는 말이라고 여긴다','듣는 사람과 상황') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X28','kor',4,'u2',ARRAY['K4-2-u2-C33']::text[],'놀이 중에 한 거친 말은 장난이라 상대가 괜찮다고 여긴다','고개 숙인 친구의 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X29','kor',4,'u2',ARRAY['K4-2-u2-C29']::text[],'우리말을 바르게 써야 하는 까닭을 글씨·점수처럼 상관없는 것으로 든다','뜻 · 마음 · 가꾸기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X30','kor',4,'u2',ARRAY['K4-2-u2-C35','K4-2-u2-C36']::text[],'보고를 내 생각대로 꾸며 알리는 것으로 여기거나 보고하는 글에 무엇이 들어가는지 잘못 안다','과정과 결과를 있는 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X31','kor',4,'u2',ARRAY['K4-2-u2-C38']::text[],'조사 방법을 많이 쓸수록 좋은 보고서라고 여긴다','개수보다 알맞음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X32','kor',4,'u2',ARRAY['K4-2-u2-C38']::text[],'보고서에는 조사 방법을 한 가지만 써야 한다고 여긴다','알맞으면 여럿도 돼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X33','kor',4,'u2',ARRAY['K4-2-u2-C37','K4-2-u2-C38']::text[],'알아내려는 내용에 맞지 않는 조사 방법을 고르거나 방법의 특징을 엇갈리게 안다','몇 명 · 까닭 · 뜻') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X34','kor',4,'u2',ARRAY['K4-2-u2-C39']::text[],'면담할 때 끼어들거나, 들은 말을 마음대로 바꾸거나 덧붙여 적는다','들은 그대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X35','kor',4,'u2',ARRAY['K4-2-u2-C41','K4-2-u2-C46']::text[],'수만 틀리지 않으면 정확하다고 여겨 「대부분·거의 모두」 같은 낱말로 결과를 부풀린다','낱말도 결과와 맞나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X36','kor',4,'u2',ARRAY['K4-2-u2-C41','K4-2-u2-C46']::text[],'한 사람의 말을 여러 사람 모두의 까닭으로 넓혀 쓴다','몇 명이 말했나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X37','kor',4,'u2',ARRAY['K4-2-u2-C42']::text[],'옮겨 온 자료를 출처 없이 내 말처럼 쓰거나 출처를 「인터넷」이라고만 쓴다','누가 만든 어떤 자료?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X38','kor',4,'u2',ARRAY['K4-2-u2-C43']::text[],'보고하는 글에는 내 생각을 한 줄도 쓰면 안 된다고 여긴다','조사 소감 칸이 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X39','kor',4,'u2',ARRAY['K4-2-u2-C43']::text[],'내 생각이나 근거 없는 짐작을 조사한 사실과 섞어 「조사한 내용」에 쓴다','확인한 사실인가?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X40','kor',4,'u2',ARRAY['K4-2-u2-C46']::text[],'조사 결과를 거꾸로 옮기거나 엉뚱한 대상에 붙여 옮긴다','가장 많은 것은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X41','kor',4,'u2',ARRAY['K4-2-u2-C48']::text[],'글을 길게 하려고 하지 않은 조사나 듣지 않은 말을 지어 넣는다','길이보다 믿음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X42','kor',4,'u2',ARRAY['K4-2-u2-C45']::text[],'설문 질문에서 한 번에 두 가지를 묻거나 답을 한쪽으로 몰아준다','하나씩 · 몰지 않게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X43','kor',4,'u2',ARRAY['K4-2-u2-C40']::text[],'매체 자료를 결과와 상관없는 꾸밈으로 여기거나 결과를 알아보기 쉽게 하는 쓰임을 모른다','한눈에 보이게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X44','kor',4,'u2',ARRAY['K4-2-u2-C47']::text[],'처음·가운데·끝에 들어갈 내용을 엇갈리게 안다','과정 · 사실 · 생각과 출처') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X45','kor',4,'u2',ARRAY['K4-2-u2-C49']::text[],'행이 많거나 어려운 낱말이 많을수록 좋은 시라고 여긴다','길이보다 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X46','kor',4,'u2',ARRAY['K4-2-u2-C51']::text[],'외국어 이름을 조사한 것을 물건이 나쁘다는 뜻으로 여기거나, 이름을 조사한 그대로 나누지 못한다','물건이 아니라 쓰인 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X47','kor',4,'u2',ARRAY['K4-2-u2-C53']::text[],'ㄼ 받침은 언제나 [ㄹ]로 소리 난다고 여겨 「밟-」도 [발]로 읽는다','밟다 → [밥따]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X48','kor',4,'u2',ARRAY['K4-2-u2-C52']::text[],'ㄼ 받침 낱말의 소리를 엇갈리게 낸다(대부분 [ㄹ]인 말을 [ㅂ]으로·뒤 소리를 그대로)','떫지 → [떨찌]') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X49','kor',4,'u2',ARRAY['K4-2-u2-C56']::text[],'겹받침을 받침 하나로 쓰거나 다른 받침으로 쓴다(흑·안다·갑진)','두 받침을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X50','kor',4,'u2',ARRAY['K4-2-u2-C50']::text[],'조사 동기나 활동을 우리말 사용·한글 사랑과 상관없는 것으로 정한다','우리말과 이어지나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X51','kor',4,'u2',ARRAY['K4-2-u2-C28']::text[],'한글을 아낀 사람에게 쓰는 편지를 알게 된 일과 다짐 없이 칭찬 한마디로 쓴다','알게 된 일 → 생각 → 다짐') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X52','kor',4,'u2',ARRAY['K4-2-u2-C26']::text[],'두 글의 공통점을 한 일의 겉모습이 똑같은 것으로만 찾거나 두 글을 관계없는 것으로 여긴다','방법은 달라도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K4-2-u2-X53','kor',4,'u2',ARRAY['K4-2-u2-C1']::text[],'이 단원에서 배울 내용을 외국어 외우기처럼 단원과 상관없는 것으로 여긴다','한글 사랑 · 보고하는 글') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_basic#1','kor',4,2,'u2','L02','g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C2',1,'mc','auto','우리가 입으로 하는 말과, 그 말을 눈에 보이게 적는 글자를 알맞게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u2-X01']::text[],false,'{"seq":1,"concept":"K4-2-u2-C2","difficulty":1,"kind":"mc","stem":"우리가 입으로 하는 말과, 그 말을 눈에 보이게 적는 글자를 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"말은 한국어, 글자는 한글","correct":true},{"t":"말은 한글, 글자는 한국어","mis":"K4-2-u2-X01"},{"t":"말과 글자 모두 한글","mis":"K4-2-u2-X01"},{"t":"말과 글자 모두 한국어","mis":"K4-2-u2-X01"}],"explanation":["입으로 하는 것은 말이에요.","눈으로 보는 것은 글자예요.","말은 한국어, 글자는 한글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_basic#2','kor',4,2,'u2','L02','g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C4',1,'mc','auto','동생처럼 「숙제를 하지 안았다」라고 쓰면 어떤 일이 생기나요?',ARRAY['K4-2-u2-X02']::text[],false,'{"seq":2,"concept":"K4-2-u2-C4","difficulty":1,"kind":"mc","stem":"동생처럼 「숙제를 하지 안았다」라고 쓰면 어떤 일이 생기나요?","options":[{"t":"읽는 사람이 「껴안았다」는 뜻으로 받아들일 수 있다","correct":true},{"t":"소리가 비슷하니 아무 일도 생기지 않는다","mis":"K4-2-u2-X02"},{"t":"글씨만 예쁘면 뜻이 바르게 전해진다","mis":"K4-2-u2-X02"},{"t":"받침은 빼고 써도 뜻이 같다","mis":"K4-2-u2-X02"}],"explanation":["「안았다」는 껴안았다는 뜻이에요.","「않았다」와 받침이 달라요.","뜻이 바뀌어 버려요."],"asset":{"type":"passage","lines":["동생이 쓴 문장 — 「나는 어제 숙제를 하지 안았다.」","하음 — 「어? 숙제를 두 팔로 꼭 껴안았다는 뜻이 되어 버렸네!」"],"title":"동생의 받아쓰기 공책"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_basic#3','kor',4,2,'u2','L02','g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C5',1,'ox','auto','문자는 목이 아파 말을 할 수 없을 때만 필요해요.',ARRAY['K4-2-u2-X03']::text[],false,'{"seq":3,"concept":"K4-2-u2-C5","difficulty":1,"kind":"ox","stem":"문자는 목이 아파 말을 할 수 없을 때만 필요해요.","answer":"X","reason_options":[{"t":"할 말을 오래 남기거나 멀리 정확하게 전할 때 문자가 꼭 필요하기 때문에","correct":true},{"t":"말을 할 수 있으면 글자는 쓸 일이 없기 때문에","mis":"K4-2-u2-X03"}],"mis":"K4-2-u2-X03","explanation":["문자는 말을 대신하려고 생긴 게 아니에요.","말을 붙잡아 두려고 생겼어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_basic#4','kor',4,2,'u2','L02','g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C7',1,'mc','auto','매듭·금·그림으로 기록할 때 불편한 점은 무엇인가요?',ARRAY['K4-2-u2-X04']::text[],false,'{"seq":4,"concept":"K4-2-u2-C7","difficulty":1,"kind":"mc","stem":"매듭·금·그림으로 기록할 때 불편한 점은 무엇인가요?","options":[{"t":"보는 사람마다 뜻을 다르게 짐작할 수 있다","correct":true},{"t":"누구나 똑같은 뜻으로 알아본다","mis":"K4-2-u2-X04"},{"t":"길고 복잡한 이야기도 쉽게 남길 수 있다","mis":"K4-2-u2-X04"},{"t":"까닭이나 마음도 또렷하게 나타낼 수 있다","mis":"K4-2-u2-X04"}],"explanation":["매듭 다섯 개를 떠올려요.","무엇을 센 걸까요?","보는 사람마다 달라요."],"asset":{"type":"passage","lines":["끈에 매듭을 지어 거둔 곡식이나 가축의 수를 나타냈어요.","나무 막대에 금을 하나씩 그어 지난 날짜를 셌어요.","바위나 벽에 동물과 사람을 그려 사냥한 일을 남겼어요."],"title":"글자가 없던 때의 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_basic#5','kor',4,2,'u2','L02','g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C8',2,'match','auto','장면과 문자가 한 역할을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u2-C8","difficulty":2,"kind":"match","stem":"장면과 문자가 한 역할을 알맞게 이으세요.","pairs":[{"l":"㉮ 달걀말이 순서 적기","r":"잊지 않고 정확하게 기억하게 돕는다"},{"l":"㉯ 이모에게 보낸 소식","r":"멀리 있는 사람에게 생각을 전한다"},{"l":"㉰ 몇백 년 전 일기","r":"지난 일을 알 수 있게 한다"}],"mis":"K4-2-u2-X05","explanation":["「잊지 않게」를 떠올려요.","「멀리」를 떠올려요.","「옛날」을 떠올려요."],"asset":{"type":"passage","lines":["㉮ 할머니께 배운 달걀말이 만드는 순서를 공책에 적어 두었다","㉯ 다른 나라에 사는 이모에게 전자 우편으로 소식을 보냈다","㉰ 몇백 년 전 사람이 쓴 일기를 읽고 그때 일을 알게 되었다"],"title":"오늘날 문자가 쓰이는 세 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_basic#6','kor',4,2,'u2','L02','g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C3',2,'mc','auto','10월 9일 한글날은 어떤 날인가요?',ARRAY['K4-2-u2-X06']::text[],false,'{"seq":6,"concept":"K4-2-u2-C3","difficulty":2,"kind":"mc","stem":"10월 9일 한글날은 어떤 날인가요?","options":[{"t":"세종 대왕이 만든 우리 글자를 널리 알린 것을 기념하고 소중함을 되새기는 날","correct":true},{"t":"세종 대왕이 태어난 날","mis":"K4-2-u2-X06"},{"t":"한글을 쓰지 않고 쉬는 날","mis":"K4-2-u2-X06"},{"t":"옛날에만 쓰던 글자를 기억하는 날","mis":"K4-2-u2-X06"}],"explanation":["하음이가 동생에게 한 말을 떠올려요.","널리 알린 일을 기념해요.","소중함을 되새겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_basic#7','kor',4,2,'u2','L02','g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C6',2,'mc','auto','귓속말 놀이에서 처음 말이 바뀌지 않게 하려면 어떻게 하는 것이 가장 좋을까요?',ARRAY['K4-2-u2-X03','K4-2-u2-X05','K4-2-u2-X04']::text[],false,'{"seq":7,"concept":"K4-2-u2-C6","difficulty":2,"kind":"mc","stem":"귓속말 놀이에서 처음 말이 바뀌지 않게 하려면 어떻게 하는 것이 가장 좋을까요?","options":[{"t":"처음 말을 종이에 적어서 돌린다","correct":true},{"t":"말을 할 수 없는 사람만 종이에 적는다","mis":"K4-2-u2-X03"},{"t":"다섯째 사람이 처음 말을 짐작해 맞힌다","mis":"K4-2-u2-X05"},{"t":"그림을 그려 보는 사람이 뜻을 짐작하게 한다","mis":"K4-2-u2-X04"}],"explanation":["말은 전해지면서 바뀌어요.","적어 두면 그대로 남아요.","종이에 적어 돌려요."],"asset":{"type":"passage","lines":["첫 사람 — 「내일 체험 학습에 물통과 돗자리를 챙겨 오래.」","다섯째 사람 — 「내일 체험 학습에 물감이랑 돋보기를 가져오래!」"],"title":"귓속말 전하기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_basic#8','kor',4,2,'u2','L02','g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C9',2,'mc','auto','문자 덕분에 사람들이 해 올 수 있었던 일은 무엇인가요?',ARRAY['K4-2-u2-X05','K4-2-u2-X03']::text[],false,'{"seq":8,"concept":"K4-2-u2-C9","difficulty":2,"kind":"mc","stem":"문자 덕분에 사람들이 해 올 수 있었던 일은 무엇인가요?","options":[{"t":"앞사람이 알아낸 것을 적어 두면 다음 사람이 이어받아 더 알아내기","correct":true},{"t":"친구와 마주 보고 인사하기","mis":"K4-2-u2-X05"},{"t":"좋아하는 노래 흥얼거리기","mis":"K4-2-u2-X05"},{"t":"목이 아플 때만 쪽지 쓰기","mis":"K4-2-u2-X03"}],"explanation":["말만으로 되는 일은 빼요.","적어 두면 다음 사람이 읽어요.","지식이 쌓여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_basic#9','kor',4,2,'u2','L02','g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C10',2,'mc','auto','우리말에 대해 조사하고 싶은 것이 떠오르지 않을 때 좋은 방법은 무엇인가요?',ARRAY['K4-2-u2-X07','K4-2-u2-X53']::text[],false,'{"seq":9,"concept":"K4-2-u2-C10","difficulty":2,"kind":"mc","stem":"우리말에 대해 조사하고 싶은 것이 떠오르지 않을 때 좋은 방법은 무엇인가요?","options":[{"t":"말 때문에 불편했거나 궁금했던 때를 떠올린다","correct":true},{"t":"사전을 펼쳐 아무 낱말이나 고른다","mis":"K4-2-u2-X07"},{"t":"짝이 정한 것을 그대로 따라 한다","mis":"K4-2-u2-X07"},{"t":"외국어 낱말을 많이 외운다","mis":"K4-2-u2-X53"}],"explanation":["내 생활에서 출발해요.","불편했던 때를 떠올려요.","거기에 조사할 거리가 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_basic#10','kor',4,2,'u2','L02','g4_2_kor_u2_L02_basic','lesson_basic','K4-2-u2-C1',3,'error','auto','이 단원에서 배울 내용을 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u2-X53']::text[],false,'{"seq":10,"concept":"K4-2-u2-C1","difficulty":3,"kind":"error","stem":"이 단원에서 배울 내용을 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「외국어 낱말을 많이 외워서 멋지게 쓰는 법을 배워.」","correct":true,"mis_target":"K4-2-u2-X53"},{"t":"친구 가 — 「한글이 어떤 원리로 만들어졌는지 알아봐.」","mis":"K4-2-u2-X53"},{"t":"친구 다 — 「우리말을 어떻게 쓰는지 조사해 보고하는 글을 써.」","mis":"K4-2-u2-X53"}],"explanation":["한글을 사랑하는 마음이 하나예요.","보고하는 글 쓰기가 하나예요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_challenge#1','kor',4,2,'u2','L02','g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C2',2,'sa','auto','우리말을 적는 글자, 세종 대왕이 만든 훈민정음이 바탕인 글자의 이름을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u2-C2","difficulty":2,"kind":"sa","stem":"우리말을 적는 글자, 세종 대왕이 만든 훈민정음이 바탕인 글자의 이름을 쓰세요.","answer":["한글"],"explanation":["말이 아니라 글자예요.","우리가 날마다 쓰는 글자예요.","‘한글’이에요."],"mis":"K4-2-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_challenge#2','kor',4,2,'u2','L02','g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C5',2,'blank','auto','문자는 말을 대신하려고 생긴 것이 아니라 말을 (  ) 두려고 생겼어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u2-X03']::text[],false,'{"seq":2,"concept":"K4-2-u2-C5","difficulty":2,"kind":"blank","stem":"문자는 말을 대신하려고 생긴 것이 아니라 말을 (  ) 두려고 생겼어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"붙잡아","correct":true},{"t":"흘려","mis":"K4-2-u2-X03"},{"t":"바꾸어","mis":"K4-2-u2-X03"},{"t":"숨겨","mis":"K4-2-u2-X03"}],"explanation":["말은 사라지기 쉬워요.","문자는 말을 남겨 둬요.","‘붙잡아’예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_challenge#3','kor',4,2,'u2','L02','g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C6',3,'mc','auto','문자가 꼭 필요한 경우로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X03','K4-2-u2-X05']::text[],false,'{"seq":3,"concept":"K4-2-u2-C6","difficulty":3,"kind":"mc","stem":"문자가 꼭 필요한 경우로 가장 알맞은 것은 무엇인가요?","options":[{"t":"할머니께 배운 김치전 만드는 순서를 몇 달 뒤에도 정확하게 기억하고 싶을 때","correct":true},{"t":"목이 아파 말을 못 할 때만","mis":"K4-2-u2-X03"},{"t":"친구와 마주 보고 이야기할 때","mis":"K4-2-u2-X05"},{"t":"좋아하는 노래를 흥얼거릴 때","mis":"K4-2-u2-X05"}],"explanation":["말로 충분한 때는 빼요.","오래 남겨야 할 때를 찾아요.","적어 두어야만 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_challenge#4','kor',4,2,'u2','L02','g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C8',3,'match','auto','새로운 세 장면과 문자가 한 역할을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K4-2-u2-C8","difficulty":3,"kind":"match","stem":"새로운 세 장면과 문자가 한 역할을 알맞게 이으세요.","pairs":[{"l":"㉮ 할아버지의 공책","r":"지난 일을 알 수 있게 한다"},{"l":"㉯ 이사 간 친구에게 보낸 편지","r":"멀리 있는 사람에게 생각을 전한다"},{"l":"㉰ 달력에 적은 날짜","r":"잊지 않고 정확하게 기억하게 돕는다"}],"mis":"K4-2-u2-X05","explanation":["옛날 공책이에요.","멀리 사는 친구예요.","잊지 않으려고 적었어요."],"asset":{"type":"passage","lines":["㉮ 할아버지가 젊었을 때 쓴 공책을 읽고 그때 동네 모습을 알게 되었다","㉯ 다른 도시로 이사 간 친구에게 편지를 보내 소식을 전했다","㉰ 책을 돌려줄 날짜를 달력에 적어 두었다"],"title":"문자가 쓰인 또 다른 세 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_challenge#5','kor',4,2,'u2','L02','g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C4',3,'ox','auto','「않았다」와 「안았다」는 소리가 비슷하니 어느 쪽으로 적어도 뜻은 같아요.',ARRAY['K4-2-u2-X02']::text[],false,'{"seq":5,"concept":"K4-2-u2-C4","difficulty":3,"kind":"ox","stem":"「않았다」와 「안았다」는 소리가 비슷하니 어느 쪽으로 적어도 뜻은 같아요.","answer":"X","reason_options":[{"t":"받침 하나가 달라지면 읽는 사람이 전혀 다른 뜻으로 받아들일 수 있기 때문에","correct":true},{"t":"소리가 같으면 글자도 같은 말이기 때문에","mis":"K4-2-u2-X02"}],"mis":"K4-2-u2-X02","explanation":["「안았다」는 껴안았다예요.","「않았다」는 하지 않았다예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_challenge#6','kor',4,2,'u2','L02','g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C7',3,'mc','auto','매듭 다섯 개를 본 다른 사람이 할 수 있는 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X04']::text[],false,'{"seq":6,"concept":"K4-2-u2-C7","difficulty":3,"kind":"mc","stem":"매듭 다섯 개를 본 다른 사람이 할 수 있는 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"곡식 다섯 자루인지, 가축 다섯 마리인지 알 수 없다","correct":true},{"t":"누구나 「닭 다섯 마리」라고 똑같이 읽는다","mis":"K4-2-u2-X04"},{"t":"매듭에는 까닭과 마음까지 담겨 있다","mis":"K4-2-u2-X04"},{"t":"매듭은 문자이니 뜻이 하나로 정해져 있다","mis":"K4-2-u2-X04"}],"explanation":["매듭은 수만 보여 줘요.","무엇을 센 건지는 몰라요.","뜻을 짐작해야 해요."],"asset":{"type":"passage","lines":["끈에 매듭을 지어 거둔 곡식이나 가축의 수를 나타냈어요.","나무 막대에 금을 하나씩 그어 지난 날짜를 셌어요.","바위나 벽에 동물과 사람을 그려 사냥한 일을 남겼어요."],"title":"글자가 없던 때의 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_challenge#7','kor',4,2,'u2','L02','g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C2',3,'error','auto','한국어와 한글을 두고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['K4-2-u2-X01']::text[],false,'{"seq":7,"concept":"K4-2-u2-C2","difficulty":3,"kind":"error","stem":"한국어와 한글을 두고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「우리가 지금 입으로 하는 말이 한글이야.」","correct":true,"mis_target":"K4-2-u2-X01"},{"t":"친구 가 — 「한글은 우리말을 눈에 보이게 적는 글자야.」","mis":"K4-2-u2-X01"},{"t":"친구 나 — 「한글이 없던 옛날에도 사람들은 우리말을 했어.」","mis":"K4-2-u2-X01"}],"explanation":["입으로 하는 건 말이에요.","말은 한국어예요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_challenge#8','kor',4,2,'u2','L02','g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C9',4,'mc','auto','「문자는 시간과 거리를 넘어 사람들의 지식을 쌓아 가게 해 주었다」를 가장 잘 보여 주는 예는 무엇인가요?',ARRAY['K4-2-u2-X05','K4-2-u2-X03','K4-2-u2-X04']::text[],false,'{"seq":8,"concept":"K4-2-u2-C9","difficulty":4,"kind":"mc","stem":"「문자는 시간과 거리를 넘어 사람들의 지식을 쌓아 가게 해 주었다」를 가장 잘 보여 주는 예는 무엇인가요?","options":[{"t":"몇백 년 전 사람이 적어 둔 별 관찰 기록을 오늘날 사람이 읽고 이어서 연구한다","correct":true},{"t":"옆자리 친구에게 오늘 숙제를 말로 알려 준다","mis":"K4-2-u2-X05"},{"t":"말을 할 수 없을 때 손짓으로 뜻을 전한다","mis":"K4-2-u2-X03"},{"t":"바위에 그린 그림을 보고 저마다 다른 이야기를 짐작한다","mis":"K4-2-u2-X04"}],"explanation":["시간을 넘었나요?","다음 사람이 이어받았나요?","그래야 지식이 쌓여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_challenge#9','kor',4,2,'u2','L02','g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C6',4,'mc','auto','귓속말 놀이에서 말이 바뀐 까닭과 문자가 필요한 까닭을 가장 알맞게 이은 것은 무엇인가요?',ARRAY['K4-2-u2-X03','K4-2-u2-X05','K4-2-u2-X04']::text[],false,'{"seq":9,"concept":"K4-2-u2-C6","difficulty":4,"kind":"mc","stem":"귓속말 놀이에서 말이 바뀐 까닭과 문자가 필요한 까닭을 가장 알맞게 이은 것은 무엇인가요?","options":[{"t":"말은 전해지는 동안 바뀌고 잊히기 쉬워서, 정확하게 오래 남기려면 문자가 필요하다","correct":true},{"t":"다섯째 사람이 말을 못 해서 문자가 필요하다","mis":"K4-2-u2-X03"},{"t":"놀이에서는 말이 바뀌어도 되니 문자는 필요 없다","mis":"K4-2-u2-X05"},{"t":"그림으로 그리면 누구나 같은 뜻으로 알아보니 문자는 필요 없다","mis":"K4-2-u2-X04"}],"explanation":["물통이 물감이 되었어요.","말은 바뀌고 잊혀요.","적어 두면 그대로 남아요."],"asset":{"type":"passage","lines":["첫 사람 — 「내일 체험 학습에 물통과 돗자리를 챙겨 오래.」","다섯째 사람 — 「내일 체험 학습에 물감이랑 돋보기를 가져오래!」"],"title":"귓속말 전하기 놀이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L02_challenge#10','kor',4,2,'u2','L02','g4_2_kor_u2_L02_challenge','lesson_challenge','K4-2-u2-C6',4,'essay','teacher','「문자가 없다면 ○○이 어렵다. 그래서 문자가 필요하다.」의 틀로 문자가 필요한 까닭을 쓰고, 「문자는 말을 못 할 때만 필요하다」가 왜 알맞지 않은지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u2-C6","difficulty":4,"kind":"essay","stem":"「문자가 없다면 ○○이 어렵다. 그래서 문자가 필요하다.」의 틀로 문자가 필요한 까닭을 쓰고, 「문자는 말을 못 할 때만 필요하다」가 왜 알맞지 않은지도 쓰세요.","answer_guide":{"answer":"예: 문자가 없다면 할머니께 배운 조리 순서를 몇 달 뒤에 정확하게 떠올리기 어렵다. 그래서 생각을 오래 정확하게 남기려면 문자가 필요하다. 말을 할 수 있어도 말은 전해지는 동안 바뀌고 잊히기 때문에, 문자는 말을 못 할 때만 필요한 것이 아니다.","scoring_points":["틀에 맞추어 문자가 필요한 까닭을 썼는가","오래 남기기·멀리 전하기·지난 일 알기 가운데 하나를 들었는가","「말을 못 할 때만」이 알맞지 않은 까닭을 썼는가"]},"explanation":["틀에 맞춰 써요.","말이 바뀌고 잊히는 것을 떠올려요.","말을 할 수 있어도 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_basic#1','kor',4,2,'u2','L03','g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C11',1,'mc','auto','세종 대왕이 새 글자를 만든 까닭은 무엇인가요?',ARRAY['K4-2-u2-X08']::text[],false,'{"seq":1,"concept":"K4-2-u2-C11","difficulty":1,"kind":"mc","stem":"세종 대왕이 새 글자를 만든 까닭은 무엇인가요?","options":[{"t":"백성 누구나 쉽게 익혀 자기 뜻을 적게 하려고","correct":true},{"t":"임금의 이름을 널리 뽐내려고","mis":"K4-2-u2-X08"},{"t":"다른 나라 글자를 모두 없애려고","mis":"K4-2-u2-X08"},{"t":"한자를 더 많이 외우게 하려고","mis":"K4-2-u2-X08"}],"explanation":["2·3번 줄의 어려움을 봐요.","뜻을 적지 못하는 백성이 많았어요.","누구나 쉽게 쓰게 하려고요."],"asset":{"type":"passage","lines":["1 한글이 생기기 전, 우리 조상은 중국 글자인 한자를 빌려 우리말을 적었어요.","2 한자는 글자 수가 매우 많아서 익히려면 오랜 시간이 걸렸어요.","3 그래서 자기 생각을 글로 적지 못하는 백성이 많았어요.","4 세종 대왕은 누구나 쉽게 익혀 쓰는 글자를 만들어 1446년에 널리 알렸어요.","5 그 이름이 「훈민정음」이에요."],"title":"「글자에 담긴 약속」 — 새 글자가 태어난 까닭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_basic#2','kor',4,2,'u2','L03','g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C12',1,'match','auto','기본 글자와 그 글자가 본뜬 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"K4-2-u2-C12","difficulty":1,"kind":"match","stem":"기본 글자와 그 글자가 본뜬 것을 알맞게 이으세요.","pairs":[{"l":"ㅁ","r":"입의 모양"},{"l":"ㅇ","r":"목구멍의 모양"},{"l":"ㅡ","r":"평평한 땅"},{"l":"ㅣ","r":"곧게 선 사람"}],"mis":"K4-2-u2-X09","explanation":["자음자는 소리 내는 몸이에요.","모음자는 하늘·땅·사람이에요.","하나씩 이어요."],"asset":{"type":"passage","lines":["자음자 ㅁ은 소리를 낼 때의 입 모양을 본떴어요.","자음자 ㅅ은 이의 모양을, ㅇ은 목구멍의 모양을 본떴어요.","모음자 ㆍ는 둥근 하늘을, ㅡ는 평평한 땅을 본떴어요.","ㅣ는 하늘과 땅 사이에 곧게 선 사람의 모습을 본떴어요."],"title":"「글자에 담긴 약속」 — 기본 글자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_basic#3','kor',4,2,'u2','L03','g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C13',1,'mc','auto','ㅁ → ㅂ → ㅍ 처럼 획이 늘면 소리는 어떻게 되나요?',ARRAY['K4-2-u2-X10']::text[],false,'{"seq":3,"concept":"K4-2-u2-C13","difficulty":1,"kind":"mc","stem":"ㅁ → ㅂ → ㅍ 처럼 획이 늘면 소리는 어떻게 되나요?","options":[{"t":"소리가 더 세진다","correct":true},{"t":"소리가 더 약해진다","mis":"K4-2-u2-X10"},{"t":"소리가 사라진다","mis":"K4-2-u2-X10"},{"t":"소리와 아무 상관이 없다","mis":"K4-2-u2-X10"}],"explanation":["획을 하나씩 더했어요.","첫 줄을 다시 읽어요.","소리가 더 세져요."],"asset":{"type":"passage","lines":["자음자는 기본 글자에 획을 더해 소리가 더 센 글자를 만들었어요.","ㅁ → ㅂ → ㅍ · ㅅ → ㅈ → ㅊ : 획이 하나씩 늘었어요.","모음자는 기본 글자를 합쳐 만들었어요."],"title":"「글자에 담긴 약속」 — 넓혀 만든 글자"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_basic#4','kor',4,2,'u2','L03','g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C15',1,'blank','auto','ㅣ 오른쪽에 ㆍ를 붙이면 (  )가 돼요. 빈칸에 알맞은 글자는 무엇인가요?',ARRAY['K4-2-u2-X11']::text[],false,'{"seq":4,"concept":"K4-2-u2-C15","difficulty":1,"kind":"blank","stem":"ㅣ 오른쪽에 ㆍ를 붙이면 (  )가 돼요. 빈칸에 알맞은 글자는 무엇인가요?","options":[{"t":"ㅏ","correct":true},{"t":"ㅜ","mis":"K4-2-u2-X11"},{"t":"ㅓ","mis":"K4-2-u2-X11"},{"t":"ㅗ","mis":"K4-2-u2-X11"}],"explanation":["ㅣ가 먼저예요.","오른쪽에 점이 붙어요.","ㅏ예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_basic#5','kor',4,2,'u2','L03','g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C13',2,'mc','auto','ㄴ에 획을 더하면 ㄷ이에요. ㄷ에 획을 하나 더 그으면 어떤 글자가 되나요?',ARRAY['K4-2-u2-X10']::text[],false,'{"seq":5,"concept":"K4-2-u2-C13","difficulty":2,"kind":"mc","stem":"ㄴ에 획을 더하면 ㄷ이에요. ㄷ에 획을 하나 더 그으면 어떤 글자가 되나요?","options":[{"t":"ㅌ","correct":true},{"t":"ㄹ","mis":"K4-2-u2-X10"},{"t":"ㅁ","mis":"K4-2-u2-X10"},{"t":"ㄱ","mis":"K4-2-u2-X10"}],"explanation":["ㅁ → ㅂ → ㅍ 를 떠올려요.","셋째 글자를 찾아요.","ㄴ → ㄷ → ㅌ 이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_basic#6','kor',4,2,'u2','L03','g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C14',2,'ox','auto','ㄹ은 ㄷ과 모양이 닮았으니 ㄷ에 획을 더해 만든 글자예요.',ARRAY['K4-2-u2-X10']::text[],false,'{"seq":6,"concept":"K4-2-u2-C14","difficulty":2,"kind":"ox","stem":"ㄹ은 ㄷ과 모양이 닮았으니 ㄷ에 획을 더해 만든 글자예요.","answer":"X","reason_options":[{"t":"모양이 닮았다고 모두 획을 더한 글자는 아니고, ㄷ에 획을 더한 글자는 ㅌ이기 때문에","correct":true},{"t":"닮은 글자끼리는 언제나 획을 더한 사이이기 때문에","mis":"K4-2-u2-X10"}],"mis":"K4-2-u2-X10","explanation":["ㄷ에 획을 더하면 ㅌ이에요.","ㄹ은 닮았을 뿐이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_basic#7','kor',4,2,'u2','L03','g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C16',2,'mc','auto','「ㅏ는 아기·나무·사과 어디에 쓰여도 대체로 같은 소리를 낸다」는 한글의 어떤 특성을 보여 주나요?',ARRAY['K4-2-u2-X12','K4-2-u2-X13']::text[],false,'{"seq":7,"concept":"K4-2-u2-C16","difficulty":2,"kind":"mc","stem":"「ㅏ는 아기·나무·사과 어디에 쓰여도 대체로 같은 소리를 낸다」는 한글의 어떤 특성을 보여 주나요?","options":[{"t":"소리와 글자가 짜임새 있게 이어져 배우기 쉽다","correct":true},{"t":"글자 모양이 모두 둥글다","mis":"K4-2-u2-X12"},{"t":"익혀야 할 글자가 아주 많다","mis":"K4-2-u2-X12"},{"t":"한 글자는 어디서나 예외 없이 똑같은 소리만 낸다","mis":"K4-2-u2-X13"}],"explanation":["「대체로」를 눈여겨봐요.","소리와 글자가 이어져요.","그래서 배우기 쉬워요."],"asset":{"type":"passage","lines":["비슷한 소리를 내는 글자는 모양도 닮았어요. ㅂ·ㅍ·ㅃ을 나란히 놓아 보세요.","ㅏ는 「아기」, 「나무」, 「사과」 어디에 쓰여도 대체로 같은 소리를 내요.","그래서 적은 수의 글자를 익히면 우리말을 두루 읽고 쓸 수 있어요."],"title":"「글자에 담긴 약속」 — 소리와 모양의 짜임"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_basic#8','kor',4,2,'u2','L03','g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C17',2,'mc','auto','「국물」이 [궁물]로 소리 나는 것을 보고 할 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u2-X14','K4-2-u2-X15','K4-2-u2-X13']::text[],false,'{"seq":8,"concept":"K4-2-u2-C17","difficulty":2,"kind":"mc","stem":"「국물」이 [궁물]로 소리 나는 것을 보고 할 알맞은 생각은 무엇인가요?","options":[{"t":"글자의 짜임은 그대로이고, 말소리가 이어지면서 소리가 바뀌기도 한다","correct":true},{"t":"규칙과 다르니 한글은 짜임새 없는 글자다","mis":"K4-2-u2-X14"},{"t":"앞으로 「궁물」이라고 소리대로 고쳐 적어야 한다","mis":"K4-2-u2-X15"},{"t":"국물만 특별한 말이고 다른 말은 모두 적힌 대로 소리 난다","mis":"K4-2-u2-X13"}],"explanation":["글자는 그대로예요.","소리가 이어지며 바뀌어요.","그래서 바른 발음도 익혀요."],"asset":{"type":"passage","lines":["글자는 「국물」인데 소리는 [궁물]로 나요.","친구 — 「한 글자는 한 소리라며? 그럼 한글은 규칙이 없는 글자네!」"],"title":"「국물」을 소리 내어 읽어 봐요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_basic#9','kor',4,2,'u2','L03','g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C18',2,'mc','auto','한글이 제일 좋다며 다른 나라 글자를 깎아내린 친구에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X16','K4-2-u2-X17','K4-2-u2-X23']::text[],false,'{"seq":9,"concept":"K4-2-u2-C18","difficulty":2,"kind":"mc","stem":"한글이 제일 좋다며 다른 나라 글자를 깎아내린 친구에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"다른 글자도 저마다 자기 말을 적어 왔어. 한글은 짜임새 있게 만든 점이 소중해.","correct":true},{"t":"맞아. 다른 나라 글자는 배울 필요가 없어.","mis":"K4-2-u2-X16"},{"t":"글자는 다 비슷하니까 한글도 자랑할 게 없어.","mis":"K4-2-u2-X17"},{"t":"한글은 쓰는 사람이 가장 많아서 제일 좋은 거야.","mis":"K4-2-u2-X23"}],"explanation":["깎아내리지 않아요.","낮추지도 않아요.","한글 자체의 짜임새가 소중해요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"한글이 제일 좋은 글자니까 다른 나라 글자는 모두 형편없어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_basic#10','kor',4,2,'u2','L03','g4_2_kor_u2_L03_basic','lesson_basic','K4-2-u2-C19',3,'mc','auto','「글자에 담긴 약속」에서 찾은 정보로 한글의 특성을 정리한 것 가운데 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X23','K4-2-u2-X12']::text[],false,'{"seq":10,"concept":"K4-2-u2-C19","difficulty":3,"kind":"mc","stem":"「글자에 담긴 약속」에서 찾은 정보로 한글의 특성을 정리한 것 가운데 알맞은 것은 무엇인가요?","options":[{"t":"기본 글자가 무엇을 본떴는지 알려져 있고, 획을 더하거나 합쳐 다른 글자를 만들었다","correct":true},{"t":"세상의 모든 소리를 한 글자도 틀림없이 적을 수 있다","mis":"K4-2-u2-X23"},{"t":"글자 모양이 모두 둥글어서 쓰기 쉽다","mis":"K4-2-u2-X12"},{"t":"익혀야 할 글자가 수만 개라서 꼼꼼하다","mis":"K4-2-u2-X12"}],"explanation":["글에 나온 것만 모아요.","본뜸과 더함을 찾아요.","부풀린 말은 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_challenge#1','kor',4,2,'u2','L03','g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C13',2,'sa','auto','ㅅ → ㅈ → (  ). 괄호에 들어갈 글자를 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u2-C13","difficulty":2,"kind":"sa","stem":"ㅅ → ㅈ → (  ). 괄호에 들어갈 글자를 쓰세요.","answer":["ㅊ"],"explanation":["획이 하나씩 늘어요.","ㅈ에 획을 하나 더해요.","ㅊ이에요."],"mis":"K4-2-u2-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_challenge#2','kor',4,2,'u2','L03','g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C12',2,'mc','auto','모음자의 기본 글자 ㆍ, ㅡ, ㅣ가 본뜬 것을 차례대로 쓴 것은 무엇인가요?',ARRAY['K4-2-u2-X09']::text[],false,'{"seq":2,"concept":"K4-2-u2-C12","difficulty":2,"kind":"mc","stem":"모음자의 기본 글자 ㆍ, ㅡ, ㅣ가 본뜬 것을 차례대로 쓴 것은 무엇인가요?","options":[{"t":"하늘 · 땅 · 사람","correct":true},{"t":"땅 · 하늘 · 사람","mis":"K4-2-u2-X09"},{"t":"입 · 이 · 목구멍","mis":"K4-2-u2-X09"},{"t":"사람 · 땅 · 하늘","mis":"K4-2-u2-X09"}],"explanation":["ㆍ는 둥글어요.","ㅡ는 평평해요.","ㅣ는 곧게 서 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_challenge#3','kor',4,2,'u2','L03','g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C16',3,'error','auto','한글이 짜임새 있는 글자인 까닭을 말했어요. 알맞지 않게 말한 친구는 누구인가요?',ARRAY['K4-2-u2-X12']::text[],false,'{"seq":3,"concept":"K4-2-u2-C16","difficulty":3,"kind":"error","stem":"한글이 짜임새 있는 글자인 까닭을 말했어요. 알맞지 않게 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「글자 수가 아주 많아서 무엇이든 적을 수 있기 때문이야.」","correct":true,"mis_target":"K4-2-u2-X12"},{"t":"친구 가 — 「비슷한 소리를 비슷한 모양으로 적기 때문이야.」","mis":"K4-2-u2-X12"},{"t":"친구 나 — 「적은 수의 글자를 익히면 우리말을 두루 읽고 쓸 수 있기 때문이야.」","mis":"K4-2-u2-X12"}],"explanation":["글자 수가 많은 건 한자였어요.","한글은 적은 글자로 두루 써요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_challenge#4','kor',4,2,'u2','L03','g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C14',3,'mc','auto','모양이 닮았지만 획을 더해 만든 사이가 아닌 짝은 무엇인가요?',ARRAY['K4-2-u2-X10']::text[],false,'{"seq":4,"concept":"K4-2-u2-C14","difficulty":3,"kind":"mc","stem":"모양이 닮았지만 획을 더해 만든 사이가 아닌 짝은 무엇인가요?","options":[{"t":"ㄷ과 ㄹ","correct":true},{"t":"ㅁ과 ㅂ","mis":"K4-2-u2-X10"},{"t":"ㅅ과 ㅈ","mis":"K4-2-u2-X10"},{"t":"ㄷ과 ㅌ","mis":"K4-2-u2-X10"}],"explanation":["ㅁ → ㅂ 은 획을 더했어요.","ㄷ → ㅌ 도 그래요.","ㄹ은 닮았을 뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_challenge#5','kor',4,2,'u2','L03','g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C17',3,'ox','auto','한글은 짜임새 있게 만든 글자이니 어떤 낱말에서도 언제나 적힌 대로만 소리 나요.',ARRAY['K4-2-u2-X13']::text[],false,'{"seq":5,"concept":"K4-2-u2-C17","difficulty":3,"kind":"ox","stem":"한글은 짜임새 있게 만든 글자이니 어떤 낱말에서도 언제나 적힌 대로만 소리 나요.","answer":"X","reason_options":[{"t":"「국물 → [궁물]」처럼 말소리가 이어지면 소리가 바뀌기도 하기 때문에","correct":true},{"t":"적힌 대로 소리 나지 않는 말은 잘못 적은 말이기 때문에","mis":"K4-2-u2-X13"}],"mis":"K4-2-u2-X13","explanation":["국물을 소리 내어 봐요.","[궁물]로 나요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_challenge#6','kor',4,2,'u2','L03','g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C17',3,'mc','auto','「먹는다」는 [멍는다]로 소리 나요. 이 말을 적는 법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X15','K4-2-u2-X02','K4-2-u2-X14']::text[],false,'{"seq":6,"concept":"K4-2-u2-C17","difficulty":3,"kind":"mc","stem":"「먹는다」는 [멍는다]로 소리 나요. 이 말을 적는 법으로 알맞은 것은 무엇인가요?","options":[{"t":"「먹다」에서 온 말임을 알아보게 「먹는다」로 적고, 소리만 [멍는다]로 낸다","correct":true},{"t":"소리 나는 대로 「멍는다」로 적는다","mis":"K4-2-u2-X15"},{"t":"어떻게 적어도 뜻은 같으니 아무렇게나 적는다","mis":"K4-2-u2-X02"},{"t":"소리가 바뀌니 한글로는 적을 수 없다","mis":"K4-2-u2-X14"}],"explanation":["「먹다 · 먹어 · 먹는다」를 나란히 봐요.","같은 모양이면 뜻이 보여요.","소리만 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_challenge#7','kor',4,2,'u2','L03','g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C18',3,'mc','auto','한글의 특성을 배운 뒤 다른 나라 글자를 대하는 생각으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X16','K4-2-u2-X17']::text[],false,'{"seq":7,"concept":"K4-2-u2-C18","difficulty":3,"kind":"mc","stem":"한글의 특성을 배운 뒤 다른 나라 글자를 대하는 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"한글의 소중함은 한글 자체의 짜임새에 있고, 다른 글자도 저마다 자기 말을 적어 왔다","correct":true},{"t":"한글보다 못한 글자는 배울 필요가 없다","mis":"K4-2-u2-X16"},{"t":"글자는 다 비슷하니 한글을 아낄 까닭이 없다","mis":"K4-2-u2-X17"},{"t":"다른 글자를 깎아내려야 한글이 빛난다","mis":"K4-2-u2-X16"}],"explanation":["두 끝을 조심해요.","깎아내리지 않아요.","한글을 낮추지도 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_challenge#8','kor',4,2,'u2','L03','g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C19',4,'mc','auto','새롭게 안 한글의 특성을 동생에게 설명한 말 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X16','K4-2-u2-X10','K4-2-u2-X13']::text[],false,'{"seq":8,"concept":"K4-2-u2-C19","difficulty":4,"kind":"mc","stem":"새롭게 안 한글의 특성을 동생에게 설명한 말 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"「ㅅ에 획을 하나 더하면 ㅈ, 또 하나 더하면 ㅊ이 돼. 획이 늘수록 소리가 세져서 몇 글자만 익혀도 다른 글자를 짐작하기 쉬워.」","correct":true},{"t":"「한글은 세계에서 제일 좋은 글자라서 다른 글자는 필요 없어.」","mis":"K4-2-u2-X16"},{"t":"「ㄹ은 ㄷ에 획을 더한 글자야. 닮았으니까.」","mis":"K4-2-u2-X10"},{"t":"「한글은 모든 낱말을 적힌 대로만 읽으면 돼.」","mis":"K4-2-u2-X13"}],"explanation":["예를 들었나요?","글에 나온 원리인가요?","부풀리지 않았나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_challenge#9','kor',4,2,'u2','L03','g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C11',4,'mc','auto','한글이 생기기 전 백성들이 겪은 어려움과 훈민정음의 관계를 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u2-X03','K4-2-u2-X08']::text[],false,'{"seq":9,"concept":"K4-2-u2-C11","difficulty":4,"kind":"mc","stem":"한글이 생기기 전 백성들이 겪은 어려움과 훈민정음의 관계를 바르게 말한 것은 무엇인가요?","options":[{"t":"한자는 익히기 어려워 뜻을 적지 못하는 백성이 많았고, 그래서 누구나 쉽게 익히는 글자를 만들었다","correct":true},{"t":"백성들이 말을 할 줄 몰라서 말 대신 쓸 글자를 만들었다","mis":"K4-2-u2-X03"},{"t":"한자가 너무 쉬워서 더 어려운 글자를 만들었다","mis":"K4-2-u2-X08"},{"t":"임금의 이름을 뽐내려고 글자를 만들었다","mis":"K4-2-u2-X08"}],"explanation":["어려움을 찾아요.","그 어려움을 풀려고 했어요.","누구나 쉽게예요."],"asset":{"type":"passage","lines":["1 한글이 생기기 전, 우리 조상은 중국 글자인 한자를 빌려 우리말을 적었어요.","2 한자는 글자 수가 매우 많아서 익히려면 오랜 시간이 걸렸어요.","3 그래서 자기 생각을 글로 적지 못하는 백성이 많았어요.","4 세종 대왕은 누구나 쉽게 익혀 쓰는 글자를 만들어 1446년에 널리 알렸어요.","5 그 이름이 「훈민정음」이에요."],"title":"「글자에 담긴 약속」 — 새 글자가 태어난 까닭"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L03_challenge#10','kor',4,2,'u2','L03','g4_2_kor_u2_L03_challenge','lesson_challenge','K4-2-u2-C17',4,'essay','teacher','친구가 「국물이 [궁물]로 소리 나니까 한글은 규칙이 없는 글자야.」라고 했어요. 「글자의 짜임」과 「말소리」라는 말을 넣어 해 줄 말을 쓰고, 그래서 우리가 함께 익혀야 할 것도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u2-C17","difficulty":4,"kind":"essay","stem":"친구가 「국물이 [궁물]로 소리 나니까 한글은 규칙이 없는 글자야.」라고 했어요. 「글자의 짜임」과 「말소리」라는 말을 넣어 해 줄 말을 쓰고, 그래서 우리가 함께 익혀야 할 것도 쓰세요.","answer_guide":{"answer":"예: 한글은 기본 글자를 본뜨고 획을 더해 만든 짜임새 있는 글자이고, 「국물」이라고 적어도 글자의 짜임은 그대로야. 다만 말소리가 이어지면서 [궁물]처럼 소리가 바뀌기도 하는 거야. 그래서 글자를 바르게 적는 것과 함께 바른 발음도 익혀야 해.","scoring_points":["「글자의 짜임」을 넣어 한글이 짜임새 있는 글자임을 말했는가","「말소리」가 이어지며 바뀌기도 한다고 설명했는가","바른 발음을 익혀야 한다고 썼는가"]},"explanation":["짜임은 그대로예요.","소리가 이어지며 바뀌어요.","바른 발음도 익혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_basic#1','kor',4,2,'u2','L05','g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C20',1,'mc','auto','국어사전을 만드는 사람, 다른 나라에서 한글을 가르치는 선생님, 외국어를 쉬운 우리말로 다듬는 사람의 공통점은 무엇인가요?',ARRAY['K4-2-u2-X20','K4-2-u2-X22','K4-2-u2-X21']::text[],false,'{"seq":1,"concept":"K4-2-u2-C20","difficulty":1,"kind":"mc","stem":"국어사전을 만드는 사람, 다른 나라에서 한글을 가르치는 선생님, 외국어를 쉬운 우리말로 다듬는 사람의 공통점은 무엇인가요?","options":[{"t":"우리말과 한글을 지키고 가꾸는 사람들이다","correct":true},{"t":"모두 유명한 사람이 되려고 일한다","mis":"K4-2-u2-X20"},{"t":"모두 외국어를 쓰지 않으려고 애쓴다","mis":"K4-2-u2-X22"},{"t":"모두 옛날 사람들만 할 수 있었던 일이다","mis":"K4-2-u2-X21"}],"explanation":["하는 일은 달라요.","모두 우리말과 한글을 위해요.","지키고 가꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_basic#2','kor',4,2,'u2','L05','g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C21',1,'mc','auto','조선어학회 사람들이 사전을 만들려고 한 까닭은 무엇인가요?',ARRAY['K4-2-u2-X20','K4-2-u2-X18']::text[],false,'{"seq":2,"concept":"K4-2-u2-C21","difficulty":1,"kind":"mc","stem":"조선어학회 사람들이 사전을 만들려고 한 까닭은 무엇인가요?","options":[{"t":"우리말이 사라지지 않도록 낱말과 뜻을 지키려고","correct":true},{"t":"사전을 많이 팔아 돈을 벌려고","mis":"K4-2-u2-X20"},{"t":"일본어를 더 쉽게 배우려고","mis":"K4-2-u2-X18"},{"t":"이름을 널리 알리려고","mis":"K4-2-u2-X20"}],"explanation":["1·2번 줄을 읽어요.","우리말을 쓰기 어려운 때였어요.","사라지지 않게 지키려고요."],"asset":{"type":"passage","lines":["1 일제 강점기에는 우리말을 마음껏 쓰기 어려운 때가 있었어요.","2 조선어학회 사람들은 우리말 낱말과 뜻을 모아 사전을 만들기로 했어요.","3 여러 해 동안 낱말을 모으고 뜻을 적어 사전 원고를 쌓아 갔어요.","4 1942년, 일본 경찰이 학회 사람들을 잡아가고 원고도 빼앗아 갔어요.","5 학회 사람들은 감옥에 갇혀 큰 고생을 했어요.","6 광복을 맞은 1945년 가을, 서울역의 한 창고에서 원고 뭉치가 다시 발견되었어요.","7 학회 사람들은 원고를 다시 다듬어 마침내 우리말 사전을 펴내기 시작했어요."],"title":"「원고 상자를 지킨 사람들」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_basic#3','kor',4,2,'u2','L05','g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C22',1,'match','auto','문장에 어울리는 낱말을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u2-C22","difficulty":1,"kind":"match","stem":"문장에 어울리는 낱말을 알맞게 이으세요.","pairs":[{"l":"1945년, 우리나라는 ○○을 맞았다","r":"광복"},{"l":"작가가 새 동화 ○○를 다 썼다","r":"원고"},{"l":"우리 반이 쓴 글을 모아 문집으로 ○○","r":"펴냈다"}],"mis":"K4-2-u2-X19","explanation":["나라를 되찾음은 광복이에요.","미리 쓴 글은 원고예요.","책을 내놓는 것은 펴내다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_basic#4','kor',4,2,'u2','L05','g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C21',1,'ox','auto','빼앗겼던 사전 원고는 모두 불에 타 버려 사전을 만들지 못했어요.',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":4,"concept":"K4-2-u2-C21","difficulty":1,"kind":"ox","stem":"빼앗겼던 사전 원고는 모두 불에 타 버려 사전을 만들지 못했어요.","answer":"X","reason_options":[{"t":"광복 뒤 서울역 창고에서 다시 발견되어 사전을 펴내는 데 쓰였기 때문에","correct":true},{"t":"빼앗긴 원고는 다시 찾을 수 없기 때문에","mis":"K4-2-u2-X18"}],"mis":"K4-2-u2-X18","explanation":["6번 줄을 읽어요.","창고에서 다시 찾았어요.","그래서 X예요."],"asset":{"type":"passage","lines":["1 일제 강점기에는 우리말을 마음껏 쓰기 어려운 때가 있었어요.","2 조선어학회 사람들은 우리말 낱말과 뜻을 모아 사전을 만들기로 했어요.","3 여러 해 동안 낱말을 모으고 뜻을 적어 사전 원고를 쌓아 갔어요.","4 1942년, 일본 경찰이 학회 사람들을 잡아가고 원고도 빼앗아 갔어요.","5 학회 사람들은 감옥에 갇혀 큰 고생을 했어요.","6 광복을 맞은 1945년 가을, 서울역의 한 창고에서 원고 뭉치가 다시 발견되었어요.","7 학회 사람들은 원고를 다시 다듬어 마침내 우리말 사전을 펴내기 시작했어요."],"title":"「원고 상자를 지킨 사람들」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_basic#5','kor',4,2,'u2','L05','g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C23',2,'match','auto','「원고 상자를 지킨 사람들」에서 일어난 일을 차례대로 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u2-C23","difficulty":2,"kind":"match","stem":"「원고 상자를 지킨 사람들」에서 일어난 일을 차례대로 이으세요.","pairs":[{"l":"① 처음","r":"우리말 낱말과 뜻을 모아 사전 원고를 쌓아 감"},{"l":"② 가운데","r":"경찰에게 원고를 빼앗기고 감옥에 갇힘"},{"l":"③ 끝","r":"서울역 창고에서 원고를 되찾아 사전을 펴내기 시작함"}],"mis":"K4-2-u2-X18","explanation":["1942년이 기준이에요.","1945년도 기준이에요.","모으기 → 빼앗김 → 되찾음이에요."],"asset":{"type":"passage","lines":["1 일제 강점기에는 우리말을 마음껏 쓰기 어려운 때가 있었어요.","2 조선어학회 사람들은 우리말 낱말과 뜻을 모아 사전을 만들기로 했어요.","3 여러 해 동안 낱말을 모으고 뜻을 적어 사전 원고를 쌓아 갔어요.","4 1942년, 일본 경찰이 학회 사람들을 잡아가고 원고도 빼앗아 갔어요.","5 학회 사람들은 감옥에 갇혀 큰 고생을 했어요.","6 광복을 맞은 1945년 가을, 서울역의 한 창고에서 원고 뭉치가 다시 발견되었어요.","7 학회 사람들은 원고를 다시 다듬어 마침내 우리말 사전을 펴내기 시작했어요."],"title":"「원고 상자를 지킨 사람들」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_basic#6','kor',4,2,'u2','L05','g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C24',2,'mc','auto','이 사람들의 행동에서 알 수 있는 마음은 무엇인가요?',ARRAY['K4-2-u2-X20','K4-2-u2-X22']::text[],false,'{"seq":6,"concept":"K4-2-u2-C24","difficulty":2,"kind":"mc","stem":"이 사람들의 행동에서 알 수 있는 마음은 무엇인가요?","options":[{"t":"우리말과 글을 잃지 않고 다음 사람들에게 물려주고 싶은 마음","correct":true},{"t":"이름을 널리 알려 유명해지고 싶은 마음","mis":"K4-2-u2-X20"},{"t":"다른 나라 말을 배우기 싫은 마음","mis":"K4-2-u2-X22"},{"t":"어려운 일은 빨리 그만두고 싶은 마음","mis":"K4-2-u2-X20"}],"explanation":["고생해도 멈추지 않았어요.","되찾은 원고를 다시 다듬었어요.","무엇을 소중히 여겼을까요?"],"asset":{"type":"passage","lines":["1 일제 강점기에는 우리말을 마음껏 쓰기 어려운 때가 있었어요.","2 조선어학회 사람들은 우리말 낱말과 뜻을 모아 사전을 만들기로 했어요.","3 여러 해 동안 낱말을 모으고 뜻을 적어 사전 원고를 쌓아 갔어요.","4 1942년, 일본 경찰이 학회 사람들을 잡아가고 원고도 빼앗아 갔어요.","5 학회 사람들은 감옥에 갇혀 큰 고생을 했어요.","6 광복을 맞은 1945년 가을, 서울역의 한 창고에서 원고 뭉치가 다시 발견되었어요.","7 학회 사람들은 원고를 다시 다듬어 마침내 우리말 사전을 펴내기 시작했어요."],"title":"「원고 상자를 지킨 사람들」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_basic#7','kor',4,2,'u2','L05','g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C25',2,'mc','auto','한글날의 처음 이름과 그 이름을 따온 곳을 알맞게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":7,"concept":"K4-2-u2-C25","difficulty":2,"kind":"mc","stem":"한글날의 처음 이름과 그 이름을 따온 곳을 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"「가갸날」 — 「가, 갸, 거, 겨……」 하고 글자를 익히던 모습","correct":true},{"t":"「세종날」 — 세종 대왕의 이름","mis":"K4-2-u2-X18"},{"t":"「가갸날」 — 가게 이름을 한글로 바꾼 날","mis":"K4-2-u2-X18"},{"t":"「훈민날」 — 훈민정음을 만든 해","mis":"K4-2-u2-X18"}],"explanation":["2번 줄을 봐요.","3번 줄도 봐요.","글자를 익히던 모습이에요."],"asset":{"type":"passage","lines":["1 1926년, 조선어연구회 사람들은 훈민정음을 기리는 날을 정했어요.","2 그 날의 처음 이름은 「가갸날」이었어요.","3 「가, 갸, 거, 겨……」 하고 글자를 익히던 모습에서 따온 이름이에요.","4 2년 뒤인 1928년에 이름을 「한글날」로 바꾸었어요.","5 오늘날 우리는 10월 9일을 한글날로 기념해요."],"title":"「한글날이 생긴 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_basic#8','kor',4,2,'u2','L05','g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C26',2,'mc','auto','「원고 상자를 지킨 사람들」과 「한글날이 생긴 날」 속 사람들의 공통점은 무엇인가요?',ARRAY['K4-2-u2-X52','K4-2-u2-X22']::text[],false,'{"seq":8,"concept":"K4-2-u2-C26","difficulty":2,"kind":"mc","stem":"「원고 상자를 지킨 사람들」과 「한글날이 생긴 날」 속 사람들의 공통점은 무엇인가요?","options":[{"t":"방법은 달라도 자기가 할 수 있는 일로 한글을 아꼈다","correct":true},{"t":"모두 사전을 만드는 일을 했다","mis":"K4-2-u2-X52"},{"t":"모두 외국어를 쓰는 사람을 꾸짖었다","mis":"K4-2-u2-X22"},{"t":"모두 감옥에 갇혀 고생을 했다","mis":"K4-2-u2-X52"}],"explanation":["한쪽은 사전 원고를 지켰어요.","한쪽은 기리는 날을 만들었어요.","방법은 달라도 같은 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_basic#9','kor',4,2,'u2','L05','g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C27',2,'mc','auto','두 친구에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X21','K4-2-u2-X22']::text[],false,'{"seq":9,"concept":"K4-2-u2-C27","difficulty":2,"kind":"mc","stem":"두 친구에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"한글 사랑은 대단한 일만도, 무엇을 금지하는 일만도 아니야. 내 생활에서 작은 것부터 할 수 있어.","correct":true},{"t":"첫째 친구 말이 맞아. 사전을 만들 수 없으면 할 일이 없어.","mis":"K4-2-u2-X21"},{"t":"둘째 친구 말이 맞아. 외국어는 한마디도 쓰면 안 돼.","mis":"K4-2-u2-X22"},{"t":"둘 다 맞으니 따로 할 일은 없어.","mis":"K4-2-u2-X21"}],"explanation":["두 끝을 조심해요.","대단한 일만이 아니에요.","금지하는 일도 아니에요."],"asset":{"type":"speech","turns":[{"who":"한 친구","text":"나는 사전을 만들 수도 없으니까 한글 사랑이랑은 상관없어."},{"who":"다른 친구","text":"한글을 사랑한다면 외국어는 한마디도 쓰면 안 돼."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_basic#10','kor',4,2,'u2','L05','g4_2_kor_u2_L05_basic','lesson_basic','K4-2-u2-C28',3,'error','auto','조선어학회 사람들에게 편지를 썼어요. 편지에 꼭 들어갈 것이 빠진 친구는 누구인가요?',ARRAY['K4-2-u2-X51']::text[],false,'{"seq":10,"concept":"K4-2-u2-C28","difficulty":3,"kind":"error","stem":"조선어학회 사람들에게 편지를 썼어요. 편지에 꼭 들어갈 것이 빠진 친구는 누구인가요?","options":[{"t":"친구 나 — 「정말 대단하세요! 멋져요!」","correct":true,"mis_target":"K4-2-u2-X51"},{"t":"친구 가 — 「원고를 되찾아 사전을 펴낸 이야기를 읽고 가슴이 뭉클했어요. 저는 모르는 낱말을 사전에서 찾아볼게요.」","mis":"K4-2-u2-X51"},{"t":"친구 다 — 「감옥에서 고생하신 이야기를 읽고 놀랐어요. 저는 받침까지 바르게 쓰도록 애쓸게요.」","mis":"K4-2-u2-X51"}],"explanation":["알게 된 일이 있나요?","내 다짐이 있나요?","친구 나는 칭찬 한마디뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_challenge#1','kor',4,2,'u2','L05','g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C22',2,'sa','auto','「빼앗긴 나라를 되찾음」을 뜻하는 낱말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u2-C22","difficulty":2,"kind":"sa","stem":"「빼앗긴 나라를 되찾음」을 뜻하는 낱말을 쓰세요.","answer":["광복"],"explanation":["1945년에 맞았어요.","나라를 되찾았어요.","‘광복’이에요."],"mis":"K4-2-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_challenge#2','kor',4,2,'u2','L05','g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C25',2,'mc','auto','「가갸날」을 정하고 몇 년 뒤에 「한글날」로 이름을 바꾸었나요?',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":2,"concept":"K4-2-u2-C25","difficulty":2,"kind":"mc","stem":"「가갸날」을 정하고 몇 년 뒤에 「한글날」로 이름을 바꾸었나요?","options":[{"t":"2년 뒤","correct":true},{"t":"1년 뒤","mis":"K4-2-u2-X18"},{"t":"5년 뒤","mis":"K4-2-u2-X18"},{"t":"480년 뒤","mis":"K4-2-u2-X18"}],"explanation":["1번 줄의 해를 봐요.","4번 줄의 해를 봐요.","1926년에서 1928년이에요."],"asset":{"type":"passage","lines":["1 1926년, 조선어연구회 사람들은 훈민정음을 기리는 날을 정했어요.","2 그 날의 처음 이름은 「가갸날」이었어요.","3 「가, 갸, 거, 겨……」 하고 글자를 익히던 모습에서 따온 이름이에요.","4 2년 뒤인 1928년에 이름을 「한글날」로 바꾸었어요.","5 오늘날 우리는 10월 9일을 한글날로 기념해요."],"title":"「한글날이 생긴 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_challenge#3','kor',4,2,'u2','L05','g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C23',3,'mc','auto','1942년과 1945년 가을 사이에 있었던 일을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":3,"concept":"K4-2-u2-C23","difficulty":3,"kind":"mc","stem":"1942년과 1945년 가을 사이에 있었던 일을 바르게 말한 것은 무엇인가요?","options":[{"t":"학회 사람들이 감옥에 갇혀 고생했고, 원고는 빼앗긴 채였다","correct":true},{"t":"원고를 다시 찾아 사전을 펴내기 시작했다","mis":"K4-2-u2-X18"},{"t":"학회 사람들이 처음으로 낱말을 모으기 시작했다","mis":"K4-2-u2-X18"},{"t":"「가갸날」을 「한글날」로 바꾸었다","mis":"K4-2-u2-X18"}],"explanation":["4·5번 줄을 봐요.","6번 줄은 1945년 가을이에요.","그 사이에는 빼앗긴 채였어요."],"asset":{"type":"passage","lines":["1 일제 강점기에는 우리말을 마음껏 쓰기 어려운 때가 있었어요.","2 조선어학회 사람들은 우리말 낱말과 뜻을 모아 사전을 만들기로 했어요.","3 여러 해 동안 낱말을 모으고 뜻을 적어 사전 원고를 쌓아 갔어요.","4 1942년, 일본 경찰이 학회 사람들을 잡아가고 원고도 빼앗아 갔어요.","5 학회 사람들은 감옥에 갇혀 큰 고생을 했어요.","6 광복을 맞은 1945년 가을, 서울역의 한 창고에서 원고 뭉치가 다시 발견되었어요.","7 학회 사람들은 원고를 다시 다듬어 마침내 우리말 사전을 펴내기 시작했어요."],"title":"「원고 상자를 지킨 사람들」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_challenge#4','kor',4,2,'u2','L05','g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C24',3,'mc','auto','잡혀가고 원고를 빼앗겨도 되찾은 원고를 다시 다듬어 사전을 펴냈다는 데서 알 수 있는 것은 무엇인가요?',ARRAY['K4-2-u2-X20','K4-2-u2-X22']::text[],false,'{"seq":4,"concept":"K4-2-u2-C24","difficulty":3,"kind":"mc","stem":"잡혀가고 원고를 빼앗겨도 되찾은 원고를 다시 다듬어 사전을 펴냈다는 데서 알 수 있는 것은 무엇인가요?","options":[{"t":"이 사람들이 우리말 사전을 무엇보다 소중하게 여겼다","correct":true},{"t":"사전 만드는 일이 아주 쉬웠다","mis":"K4-2-u2-X20"},{"t":"이름이 알려지기를 바랐다","mis":"K4-2-u2-X20"},{"t":"일본어를 쓰기 싫어서 사전을 만들었을 뿐이다","mis":"K4-2-u2-X22"}],"explanation":["쉬운 일이었을까요?","그래도 멈추지 않았어요.","그만큼 소중했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_challenge#5','kor',4,2,'u2','L05','g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C27',3,'ox','auto','한글을 사랑한다면 외국 노래는 절대 부르지 않아야 해요.',ARRAY['K4-2-u2-X22']::text[],false,'{"seq":5,"concept":"K4-2-u2-C27","difficulty":3,"kind":"ox","stem":"한글을 사랑한다면 외국 노래는 절대 부르지 않아야 해요.","answer":"X","reason_options":[{"t":"한글 사랑은 무엇을 금지하는 일이 아니라 우리말과 글을 아끼고 바르게 쓰려는 마음과 실천이기 때문에","correct":true},{"t":"외국어를 한마디라도 쓰면 한글이 사라지기 때문에","mis":"K4-2-u2-X22"}],"mis":"K4-2-u2-X22","explanation":["금지하는 일이 아니에요.","아끼고 바르게 써요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_challenge#6','kor',4,2,'u2','L05','g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C27',3,'error','auto','오늘의 내가 할 수 있는 한글 사랑을 말했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K4-2-u2-X21']::text[],false,'{"seq":6,"concept":"K4-2-u2-C27","difficulty":3,"kind":"error","stem":"오늘의 내가 할 수 있는 한글 사랑을 말했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 가 — 「나는 사전을 만들 수 없으니까 할 수 있는 일이 없어.」","correct":true,"mis_target":"K4-2-u2-X21"},{"t":"친구 나 — 「뜻을 모르는 말은 국어사전에서 찾아볼래.」","mis":"K4-2-u2-X21"},{"t":"친구 다 — 「동생에게 한글의 짜임새를 알려 줄래.」","mis":"K4-2-u2-X21"}],"explanation":["내 생활에서 할 수 있어요.","사전 찾기도 한글 사랑이에요.","친구 가가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_challenge#7','kor',4,2,'u2','L05','g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C26',3,'mc','auto','두 글의 사람들이 한 일을 견준 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X52','K4-2-u2-X22']::text[],false,'{"seq":7,"concept":"K4-2-u2-C26","difficulty":3,"kind":"mc","stem":"두 글의 사람들이 한 일을 견준 말로 알맞은 것은 무엇인가요?","options":[{"t":"한쪽은 우리말을 기록으로 남겼고, 다른 쪽은 한글의 소중함을 함께 되새기게 했다","correct":true},{"t":"두 글의 사람들은 똑같이 사전을 만들었다","mis":"K4-2-u2-X52"},{"t":"두 글의 사람들이 한 일은 서로 아무 관계가 없다","mis":"K4-2-u2-X52"},{"t":"두 글의 사람들은 모두 외국어를 쓰지 못하게 막았다","mis":"K4-2-u2-X22"}],"explanation":["한쪽은 원고예요.","한쪽은 기리는 날이에요.","방법은 달라도 한글을 아꼈어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_challenge#8','kor',4,2,'u2','L05','g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C21',4,'mc','auto','「원고 상자를 지킨 사람들」을 읽고 한 말 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X21','K4-2-u2-X18','K4-2-u2-X22']::text[],false,'{"seq":8,"concept":"K4-2-u2-C21","difficulty":4,"kind":"mc","stem":"「원고 상자를 지킨 사람들」을 읽고 한 말 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"「쓰기 어려운 때에도 낱말을 모아 지켰기에 오늘 우리가 사전을 쓸 수 있어. 지켜 가는 일은 이제 우리가 이어 갈 일이야.」","correct":true},{"t":"「옛날 대단한 사람들의 일이라 나와는 상관없어.」","mis":"K4-2-u2-X21"},{"t":"「원고를 빼앗긴 뒤 다시 찾지 못해서 사전은 끝내 나오지 않았어.」","mis":"K4-2-u2-X18"},{"t":"「그분들처럼 외국어를 쓰는 사람은 모두 꾸짖어야 해.」","mis":"K4-2-u2-X22"}],"explanation":["글의 내용과 맞나요?","나와 이어 생각했나요?","지켜 가는 일은 우리가 이어 가요."],"asset":{"type":"passage","lines":["1 일제 강점기에는 우리말을 마음껏 쓰기 어려운 때가 있었어요.","2 조선어학회 사람들은 우리말 낱말과 뜻을 모아 사전을 만들기로 했어요.","3 여러 해 동안 낱말을 모으고 뜻을 적어 사전 원고를 쌓아 갔어요.","4 1942년, 일본 경찰이 학회 사람들을 잡아가고 원고도 빼앗아 갔어요.","5 학회 사람들은 감옥에 갇혀 큰 고생을 했어요.","6 광복을 맞은 1945년 가을, 서울역의 한 창고에서 원고 뭉치가 다시 발견되었어요.","7 학회 사람들은 원고를 다시 다듬어 마침내 우리말 사전을 펴내기 시작했어요."],"title":"「원고 상자를 지킨 사람들」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_challenge#9','kor',4,2,'u2','L05','g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C20',4,'mc','auto','우리말과 한글을 지키고 가꾸는 사람을 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u2-X21','K4-2-u2-X22']::text[],false,'{"seq":9,"concept":"K4-2-u2-C20","difficulty":4,"kind":"mc","stem":"우리말과 한글을 지키고 가꾸는 사람을 바르게 말한 것은 무엇인가요?","options":[{"t":"사전을 만든 사람뿐 아니라 받침까지 살펴 바르게 쓰는 나도 한글을 가꾸는 사람이 될 수 있다","correct":true},{"t":"사전을 만들거나 감옥에 갈 만큼 큰일을 한 사람만 해당한다","mis":"K4-2-u2-X21"},{"t":"외국어를 한마디도 쓰지 않는 사람만 해당한다","mis":"K4-2-u2-X22"},{"t":"한글을 처음 만든 세종 대왕 한 사람뿐이다","mis":"K4-2-u2-X21"}],"explanation":["하는 일은 저마다 달라요.","나도 할 수 있어요.","바르게 쓰는 것도 가꾸는 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L05_challenge#10','kor',4,2,'u2','L05','g4_2_kor_u2_L05_challenge','lesson_challenge','K4-2-u2-C28',4,'essay','teacher','조선어학회 사람들이나 가갸날을 정한 사람들 가운데 한 모임에 편지를 쓰세요. 알게 된 일, 그때 든 생각, 앞으로 내가 할 한글 사랑을 차례대로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u2-C28","difficulty":4,"kind":"essay","stem":"조선어학회 사람들이나 가갸날을 정한 사람들 가운데 한 모임에 편지를 쓰세요. 알게 된 일, 그때 든 생각, 앞으로 내가 할 한글 사랑을 차례대로 쓰세요.","answer_guide":{"answer":"예: 조선어학회 어른들께. 원고를 빼앗기고 감옥에서 고생하시면서도 광복 뒤 되찾은 원고를 다시 다듬어 사전을 펴내셨다는 이야기를 읽었어요. 우리말이 사라질 뻔했다는 것이 무섭고, 끝까지 지켜 주셔서 정말 고마웠어요. 저는 모르는 낱말을 사전에서 찾아보고, 받침까지 바르게 쓰도록 애쓸게요.","scoring_points":["알게 된 일을 썼는가","그때 든 생각을 썼는가","앞으로 내가 할 한글 사랑을 구체적으로 썼는가"]},"explanation":["누구에게 쓰는지 밝혀요.","알게 된 일 → 생각이에요.","내 다짐으로 마무리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_basic#1','kor',4,2,'u2','L07','g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C30',1,'mc','auto','자료 ㉮에서 우리말 사용과 관련한 문제점은 무엇인가요?',ARRAY['K4-2-u2-X29','K4-2-u2-X24','K4-2-u2-X25']::text[],false,'{"seq":1,"concept":"K4-2-u2-C30","difficulty":1,"kind":"mc","stem":"자료 ㉮에서 우리말 사용과 관련한 문제점은 무엇인가요?","options":[{"t":"우리말로 쓸 수 있는데도 외국어를 지나치게 썼다","correct":true},{"t":"글자 크기가 너무 작다","mis":"K4-2-u2-X29"},{"t":"외국어가 한 글자라도 있으면 모두 틀린 글이다","mis":"K4-2-u2-X24"},{"t":"외국어를 더 많이 쓰면 멋진 안내문이 된다","mis":"K4-2-u2-X25"}],"explanation":["우리말로 바꿔 읽어 봐요.","「어린이 방 이용 규칙」이 돼요.","쓸 수 있는 우리말이 있었어요."],"asset":{"type":"passage","lines":["키즈 룸 이용 룰","· 오픈 타임: 오전 10시","· 룸 안에서는 슈즈를 벗어 주세요"],"title":"자료 ㉮ 아파트 게시판 안내문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_basic#2','kor',4,2,'u2','L07','g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C32',1,'mc','auto','시윤이와 할머니 사이에서 생긴 문제는 무엇인가요?',ARRAY['K4-2-u2-X26','K4-2-u2-X27','K4-2-u2-X29']::text[],false,'{"seq":2,"concept":"K4-2-u2-C32","difficulty":1,"kind":"mc","stem":"시윤이와 할머니 사이에서 생긴 문제는 무엇인가요?","options":[{"t":"할머니가 모르시는 줄임말을 써서 뜻이 잘못 전해졌다","correct":true},{"t":"할머니가 선물을 잘못 보내셨다","mis":"K4-2-u2-X26"},{"t":"줄임말은 친구끼리도 절대 쓰면 안 된다","mis":"K4-2-u2-X27"},{"t":"시윤이가 글씨를 틀리게 썼다","mis":"K4-2-u2-X29"}],"explanation":["「생선」은 생일 선물이에요.","할머니는 물고기로 알아들으셨어요.","누구에게 썼는지 봐요."],"asset":{"type":"speech","turns":[{"who":"시윤","text":"할머니, 보내 주신 생선 너무 고마워요!"},{"who":"할머니","text":"생선? 할미는 운동화를 보냈는데, 누가 생선을 보냈니?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_basic#3','kor',4,2,'u2','L07','g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C33',1,'mc','auto','자료 ㉰의 말을 들은 친구에게 생길 일로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X28']::text[],false,'{"seq":3,"concept":"K4-2-u2-C33","difficulty":1,"kind":"mc","stem":"자료 ㉰의 말을 들은 친구에게 생길 일로 알맞은 것은 무엇인가요?","options":[{"t":"마음이 상하고 친구와 사이가 멀어질 수 있다","correct":true},{"t":"놀이 중이니 장난으로 웃고 넘긴다","mis":"K4-2-u2-X28"},{"t":"공을 더 잘 차고 싶어 힘이 난다","mis":"K4-2-u2-X28"},{"t":"아무 일도 생기지 않는다","mis":"K4-2-u2-X28"}],"explanation":["고개를 푹 숙였어요.","마음이 어땠을까요?","거친 말은 마음을 다치게 해요."],"asset":{"type":"passage","lines":["공을 놓친 친구에게 한 친구가 (친구를 깎아내리는 거친 말)을 내뱉었어요.","공을 놓친 친구는 고개를 푹 숙였어요."],"title":"자료 ㉰ 공놀이를 하다가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_basic#4','kor',4,2,'u2','L07','g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C34',1,'match','auto','외국어와 그 말을 다듬은 우리말을 알맞게 이으세요.','{}'::text[],false,'{"seq":4,"concept":"K4-2-u2-C34","difficulty":1,"kind":"match","stem":"외국어와 그 말을 다듬은 우리말을 알맞게 이으세요.","pairs":[{"l":"스크린 도어","r":"안전문"},{"l":"내비게이션","r":"길도우미"},{"l":"홈페이지","r":"누리집"}],"mis":"K4-2-u2-X19","explanation":["승강장의 문이에요.","길을 도와줘요.","누리의 집이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_basic#5','kor',4,2,'u2','L07','g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C31',2,'mc','auto','이 친구의 물음에 알맞은 답은 무엇인가요?',ARRAY['K4-2-u2-X24','K4-2-u2-X25']::text[],false,'{"seq":5,"concept":"K4-2-u2-C31","difficulty":2,"kind":"mc","stem":"이 친구의 물음에 알맞은 답은 무엇인가요?","options":[{"t":"바꿔 쓸 알맞은 우리말 없이 굳은 말은 써도 된다. 우리말이 있는데 외국어를 남용하는 것이 문제다","correct":true},{"t":"모두 새 우리말을 지어 바꿔 불러야 한다","mis":"K4-2-u2-X24"},{"t":"외국어는 멋지니 많이 쓸수록 좋다","mis":"K4-2-u2-X25"},{"t":"외국에서 온 말은 절대 쓰면 안 된다","mis":"K4-2-u2-X24"}],"explanation":["「키즈 룸」과 「버스」를 견줘요.","바꿔 쓸 우리말이 있나요?","굳은 말은 괜찮아요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"그럼 버스, 피아노도 외국에서 온 말이니까 이제부터 쓰면 안 되는 거야?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_basic#6','kor',4,2,'u2','L07','g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C29',2,'mc','auto','우리말을 바르게 써야 하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X29','K4-2-u2-X24']::text[],false,'{"seq":6,"concept":"K4-2-u2-C29","difficulty":2,"kind":"mc","stem":"우리말을 바르게 써야 하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"누구와도 뜻이 정확하게 통하고 서로의 마음을 지킬 수 있다","correct":true},{"t":"글씨가 예뻐 보이기 때문이다","mis":"K4-2-u2-X29"},{"t":"받아쓰기 점수를 잘 받기 위해서만이다","mis":"K4-2-u2-X29"},{"t":"외국어는 모두 나쁜 말이기 때문이다","mis":"K4-2-u2-X24"}],"explanation":["할머니와의 문자를 떠올려요.","공놀이 장면도 떠올려요.","뜻과 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_basic#7','kor',4,2,'u2','L07','g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C32',2,'ox','auto','줄임말은 친구끼리도 절대 쓰면 안 돼요.',ARRAY['K4-2-u2-X27']::text[],false,'{"seq":7,"concept":"K4-2-u2-C32","difficulty":2,"kind":"ox","stem":"줄임말은 친구끼리도 절대 쓰면 안 돼요.","answer":"X","reason_options":[{"t":"줄임말은 듣는 사람이 알아듣는지와 상황을 살펴서 쓰면 되기 때문에","correct":true},{"t":"줄임말은 모두 바르지 않은 말이기 때문에","mis":"K4-2-u2-X27"}],"mis":"K4-2-u2-X27","explanation":["누구에게 쓰는지가 중요해요.","알아듣는 친구도 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_basic#8','kor',4,2,'u2','L07','g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C29',2,'blank','auto','우리말은 조상에게서 이어받아 다음 사람에게 물려줄 (  )이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['K4-2-u2-X25','K4-2-u2-X26','K4-2-u2-X29']::text[],false,'{"seq":8,"concept":"K4-2-u2-C29","difficulty":2,"kind":"blank","stem":"우리말은 조상에게서 이어받아 다음 사람에게 물려줄 (  )이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"유산","correct":true},{"t":"외국어","mis":"K4-2-u2-X25"},{"t":"줄임말","mis":"K4-2-u2-X26"},{"t":"규칙표","mis":"K4-2-u2-X29"}],"explanation":["이어받아요.","물려줘요.","‘유산’이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_basic#9','kor',4,2,'u2','L07','g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C30',2,'mc','auto','「룸 안에서는 슈즈를 벗어 주세요」를 우리말로 바르게 고친 것은 무엇인가요?',ARRAY['K4-2-u2-X25']::text[],false,'{"seq":9,"concept":"K4-2-u2-C30","difficulty":2,"kind":"mc","stem":"「룸 안에서는 슈즈를 벗어 주세요」를 우리말로 바르게 고친 것은 무엇인가요?","options":[{"t":"「방 안에서는 신발을 벗어 주세요」","correct":true},{"t":"「룸 안에서는 신발을 벗어 주세요」","mis":"K4-2-u2-X25"},{"t":"「방 안에서는 슈즈를 벗어 주세요」","mis":"K4-2-u2-X25"},{"t":"「ROOM 안에서는 SHOES를 벗어 주세요」","mis":"K4-2-u2-X25"}],"explanation":["룸은 방이에요.","슈즈는 신발이에요.","둘 다 바꿔요."],"asset":{"type":"passage","lines":["키즈 룸 이용 룰","· 오픈 타임: 오전 10시","· 룸 안에서는 슈즈를 벗어 주세요"],"title":"자료 ㉮ 아파트 게시판 안내문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_basic#10','kor',4,2,'u2','L07','g4_2_kor_u2_L07_basic','lesson_basic','K4-2-u2-C31',3,'error','auto','외국어 사용에 대해 말했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K4-2-u2-X24']::text[],false,'{"seq":10,"concept":"K4-2-u2-C31","difficulty":3,"kind":"error","stem":"외국어 사용에 대해 말했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 다 — 「피아노는 외국에서 온 말이니까 이제부터 다른 말로 바꿔 불러야 해.」","correct":true,"mis_target":"K4-2-u2-X24"},{"t":"친구 가 — 「‘키즈 룸’은 ‘어린이 방’으로 바꿔 쓸 수 있어.」","mis":"K4-2-u2-X24"},{"t":"친구 나 — 「‘버스’는 바꿔 쓸 알맞은 우리말이 없이 굳은 말이야.」","mis":"K4-2-u2-X24"}],"explanation":["피아노는 굳은 말이에요.","바꿔 쓸 우리말이 마땅치 않아요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_challenge#1','kor',4,2,'u2','L07','g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C34',2,'sa','auto','「홈페이지」를 다듬은 우리말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u2-C34","difficulty":2,"kind":"sa","stem":"「홈페이지」를 다듬은 우리말을 쓰세요.","answer":["누리집"],"explanation":["누리는 세상이에요.","세상의 집이에요.","‘누리집’이에요."],"mis":"K4-2-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_challenge#2','kor',4,2,'u2','L07','g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C32',2,'mc','auto','지아는 「수학 익힘책」을 줄여 「수익」이라고 썼어요. 할머니께 어떻게 말하면 좋았을까요?',ARRAY['K4-2-u2-X26','K4-2-u2-X27']::text[],false,'{"seq":2,"concept":"K4-2-u2-C32","difficulty":2,"kind":"mc","stem":"지아는 「수학 익힘책」을 줄여 「수익」이라고 썼어요. 할머니께 어떻게 말하면 좋았을까요?","options":[{"t":"「할머니, 오늘 수학 익힘책 숙제 다 했어요!」","correct":true},{"t":"「할머니, 오늘 수익 다 했어요!」라고 더 크게 말한다","mis":"K4-2-u2-X26"},{"t":"할머니가 줄임말을 배우셔야 하니 그대로 쓴다","mis":"K4-2-u2-X26"},{"t":"줄임말은 나쁘니 친구에게도 절대 쓰지 않겠다고 다짐한다","mis":"K4-2-u2-X27"}],"explanation":["할머니는 수익을 모르세요.","풀어 써야 통해요.","듣는 사람을 살펴요."],"asset":{"type":"speech","turns":[{"who":"지아","text":"할머니, 오늘 수익 다 했어요!"},{"who":"할머니","text":"수익? 우리 지아가 장사라도 했니?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_challenge#3','kor',4,2,'u2','L07','g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C30',3,'mc','auto','문구점 안내문을 고칠 때 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u2-X24','K4-2-u2-X25']::text[],false,'{"seq":3,"concept":"K4-2-u2-C30","difficulty":3,"kind":"mc","stem":"문구점 안내문을 고칠 때 알맞은 생각은 무엇인가요?","options":[{"t":"「뉴 아이템」·「오픈 기념 세일」은 우리말로 바꿔 쓰고, 「펜」은 굳은 말이라 그대로 둔다","correct":true},{"t":"「펜」까지 모두 새 우리말을 지어 바꾼다","mis":"K4-2-u2-X24"},{"t":"외국어가 많을수록 멋지니 그대로 둔다","mis":"K4-2-u2-X25"},{"t":"외국어가 한 글자라도 있으니 안내문을 떼어 낸다","mis":"K4-2-u2-X24"}],"explanation":["바꿔 쓸 우리말이 있나요?","「뉴 아이템」은 새 물건이에요.","「펜」은 굳은 말이에요."],"asset":{"type":"passage","lines":["뉴 아이템 입고!","오픈 기념 세일 — 모든 펜 할인"],"title":"학교 앞 문구점 안내문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_challenge#4','kor',4,2,'u2','L07','g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C29',3,'mc','auto','할머니와의 문자, 공놀이 장면, 아파트 안내문을 함께 보고 알 수 있는 것은 무엇인가요?',ARRAY['K4-2-u2-X29','K4-2-u2-X24','K4-2-u2-X25']::text[],false,'{"seq":4,"concept":"K4-2-u2-C29","difficulty":3,"kind":"mc","stem":"할머니와의 문자, 공놀이 장면, 아파트 안내문을 함께 보고 알 수 있는 것은 무엇인가요?","options":[{"t":"바른 우리말은 뜻을 통하게 하고, 마음을 지키고, 우리말을 가꾼다","correct":true},{"t":"세 장면 모두 글씨를 예쁘게 쓰면 해결된다","mis":"K4-2-u2-X29"},{"t":"세 장면 모두 외국어 때문에 생긴 문제다","mis":"K4-2-u2-X24"},{"t":"세 장면 모두 아무 문제가 없다","mis":"K4-2-u2-X25"}],"explanation":["문자는 뜻이 안 통했어요.","공놀이는 마음이 다쳤어요.","안내문은 우리말을 아끼지 않았어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_challenge#5','kor',4,2,'u2','L07','g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C33',3,'ox','auto','놀이 중에 한 거친 말은 장난이니 괜찮아요.',ARRAY['K4-2-u2-X28']::text[],false,'{"seq":5,"concept":"K4-2-u2-C33","difficulty":3,"kind":"ox","stem":"놀이 중에 한 거친 말은 장난이니 괜찮아요.","answer":"X","reason_options":[{"t":"장난이라도 듣는 친구의 마음을 다치게 하고 사이를 멀어지게 하기 때문에","correct":true},{"t":"놀이할 때는 말을 가리지 않아도 되기 때문에","mis":"K4-2-u2-X28"}],"mis":"K4-2-u2-X28","explanation":["고개 숙인 친구를 떠올려요.","장난이어도 마음이 다쳐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_challenge#6','kor',4,2,'u2','L07','g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C32',3,'error','auto','줄임말을 쓴 장면이에요. 알맞지 않게 쓴 친구는 누구인가요?',ARRAY['K4-2-u2-X26','K4-2-u2-X27']::text[],false,'{"seq":6,"concept":"K4-2-u2-C32","difficulty":3,"kind":"error","stem":"줄임말을 쓴 장면이에요. 알맞지 않게 쓴 친구는 누구인가요?","options":[{"t":"친구 다 — 줄임말을 모르시는 할아버지께 「생선 고마워요!」라고 문자를 보냈다","correct":true,"mis_target":"K4-2-u2-X26"},{"t":"친구 가 — 할머니께 「생일 선물 고마워요!」라고 풀어 썼다","mis":"K4-2-u2-X26"},{"t":"친구 나 — 뜻을 아는 짝에게 「수익 몇 쪽까지야?」라고 물었다","mis":"K4-2-u2-X27"}],"explanation":["누구에게 보냈나요?","할아버지는 모르세요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_challenge#7','kor',4,2,'u2','L07','g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C34',3,'mc','auto','외국어를 다듬은 우리말을 찾아볼 수 있는 곳으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X25','K4-2-u2-X26','K4-2-u2-X24']::text[],false,'{"seq":7,"concept":"K4-2-u2-C34","difficulty":3,"kind":"mc","stem":"외국어를 다듬은 우리말을 찾아볼 수 있는 곳으로 알맞은 것은 무엇인가요?","options":[{"t":"국립국어원 누리집에 모아 둔 다듬은 말","correct":true},{"t":"외국어가 많이 쓰인 가게 간판","mis":"K4-2-u2-X25"},{"t":"친구들끼리 새로 지어낸 줄임말 목록","mis":"K4-2-u2-X26"},{"t":"아무 낱말이나 우리말처럼 바꾸어 본 내 공책","mis":"K4-2-u2-X24"}],"explanation":["다듬은 말을 모은 곳이에요.","믿을 수 있는 곳이에요.","국립국어원 누리집이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_challenge#8','kor',4,2,'u2','L07','g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C31',4,'mc','auto','외국어 사용을 두고 한 말 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X24','K4-2-u2-X25']::text[],false,'{"seq":8,"concept":"K4-2-u2-C31","difficulty":4,"kind":"mc","stem":"외국어 사용을 두고 한 말 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"「‘오픈 타임’은 ‘여는 시간’으로 바꿔 쓸 수 있지만, ‘버스’처럼 굳은 말은 써도 돼. 우리말이 있는데도 외국어를 지나치게 쓰는 게 문제야.」","correct":true},{"t":"「외국어는 무조건 나쁘니까 버스도 바꿔야 해.」","mis":"K4-2-u2-X24"},{"t":"「외국어가 많을수록 멋있으니 안내문은 외국어로 쓰자.」","mis":"K4-2-u2-X25"},{"t":"「‘오픈 타임’도 ‘버스’처럼 굳은 말이니 그대로 쓰자.」","mis":"K4-2-u2-X25"}],"explanation":["바꿀 수 있는 말을 찾아요.","굳은 말은 그대로 둬요.","남용이 문제예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_challenge#9','kor',4,2,'u2','L07','g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C32',4,'mc','auto','줄임말을 쓸 때 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u2-X27','K4-2-u2-X26','K4-2-u2-X25']::text[],false,'{"seq":9,"concept":"K4-2-u2-C32","difficulty":4,"kind":"mc","stem":"줄임말을 쓸 때 알맞은 생각은 무엇인가요?","options":[{"t":"듣는 사람이 그 뜻을 아는지와 상황을 살펴, 모를 수 있는 사람에게는 풀어 쓴다","correct":true},{"t":"줄임말은 어디서든 절대 쓰지 않는다","mis":"K4-2-u2-X27"},{"t":"내가 아는 줄임말은 누구에게나 써도 된다","mis":"K4-2-u2-X26"},{"t":"줄임말을 많이 알수록 우리말을 잘 쓰는 것이다","mis":"K4-2-u2-X25"}],"explanation":["듣는 사람을 봐요.","상황을 봐요.","모를 수 있으면 풀어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L07_challenge#10','kor',4,2,'u2','L07','g4_2_kor_u2_L07_challenge','lesson_challenge','K4-2-u2-C29',4,'essay','teacher','학교 앞 문구점 안내문을 우리말을 살려 고쳐 쓰고, 우리말을 바르게 써야 하는 까닭 두 가지를 쓰세요. 그대로 둔 말이 있다면 왜 그대로 두었는지도 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u2-C29","difficulty":4,"kind":"essay","stem":"학교 앞 문구점 안내문을 우리말을 살려 고쳐 쓰고, 우리말을 바르게 써야 하는 까닭 두 가지를 쓰세요. 그대로 둔 말이 있다면 왜 그대로 두었는지도 쓰세요.","answer_guide":{"answer":"예: 「새 물건 들어옴! 문 연 기념 할인 — 모든 펜 값을 깎아 드려요」로 고친다. 우리말을 바르게 쓰면 어린이부터 할머니까지 누구나 뜻을 정확하게 알 수 있고, 조상에게서 이어받은 우리말을 아끼고 가꿀 수 있다. 「펜」은 바꿔 쓸 알맞은 우리말이 없이 굳은 말이라 그대로 두었다.","scoring_points":["안내문을 우리말을 살려 고쳐 썼는가","바르게 써야 하는 까닭 두 가지를 썼는가","그대로 둔 굳은 말과 그 까닭을 썼는가"]},"explanation":["바꿀 수 있는 말을 바꿔요.","까닭은 뜻·마음·가꾸기예요.","굳은 말은 그대로 둬요."],"asset":{"type":"passage","lines":["뉴 아이템 입고!","오픈 기념 세일 — 모든 펜 할인"],"title":"학교 앞 문구점 안내문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_basic#1','kor',4,2,'u2','L08','g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C35',1,'mc','auto','「보고」를 바르게 설명한 것은 무엇인가요?',ARRAY['K4-2-u2-X30','K4-2-u2-X35','K4-2-u2-X41']::text[],false,'{"seq":1,"concept":"K4-2-u2-C35","difficulty":1,"kind":"mc","stem":"「보고」를 바르게 설명한 것은 무엇인가요?","options":[{"t":"알아보거나 한 일의 과정과 결과를 있는 그대로 알리는 것","correct":true},{"t":"내 생각만 재미있게 꾸며 알리는 것","mis":"K4-2-u2-X30"},{"t":"들은 이야기를 부풀려 알리는 것","mis":"K4-2-u2-X35"},{"t":"조사하지 않은 일을 짐작해 알리는 것","mis":"K4-2-u2-X41"}],"explanation":["강낭콩 관찰 발표를 떠올려요.","과정과 결과예요.","있는 그대로 알려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_basic#2','kor',4,2,'u2','L08','g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C36',1,'mc','auto','보민이는 무엇을 조사해 보고하는 글을 썼나요?',ARRAY['K4-2-u2-X30']::text[],false,'{"seq":2,"concept":"K4-2-u2-C36","difficulty":1,"kind":"mc","stem":"보민이는 무엇을 조사해 보고하는 글을 썼나요?","options":[{"t":"우리 반 친구들이 고맙다는 말을 하는 정도와 때","correct":true},{"t":"급식에 나오는 반찬의 종류","mis":"K4-2-u2-X30"},{"t":"국어사전에 실린 낱말의 수","mis":"K4-2-u2-X30"},{"t":"선생님께서 하루에 하시는 말의 수","mis":"K4-2-u2-X30"}],"explanation":["제목을 봐요.","조사 동기를 봐요.","고맙다는 말이에요."],"asset":{"type":"passage","lines":["조사 대상 — 4학년 ○반 학생 24명","조사 동기 — 급식 때 고맙다고 말하는 친구가 적어 보여서 알고 싶었다.","조사 방법 — 설문 조사, 면담 조사, 사전 찾아보기","설문 — 하루 한 번 이상 9명 · 가끔 11명 · 거의 안 한다 4명","가장 많이 말하는 때 — 물건 빌려줄 때 12명 · 가족 6명 · 급식 4명 · 선생님 2명","면담 — 거의 안 한다는 세 명: 「쑥스러워서」 「알 것 같아서」 「깜빡 잊어서」","조사 소감 — 생각보다 적어서 놀랐다. 내가 먼저 말해 보아야겠다.","출처 — 국립국어원, 「표준국어대사전」 누리집, 「고맙다」"],"title":"보민이의 보고하는 글 「우리 반 친구들의 ‘고마워’ 말하기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_basic#3','kor',4,2,'u2','L08','g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C38',1,'match','auto','보민이의 조사 방법과 그 방법으로 알아낸 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":3,"concept":"K4-2-u2-C38","difficulty":1,"kind":"match","stem":"보민이의 조사 방법과 그 방법으로 알아낸 것을 알맞게 이으세요.","pairs":[{"l":"설문 조사","r":"고맙다고 말하는 친구의 수"},{"l":"면담 조사","r":"고맙다고 말하지 않는 까닭"},{"l":"사전 찾아보기","r":"「고맙다」의 뜻"}],"mis":"K4-2-u2-X33","explanation":["몇 명은 여럿에게 물어요.","까닭은 직접 물어요.","뜻은 사전에서 찾아요."],"asset":{"type":"passage","lines":["조사 대상 — 4학년 ○반 학생 24명","조사 동기 — 급식 때 고맙다고 말하는 친구가 적어 보여서 알고 싶었다.","조사 방법 — 설문 조사, 면담 조사, 사전 찾아보기","설문 — 하루 한 번 이상 9명 · 가끔 11명 · 거의 안 한다 4명","가장 많이 말하는 때 — 물건 빌려줄 때 12명 · 가족 6명 · 급식 4명 · 선생님 2명","면담 — 거의 안 한다는 세 명: 「쑥스러워서」 「알 것 같아서」 「깜빡 잊어서」","조사 소감 — 생각보다 적어서 놀랐다. 내가 먼저 말해 보아야겠다.","출처 — 국립국어원, 「표준국어대사전」 누리집, 「고맙다」"],"title":"보민이의 보고하는 글 「우리 반 친구들의 ‘고마워’ 말하기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_basic#4','kor',4,2,'u2','L08','g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C42',1,'ox','auto','누리집에서 찾은 낱말 뜻은 출처를 쓰지 않고 내 말처럼 옮겨도 돼요.',ARRAY['K4-2-u2-X37']::text[],false,'{"seq":4,"concept":"K4-2-u2-C42","difficulty":1,"kind":"ox","stem":"누리집에서 찾은 낱말 뜻은 출처를 쓰지 않고 내 말처럼 옮겨도 돼요.","answer":"X","reason_options":[{"t":"옮겨 온 자료는 누가 만든 어떤 자료인지 출처를 밝혀야 하기 때문에","correct":true},{"t":"사전에 있는 뜻은 누구나 아니까 출처가 필요 없기 때문에","mis":"K4-2-u2-X37"}],"mis":"K4-2-u2-X37","explanation":["남이 만든 자료예요.","어디서 왔는지 밝혀요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_basic#5','kor',4,2,'u2','L08','g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C39',2,'mc','auto','면담 조사를 할 때 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X34']::text[],false,'{"seq":5,"concept":"K4-2-u2-C39","difficulty":2,"kind":"mc","stem":"면담 조사를 할 때 알맞은 것은 무엇인가요?","options":[{"t":"물어볼 질문을 미리 적어 가고, 들은 말을 그대로 적는다","correct":true},{"t":"친구가 말하는 도중에 끼어들어 내 생각을 말한다","mis":"K4-2-u2-X34"},{"t":"대답이 마음에 들지 않으면 알맞게 바꾸어 적는다","mis":"K4-2-u2-X34"},{"t":"질문은 준비하지 않고 떠오르는 대로 묻는다","mis":"K4-2-u2-X34"}],"explanation":["미리 준비해요.","끝까지 들어요.","들은 그대로 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_basic#6','kor',4,2,'u2','L08','g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C38',2,'mc','auto','조사 방법을 다섯 가지 다 쓰겠다는 친구에게 해 줄 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X31','K4-2-u2-X32','K4-2-u2-X33']::text[],false,'{"seq":6,"concept":"K4-2-u2-C38","difficulty":2,"kind":"mc","stem":"조사 방법을 다섯 가지 다 쓰겠다는 친구에게 해 줄 말로 알맞은 것은 무엇인가요?","options":[{"t":"알아내려는 내용에 맞는 방법을 골라야 해. 많다고 더 좋은 건 아니야.","correct":true},{"t":"맞아. 방법이 많을수록 좋은 보고서야.","mis":"K4-2-u2-X31"},{"t":"보고서에는 조사 방법을 한 가지만 써야 해.","mis":"K4-2-u2-X32"},{"t":"방법은 아무것이나 골라도 돼.","mis":"K4-2-u2-X33"}],"explanation":["두 끝을 조심해요.","많을수록도 아니에요.","한 가지만도 아니에요."],"asset":{"type":"speech","turns":[{"who":"친구","text":"보민이는 방법을 세 가지 썼네. 나는 다섯 가지를 다 써서 더 좋은 보고서를 만들 거야!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_basic#7','kor',4,2,'u2','L08','g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C40',2,'mc','auto','보민이의 때별 사람 수를 막대그래프로 함께 나타내면 좋은 점은 무엇인가요?',ARRAY['K4-2-u2-X43','K4-2-u2-X35','K4-2-u2-X41']::text[],false,'{"seq":7,"concept":"K4-2-u2-C40","difficulty":2,"kind":"mc","stem":"보민이의 때별 사람 수를 막대그래프로 함께 나타내면 좋은 점은 무엇인가요?","options":[{"t":"어느 때가 가장 많은지 한눈에 알아볼 수 있다","correct":true},{"t":"보고서가 더 길어 보인다","mis":"K4-2-u2-X43"},{"t":"수를 부풀려 보여 줄 수 있다","mis":"K4-2-u2-X35"},{"t":"조사하지 않은 내용도 채울 수 있다","mis":"K4-2-u2-X41"}],"explanation":["글로만 쓰면 길어요.","막대를 견줘요.","한눈에 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_basic#8','kor',4,2,'u2','L08','g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C41',2,'mc','auto','메모 ①의 문제점은 무엇인가요?',ARRAY['K4-2-u2-X35','K4-2-u2-X30']::text[],false,'{"seq":8,"concept":"K4-2-u2-C41","difficulty":2,"kind":"mc","stem":"메모 ①의 문제점은 무엇인가요?","options":[{"t":"24명 가운데 9명을 「대부분」이라고 부풀렸다","correct":true},{"t":"수를 바르게 적었으니 아무 문제가 없다","mis":"K4-2-u2-X35"},{"t":"9명을 틀리게 옮겨 적었다","mis":"K4-2-u2-X30"},{"t":"「고맙다」의 뜻을 빠뜨렸다","mis":"K4-2-u2-X30"}],"explanation":["수는 틀리지 않았어요.","「대부분」을 봐요.","9명은 대부분이 아니에요."],"asset":{"type":"passage","lines":["① 「9명은 적어 보이니까 ‘우리 반 대부분’이 날마다 고맙다고 말한다고 쓰자.」","② 「면담한 세 친구 가운데 한 명이 쑥스럽다고 했으니 모두 그렇다고 쓰자.」","③ 「누리집에서 찾은 ‘고맙다’의 뜻은 출처를 쓰지 않고 내 말처럼 옮기자.」","④ 「고맙다고 말하는 때별 사람 수는 막대그래프로 나타내자.」"],"title":"보민이가 쓰기 전에 적은 메모 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_basic#9','kor',4,2,'u2','L08','g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C43',2,'mc','auto','「조사한 내용」 칸에 들어갈 문장은 무엇인가요?',ARRAY['K4-2-u2-X39','K4-2-u2-X35']::text[],false,'{"seq":9,"concept":"K4-2-u2-C43","difficulty":2,"kind":"mc","stem":"「조사한 내용」 칸에 들어갈 문장은 무엇인가요?","options":[{"t":"24명 가운데 9명이 하루에 한 번 이상 고맙다고 말한다고 답했다","correct":true},{"t":"앞으로 내가 먼저 고맙다고 말해 보아야겠다","mis":"K4-2-u2-X39"},{"t":"고맙다고 말하지 않는 친구들은 마음씨가 나쁠 것이다","mis":"K4-2-u2-X39"},{"t":"우리 반 대부분이 날마다 고맙다고 말한다","mis":"K4-2-u2-X35"}],"explanation":["조사해서 확인했나요?","다짐은 소감 칸이에요.","짐작은 빼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_basic#10','kor',4,2,'u2','L08','g4_2_kor_u2_L08_basic','lesson_basic','K4-2-u2-C43',3,'ox','auto','보고하는 글에는 내 생각을 한 줄도 쓰면 안 돼요.',ARRAY['K4-2-u2-X38']::text[],false,'{"seq":10,"concept":"K4-2-u2-C43","difficulty":3,"kind":"ox","stem":"보고하는 글에는 내 생각을 한 줄도 쓰면 안 돼요.","answer":"X","reason_options":[{"t":"내 생각은 사실과 섞이지 않게 「조사 소감」 칸에 따로 쓰면 되기 때문에","correct":true},{"t":"보고하는 글은 사실만 쓰는 글이라 소감 칸이 없기 때문에","mis":"K4-2-u2-X38"}],"mis":"K4-2-u2-X38","explanation":["보민이 글에 소감이 있어요.","칸을 나누어 써요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_challenge#1','kor',4,2,'u2','L08','g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C42',2,'sa','auto','보고하는 글에서 옮겨 온 자료가 누가 만든 어떤 자료인지 밝힌 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u2-C42","difficulty":2,"kind":"sa","stem":"보고하는 글에서 옮겨 온 자료가 누가 만든 어떤 자료인지 밝힌 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["출처"],"explanation":["자료가 나온 곳이에요.","보민이 글 끝에 있어요.","‘출처’예요."],"mis":"K4-2-u2-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_challenge#2','kor',4,2,'u2','L08','g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C37',2,'mc','auto','여러 사람에게 같은 질문지로 물어 몇 명이 어떻게 답했는지 알아보는 조사 방법은 무엇인가요?',ARRAY['K4-2-u2-X33']::text[],false,'{"seq":2,"concept":"K4-2-u2-C37","difficulty":2,"kind":"mc","stem":"여러 사람에게 같은 질문지로 물어 몇 명이 어떻게 답했는지 알아보는 조사 방법은 무엇인가요?","options":[{"t":"설문 조사","correct":true},{"t":"면담 조사","mis":"K4-2-u2-X33"},{"t":"사전 찾아보기","mis":"K4-2-u2-X33"},{"t":"방문 조사","mis":"K4-2-u2-X33"}],"explanation":["여러 사람이에요.","같은 질문지예요.","설문 조사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_challenge#3','kor',4,2,'u2','L08','g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C41',3,'mc','auto','메모 ②의 문제점은 무엇인가요?',ARRAY['K4-2-u2-X35','K4-2-u2-X34','K4-2-u2-X33']::text[],false,'{"seq":3,"concept":"K4-2-u2-C41","difficulty":3,"kind":"mc","stem":"메모 ②의 문제점은 무엇인가요?","options":[{"t":"한 명의 말을 세 친구 모두의 까닭으로 넓혔다","correct":true},{"t":"수를 틀리게 적지 않았으니 문제가 없다","mis":"K4-2-u2-X35"},{"t":"면담한 친구의 말을 그대로 적은 것이 잘못이다","mis":"K4-2-u2-X34"},{"t":"면담은 보고하는 글에 쓸 수 없는 방법이다","mis":"K4-2-u2-X33"}],"explanation":["세 친구가 답했어요.","쑥스럽다는 한 명이에요.","모두로 넓히면 안 돼요."],"asset":{"type":"passage","lines":["① 「9명은 적어 보이니까 ‘우리 반 대부분’이 날마다 고맙다고 말한다고 쓰자.」","② 「면담한 세 친구 가운데 한 명이 쑥스럽다고 했으니 모두 그렇다고 쓰자.」","③ 「누리집에서 찾은 ‘고맙다’의 뜻은 출처를 쓰지 않고 내 말처럼 옮기자.」","④ 「고맙다고 말하는 때별 사람 수는 막대그래프로 나타내자.」"],"title":"보민이가 쓰기 전에 적은 메모 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_challenge#4','kor',4,2,'u2','L08','g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C41',3,'error','auto','보민이의 메모 넷을 점검했어요. 고치지 않아도 되는 메모를 고치자고 한 친구는 누구인가요?',ARRAY['K4-2-u2-X43','K4-2-u2-X35','K4-2-u2-X37']::text[],false,'{"seq":4,"concept":"K4-2-u2-C41","difficulty":3,"kind":"error","stem":"보민이의 메모 넷을 점검했어요. 고치지 않아도 되는 메모를 고치자고 한 친구는 누구인가요?","options":[{"t":"친구 다 — 「④ 사람 수를 막대그래프로 나타낸다는 메모도 고쳐야 해.」","correct":true,"mis_target":"K4-2-u2-X43"},{"t":"친구 가 — 「① ‘대부분’은 조사 결과와 맞지 않아.」","mis":"K4-2-u2-X35"},{"t":"친구 나 — 「③ 출처를 쓰지 않으면 남의 자료를 내 것처럼 쓰는 거야.」","mis":"K4-2-u2-X37"}],"explanation":["①은 부풀렸어요.","③은 출처가 없어요.","④는 알맞은 매체 자료예요."],"asset":{"type":"passage","lines":["① 「9명은 적어 보이니까 ‘우리 반 대부분’이 날마다 고맙다고 말한다고 쓰자.」","② 「면담한 세 친구 가운데 한 명이 쑥스럽다고 했으니 모두 그렇다고 쓰자.」","③ 「누리집에서 찾은 ‘고맙다’의 뜻은 출처를 쓰지 않고 내 말처럼 옮기자.」","④ 「고맙다고 말하는 때별 사람 수는 막대그래프로 나타내자.」"],"title":"보민이가 쓰기 전에 적은 메모 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_challenge#5','kor',4,2,'u2','L08','g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C37',3,'mc','auto','알아내려는 내용과 조사 방법을 알맞게 짝지은 것은 무엇인가요?',ARRAY['K4-2-u2-X33']::text[],false,'{"seq":5,"concept":"K4-2-u2-C37","difficulty":3,"kind":"mc","stem":"알아내려는 내용과 조사 방법을 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"「고맙다」의 뜻 — 사전 찾아보기","correct":true},{"t":"고맙다고 말하지 않는 까닭 — 사전 찾아보기","mis":"K4-2-u2-X33"},{"t":"고맙다고 말하는 친구 수 — 한 친구 면담하기","mis":"K4-2-u2-X33"},{"t":"「고맙다」의 뜻 — 친구들에게 설문하기","mis":"K4-2-u2-X33"}],"explanation":["까닭은 직접 물어요.","수는 여럿에게 물어요.","뜻은 사전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_challenge#6','kor',4,2,'u2','L08','g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C42',3,'mc','auto','참고 자료와 그 출처를 가장 바르게 적은 것은 무엇인가요?',ARRAY['K4-2-u2-X37']::text[],false,'{"seq":6,"concept":"K4-2-u2-C42","difficulty":3,"kind":"mc","stem":"참고 자료와 그 출처를 가장 바르게 적은 것은 무엇인가요?","options":[{"t":"국립국어원, 「표준국어대사전」 누리집, 「고맙다」 (찾아본 날 적기)","correct":true},{"t":"인터넷","mis":"K4-2-u2-X37"},{"t":"어떤 누리집","mis":"K4-2-u2-X37"},{"t":"출처는 적지 않고 뜻만 옮기기","mis":"K4-2-u2-X37"}],"explanation":["누가 만들었나요?","어떤 자료인가요?","다시 찾아볼 수 있게 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_challenge#7','kor',4,2,'u2','L08','g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C39',3,'mc','auto','면담한 내용을 기록하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X34']::text[],false,'{"seq":7,"concept":"K4-2-u2-C39","difficulty":3,"kind":"mc","stem":"면담한 내용을 기록하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"들은 말을 적거나, 허락을 받고 녹음한다","correct":true},{"t":"기억해 두었다가 나중에 내 말로 바꾸어 적는다","mis":"K4-2-u2-X34"},{"t":"대답이 너무 간단하면 내가 알맞게 덧붙여 적는다","mis":"K4-2-u2-X34"},{"t":"허락 없이 몰래 녹음한다","mis":"K4-2-u2-X34"}],"explanation":["바꾸지 않아요.","덧붙이지 않아요.","허락을 받아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_challenge#8','kor',4,2,'u2','L08','g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C43',4,'mc','auto','보민이 글의 「조사 소감」에 대한 생각으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X38','K4-2-u2-X39']::text[],false,'{"seq":8,"concept":"K4-2-u2-C43","difficulty":4,"kind":"mc","stem":"보민이 글의 「조사 소감」에 대한 생각으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「생각보다 적어서 놀랐다」는 조사를 마치고 든 내 생각이라, 조사한 내용과 칸을 나누어 쓴 것이 알맞다","correct":true},{"t":"보고하는 글에 소감을 쓴 것은 잘못이다","mis":"K4-2-u2-X38"},{"t":"소감도 조사한 내용 칸에 함께 섞어 써야 한다","mis":"K4-2-u2-X39"},{"t":"소감은 사실이므로 조사한 내용 칸으로 옮겨야 한다","mis":"K4-2-u2-X39"}],"explanation":["소감은 내 생각이에요.","쓸 수 있어요.","칸을 나누어요."],"asset":{"type":"passage","lines":["조사 대상 — 4학년 ○반 학생 24명","조사 동기 — 급식 때 고맙다고 말하는 친구가 적어 보여서 알고 싶었다.","조사 방법 — 설문 조사, 면담 조사, 사전 찾아보기","설문 — 하루 한 번 이상 9명 · 가끔 11명 · 거의 안 한다 4명","가장 많이 말하는 때 — 물건 빌려줄 때 12명 · 가족 6명 · 급식 4명 · 선생님 2명","면담 — 거의 안 한다는 세 명: 「쑥스러워서」 「알 것 같아서」 「깜빡 잊어서」","조사 소감 — 생각보다 적어서 놀랐다. 내가 먼저 말해 보아야겠다.","출처 — 국립국어원, 「표준국어대사전」 누리집, 「고맙다」"],"title":"보민이의 보고하는 글 「우리 반 친구들의 ‘고마워’ 말하기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_challenge#9','kor',4,2,'u2','L08','g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C41',4,'mc','auto','보민이의 설문 결과를 바르게 옮긴 문장은 무엇인가요?',ARRAY['K4-2-u2-X35','K4-2-u2-X40']::text[],false,'{"seq":9,"concept":"K4-2-u2-C41","difficulty":4,"kind":"mc","stem":"보민이의 설문 결과를 바르게 옮긴 문장은 무엇인가요?","options":[{"t":"24명 가운데 하루 한 번 이상 고맙다고 말하는 친구는 9명, 거의 하지 않는 친구는 4명이었다","correct":true},{"t":"우리 반 대부분이 날마다 고맙다고 말한다","mis":"K4-2-u2-X35"},{"t":"우리 반에는 고맙다고 말하는 친구가 거의 없다","mis":"K4-2-u2-X35"},{"t":"고맙다고 가장 많이 말하는 때는 급식을 받을 때다","mis":"K4-2-u2-X40"}],"explanation":["수를 그대로 옮겨요.","부풀리지도 줄이지도 않아요.","가장 많은 때도 확인해요."],"asset":{"type":"passage","lines":["조사 대상 — 4학년 ○반 학생 24명","조사 동기 — 급식 때 고맙다고 말하는 친구가 적어 보여서 알고 싶었다.","조사 방법 — 설문 조사, 면담 조사, 사전 찾아보기","설문 — 하루 한 번 이상 9명 · 가끔 11명 · 거의 안 한다 4명","가장 많이 말하는 때 — 물건 빌려줄 때 12명 · 가족 6명 · 급식 4명 · 선생님 2명","면담 — 거의 안 한다는 세 명: 「쑥스러워서」 「알 것 같아서」 「깜빡 잊어서」","조사 소감 — 생각보다 적어서 놀랐다. 내가 먼저 말해 보아야겠다.","출처 — 국립국어원, 「표준국어대사전」 누리집, 「고맙다」"],"title":"보민이의 보고하는 글 「우리 반 친구들의 ‘고마워’ 말하기」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L08_challenge#10','kor',4,2,'u2','L08','g4_2_kor_u2_L08_challenge','lesson_challenge','K4-2-u2-C38',4,'essay','teacher','보민이 반 친구들이 고맙다고 말하지 않는 까닭을 알아보려고 해요. 알맞은 조사 방법을 쓰고, 방법을 많이 쓸수록 좋은 보고서가 아닌 까닭과 그 방법으로 조사할 때 지킬 점 한 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u2-C38","difficulty":4,"kind":"essay","stem":"보민이 반 친구들이 고맙다고 말하지 않는 까닭을 알아보려고 해요. 알맞은 조사 방법을 쓰고, 방법을 많이 쓸수록 좋은 보고서가 아닌 까닭과 그 방법으로 조사할 때 지킬 점 한 가지를 쓰세요.","answer_guide":{"answer":"예: 까닭을 알아보려면 친구를 직접 만나 묻는 면담 조사가 알맞다. 방법의 개수보다 알아내려는 내용에 맞는 방법인지가 중요하므로, 방법을 많이 쓴다고 더 좋은 보고서가 되지는 않는다. 면담할 때는 질문을 미리 준비하고 들은 말을 바꾸지 않고 그대로 적어야 한다.","scoring_points":["알맞은 조사 방법(면담)을 썼는가","방법의 개수보다 알맞음이 중요한 까닭을 썼는가","그 방법으로 조사할 때 지킬 점을 썼는가"]},"explanation":["까닭은 직접 물어요.","개수가 아니라 알맞음이에요.","들은 그대로 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_basic#1','kor',4,2,'u2','L10','g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C44',1,'mc','auto','이번 주에 직접 조사하기에 가장 알맞은 주제는 무엇인가요?',ARRAY['K4-2-u2-X07']::text[],false,'{"seq":1,"concept":"K4-2-u2-C44","difficulty":1,"kind":"mc","stem":"이번 주에 직접 조사하기에 가장 알맞은 주제는 무엇인가요?","options":[{"t":"㉯ 우리 반 친구들이 아침에 쓰는 인사말","correct":true},{"t":"㉮ 전 세계 어린이가 쓰는 모든 인사말","mis":"K4-2-u2-X07"},{"t":"㉰ 조선 시대 사람들이 날마다 쓴 모든 말","mis":"K4-2-u2-X07"},{"t":"㉮와 ㉰를 한꺼번에 조사하기","mis":"K4-2-u2-X07"}],"explanation":["일주일 안에 할 수 있나요?","내가 직접 묻고 볼 수 있나요?","㉯예요."],"asset":{"type":"passage","lines":["㉮ 전 세계 어린이가 쓰는 모든 인사말","㉯ 우리 반 친구들이 아침에 쓰는 인사말","㉰ 조선 시대 사람들이 날마다 쓴 모든 말"],"title":"도겸이가 떠올린 주제 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_basic#2','kor',4,2,'u2','L10','g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C45',1,'mc','auto','설문지에 넣기 알맞은 질문은 무엇인가요?',ARRAY['K4-2-u2-X42']::text[],false,'{"seq":2,"concept":"K4-2-u2-C45","difficulty":1,"kind":"mc","stem":"설문지에 넣기 알맞은 질문은 무엇인가요?","options":[{"t":"아침에 친구를 만나면 주로 어떤 말로 인사하나요?","correct":true},{"t":"인사말은 무엇이고, 좋아하는 과목은 무엇인가요?","mis":"K4-2-u2-X42"},{"t":"「안녕」이 가장 좋은 인사말이지요?","mis":"K4-2-u2-X42"},{"t":"인사말과 점심 메뉴와 장래 희망은 무엇인가요?","mis":"K4-2-u2-X42"}],"explanation":["한 번에 하나만 물어요.","답을 몰아주지 않아요.","첫째 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_basic#3','kor',4,2,'u2','L10','g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C46',1,'mc','auto','도겸이의 조사 결과를 바르게 간추린 문장은 무엇인가요?',ARRAY['K4-2-u2-X35','K4-2-u2-X40']::text[],false,'{"seq":3,"concept":"K4-2-u2-C46","difficulty":1,"kind":"mc","stem":"도겸이의 조사 결과를 바르게 간추린 문장은 무엇인가요?","options":[{"t":"26명 가운데 15명이 「안녕」이라고 인사한다","correct":true},{"t":"우리 반은 모두 「안녕」이라고 인사한다","mis":"K4-2-u2-X35"},{"t":"「하이」라고 인사하는 친구가 가장 많다","mis":"K4-2-u2-X40"},{"t":"손만 흔드는 친구는 한 명도 없다","mis":"K4-2-u2-X40"}],"explanation":["설문 줄을 봐요.","15명은 모두가 아니에요.","가장 많은 건 「안녕」이에요."],"asset":{"type":"passage","lines":["설문(26명) — 「안녕」 15명 · 손만 흔들기 6명 · 「하이」 3명 · 인사 안 함 2명","면담 — 「안녕」은 「입에 붙어서」, 「하이」는 「간단하고 재미있어서」","면담 — 손만 흔드는 친구는 「멀리 있을 때가 많아서」","사전 — 「안녕」은 아무 탈 없이 편안하다는 뜻이다."],"title":"도겸이가 모은 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_basic#4','kor',4,2,'u2','L10','g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C47',1,'ox','auto','보고하는 글의 「끝」에는 조사 소감과 참고 자료의 출처를 써요.',ARRAY['K4-2-u2-X44']::text[],false,'{"seq":4,"concept":"K4-2-u2-C47","difficulty":1,"kind":"ox","stem":"보고하는 글의 「끝」에는 조사 소감과 참고 자료의 출처를 써요.","answer":"O","reason_options":[{"t":"처음에는 조사 과정, 가운데에는 알아낸 사실, 끝에는 내 생각과 출처를 쓰기 때문에","correct":true},{"t":"끝에는 조사 대상과 기간을 쓰기 때문에","mis":"K4-2-u2-X44"}],"mis":"K4-2-u2-X44","explanation":["처음은 과정이에요.","가운데는 사실이에요.","끝은 생각과 출처예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_basic#5','kor',4,2,'u2','L10','g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C47',2,'match','auto','도겸이 글의 짜임과 들어갈 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"K4-2-u2-C47","difficulty":2,"kind":"match","stem":"도겸이 글의 짜임과 들어갈 내용을 알맞게 이으세요.","pairs":[{"l":"처음","r":"설문 조사와 면담 조사로 알아보았다"},{"l":"가운데","r":"26명 가운데 15명이 「안녕」이라고 인사한다"},{"l":"끝","r":"나도 내일은 먼저 인사해 보고 싶다"}],"mis":"K4-2-u2-X44","explanation":["어떻게 조사했나요?","무엇을 알아냈나요?","내 생각은 끝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_basic#6','kor',4,2,'u2','L10','g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C48',2,'mc','auto','도겸이의 첫 글에 해 줄 알맞은 조언은 무엇인가요?',ARRAY['K4-2-u2-X41','K4-2-u2-X37']::text[],false,'{"seq":6,"concept":"K4-2-u2-C48","difficulty":2,"kind":"mc","stem":"도겸이의 첫 글에 해 줄 알맞은 조언은 무엇인가요?","options":[{"t":"「거의 모두」를 「26명 가운데 15명」으로 고치자","correct":true},{"t":"글이 짧으니 면담하지 않은 친구의 말도 지어 넣자","mis":"K4-2-u2-X41"},{"t":"방법이 두 가지뿐이니 하지 않은 조사도 한 것처럼 적자","mis":"K4-2-u2-X41"},{"t":"출처는 「인터넷」이라고만 써도 충분하다","mis":"K4-2-u2-X37"}],"explanation":["길게 만드는 조언이 아니에요.","믿을 수 있게 고쳐요.","수를 그대로 써요."],"asset":{"type":"passage","lines":["조사한 내용 — 설문 조사 결과, 우리 반은 거의 모두 「안녕」이라고 인사한다.","(막대그래프 있음)","조사 방법 — 설문 조사, 면담 조사","참고 자료와 그 출처 — 인터넷"],"title":"도겸이의 첫 글 일부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_basic#7','kor',4,2,'u2','L10','g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C45',2,'mc','auto','「‘안녕’이 가장 좋은 인사말이지요?」라는 질문의 문제점은 무엇인가요?',ARRAY['K4-2-u2-X42']::text[],false,'{"seq":7,"concept":"K4-2-u2-C45","difficulty":2,"kind":"mc","stem":"「‘안녕’이 가장 좋은 인사말이지요?」라는 질문의 문제점은 무엇인가요?","options":[{"t":"답을 한쪽으로 몰아 친구들의 생각을 있는 그대로 알기 어렵다","correct":true},{"t":"질문에 물음표가 있다","mis":"K4-2-u2-X42"},{"t":"「안녕」이라는 낱말을 쓰면 안 된다","mis":"K4-2-u2-X42"},{"t":"한 번에 세 가지를 묻는다","mis":"K4-2-u2-X42"}],"explanation":["「~지요?」를 봐요.","답을 정해 주고 있어요.","한쪽으로 몰아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_basic#8','kor',4,2,'u2','L10','g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C44',2,'mc','auto','조사 주제를 정할 때 알맞은 생각은 무엇인가요?',ARRAY['K4-2-u2-X07','K4-2-u2-X50']::text[],false,'{"seq":8,"concept":"K4-2-u2-C44","difficulty":2,"kind":"mc","stem":"조사 주제를 정할 때 알맞은 생각은 무엇인가요?","options":[{"t":"내가 관심 있으면서 직접 자료를 모을 수 있는 주제를 고른다","correct":true},{"t":"크고 멋진 주제일수록 좋다","mis":"K4-2-u2-X07"},{"t":"친구가 정한 주제를 그대로 따른다","mis":"K4-2-u2-X07"},{"t":"우리말과 상관없는 주제도 괜찮다","mis":"K4-2-u2-X50"}],"explanation":["관심이 있어야 해요.","직접 모을 수 있어야 해요.","우리말과 이어져야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_basic#9','kor',4,2,'u2','L10','g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C46',2,'mc','auto','「우리 반은 거의 모두 「안녕」이라고 인사한다」는 왜 고쳐야 하나요?',ARRAY['K4-2-u2-X30','K4-2-u2-X40','K4-2-u2-X35']::text[],false,'{"seq":9,"concept":"K4-2-u2-C46","difficulty":2,"kind":"mc","stem":"「우리 반은 거의 모두 「안녕」이라고 인사한다」는 왜 고쳐야 하나요?","options":[{"t":"26명 가운데 15명인데 「거의 모두」라고 부풀렸기 때문에","correct":true},{"t":"「안녕」은 인사말이 아니기 때문에","mis":"K4-2-u2-X30"},{"t":"조사 결과를 줄여 적었기 때문에","mis":"K4-2-u2-X40"},{"t":"수가 없는 문장은 언제나 맞기 때문에","mis":"K4-2-u2-X35"}],"explanation":["15명은 몇 명 가운데예요?","「거의 모두」일까요?","부풀렸어요."],"asset":{"type":"passage","lines":["설문(26명) — 「안녕」 15명 · 손만 흔들기 6명 · 「하이」 3명 · 인사 안 함 2명","면담 — 「안녕」은 「입에 붙어서」, 「하이」는 「간단하고 재미있어서」","면담 — 손만 흔드는 친구는 「멀리 있을 때가 많아서」","사전 — 「안녕」은 아무 탈 없이 편안하다는 뜻이다."],"title":"도겸이가 모은 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_basic#10','kor',4,2,'u2','L10','g4_2_kor_u2_L10_basic','lesson_basic','K4-2-u2-C48',3,'mc','auto','좋은 보고하는 글을 가장 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u2-X31','K4-2-u2-X39','K4-2-u2-X35']::text[],false,'{"seq":10,"concept":"K4-2-u2-C48","difficulty":3,"kind":"mc","stem":"좋은 보고하는 글을 가장 바르게 말한 것은 무엇인가요?","options":[{"t":"긴 글이 아니라 조사한 대로 써서 믿을 수 있는 글","correct":true},{"t":"조사 방법이 많고 길게 쓴 글","mis":"K4-2-u2-X31"},{"t":"내 생각을 가장 많이 담은 글","mis":"K4-2-u2-X39"},{"t":"결과가 놀라워 보이게 부풀린 글","mis":"K4-2-u2-X35"}],"explanation":["길이가 기준이 아니에요.","조사한 대로예요.","믿을 수 있어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_challenge#1','kor',4,2,'u2','L10','g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C47',2,'sa','auto','보고하는 글의 짜임 「처음 · ○○○ · 끝」에서 ○○○에 들어갈 말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u2-C47","difficulty":2,"kind":"sa","stem":"보고하는 글의 짜임 「처음 · ○○○ · 끝」에서 ○○○에 들어갈 말을 쓰세요.","answer":["가운데"],"explanation":["처음과 끝 사이예요.","알아낸 사실이 들어가요.","‘가운데’예요."],"mis":"K4-2-u2-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_challenge#2','kor',4,2,'u2','L10','g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C46',2,'mc','auto','도겸이의 면담 결과를 바르게 옮긴 것은 무엇인가요?',ARRAY['K4-2-u2-X36','K4-2-u2-X40']::text[],false,'{"seq":2,"concept":"K4-2-u2-C46","difficulty":2,"kind":"mc","stem":"도겸이의 면담 결과를 바르게 옮긴 것은 무엇인가요?","options":[{"t":"손만 흔드는 친구는 「멀리 있을 때가 많아서」라고 까닭을 들었다","correct":true},{"t":"「하이」라고 하는 친구는 모두 쑥스러워서라고 했다","mis":"K4-2-u2-X36"},{"t":"손만 흔드는 친구는 인사하기 싫어서라고 했다","mis":"K4-2-u2-X40"},{"t":"「안녕」은 멋있어서 쓴다고 했다","mis":"K4-2-u2-X40"}],"explanation":["면담 줄을 봐요.","들은 말 그대로예요.","바꾸지 않아요."],"asset":{"type":"passage","lines":["설문(26명) — 「안녕」 15명 · 손만 흔들기 6명 · 「하이」 3명 · 인사 안 함 2명","면담 — 「안녕」은 「입에 붙어서」, 「하이」는 「간단하고 재미있어서」","면담 — 손만 흔드는 친구는 「멀리 있을 때가 많아서」","사전 — 「안녕」은 아무 탈 없이 편안하다는 뜻이다."],"title":"도겸이가 모은 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_challenge#3','kor',4,2,'u2','L10','g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C45',3,'error','auto','설문 질문을 만들었어요. 고쳐야 할 질문을 만든 친구는 누구인가요?',ARRAY['K4-2-u2-X42']::text[],false,'{"seq":3,"concept":"K4-2-u2-C45","difficulty":3,"kind":"error","stem":"설문 질문을 만들었어요. 고쳐야 할 질문을 만든 친구는 누구인가요?","options":[{"t":"친구 나 — 「아침에 주로 하는 인사말과 좋아하는 과목은 무엇인가요?」","correct":true,"mis_target":"K4-2-u2-X42"},{"t":"친구 가 — 「아침에 친구를 만나면 주로 어떤 말로 인사하나요?」","mis":"K4-2-u2-X42"},{"t":"친구 다 — 「아침에 인사를 하지 않을 때도 있나요?」","mis":"K4-2-u2-X42"}],"explanation":["한 번에 몇 가지를 묻나요?","친구 나는 두 가지예요.","하나씩 물어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_challenge#4','kor',4,2,'u2','L10','g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C46',3,'mc','auto','하준이의 조사 결과를 바르게 간추린 문장은 무엇인가요?',ARRAY['K4-2-u2-X35','K4-2-u2-X40']::text[],false,'{"seq":4,"concept":"K4-2-u2-C46","difficulty":3,"kind":"mc","stem":"하준이의 조사 결과를 바르게 간추린 문장은 무엇인가요?","options":[{"t":"20장 가운데 8장에 외국어가 들어 있었다","correct":true},{"t":"거의 모든 게시물에 외국어가 쓰여 있었다","mis":"K4-2-u2-X35"},{"t":"우리말로만 쓴 게시물이 가장 적었다","mis":"K4-2-u2-X40"},{"t":"외국어가 들어간 게시물은 한 장도 없었다","mis":"K4-2-u2-X40"}],"explanation":["결과 ①을 봐요.","8장은 거의 모두가 아니에요.","우리말로만 쓴 것이 더 많아요."],"asset":{"type":"passage","lines":["조사 대상 — 우리 학교 3·4층 복도 게시물 20장","조사 방법 — 직접 보고 기록하기, 게시물을 만든 사람 면담하기","결과 ① — 외국어가 들어간 것 8장, 우리말로만 쓴 것 12장","결과 ② — 「클린 데이」 3장 · 「이벤트」 2장 · 「버스」 2장 · 「컴퓨터」 1장","면담 — 게시물을 만든 6학년 두 명: 「눈에 잘 띄어서」, 「다들 그렇게 써서」"],"title":"하준이의 조사 자료 「우리 학교 복도 게시물에 쓰인 외국어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_challenge#5','kor',4,2,'u2','L10','g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C48',3,'mc','auto','하준이 글에 해 줄 조언으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X41','K4-2-u2-X35','K4-2-u2-X38']::text[],false,'{"seq":5,"concept":"K4-2-u2-C48","difficulty":3,"kind":"mc","stem":"하준이 글에 해 줄 조언으로 알맞은 것은 무엇인가요?","options":[{"t":"「버스」·「컴퓨터」처럼 굳은 말과 우리말로 바꿀 수 있는 말을 나누어 정리하면 더 정확해","correct":true},{"t":"면담하지 않은 선생님 말씀도 지어 넣어 글을 길게 하자","mis":"K4-2-u2-X41"},{"t":"외국어 게시물을 14장이라고 늘려 쓰면 더 놀라울 거야","mis":"K4-2-u2-X35"},{"t":"조사 소감은 지우고 사실만 남겨야 해","mis":"K4-2-u2-X38"}],"explanation":["지어 넣지 않아요.","늘려 쓰지 않아요.","나누어 정리하면 정확해져요."],"asset":{"type":"passage","lines":["조사 대상 — 우리 학교 3·4층 복도 게시물 20장","조사 방법 — 직접 보고 기록하기, 게시물을 만든 사람 면담하기","결과 ① — 외국어가 들어간 것 8장, 우리말로만 쓴 것 12장","결과 ② — 「클린 데이」 3장 · 「이벤트」 2장 · 「버스」 2장 · 「컴퓨터」 1장","면담 — 게시물을 만든 6학년 두 명: 「눈에 잘 띄어서」, 「다들 그렇게 써서」"],"title":"하준이의 조사 자료 「우리 학교 복도 게시물에 쓰인 외국어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_challenge#6','kor',4,2,'u2','L10','g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C44',3,'mc','auto','다음 가운데 이번 주에 직접 조사하기 알맞은 주제는 무엇인가요?',ARRAY['K4-2-u2-X07','K4-2-u2-X50']::text[],false,'{"seq":6,"concept":"K4-2-u2-C44","difficulty":3,"kind":"mc","stem":"다음 가운데 이번 주에 직접 조사하기 알맞은 주제는 무엇인가요?","options":[{"t":"우리 학교 복도 게시물에 쓰인 외국어","correct":true},{"t":"세계 여러 나라 간판에 쓰인 모든 말","mis":"K4-2-u2-X07"},{"t":"우리나라 사람이 하루에 쓰는 모든 낱말","mis":"K4-2-u2-X07"},{"t":"우리 반 친구들이 좋아하는 운동 경기","mis":"K4-2-u2-X50"}],"explanation":["직접 보고 기록할 수 있나요?","우리말과 이어지나요?","복도 게시물이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_challenge#7','kor',4,2,'u2','L10','g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C47',3,'mc','auto','하준이 글을 처음·가운데·끝으로 짤 때 「가운데」에 들어갈 것은 무엇인가요?',ARRAY['K4-2-u2-X44']::text[],false,'{"seq":7,"concept":"K4-2-u2-C47","difficulty":3,"kind":"mc","stem":"하준이 글을 처음·가운데·끝으로 짤 때 「가운데」에 들어갈 것은 무엇인가요?","options":[{"t":"외국어가 들어간 게시물 수와 면담 결과","correct":true},{"t":"조사 대상과 조사 방법","mis":"K4-2-u2-X44"},{"t":"우리말로 바꿀 수 있는 말이 많아 놀랐다는 소감","mis":"K4-2-u2-X44"},{"t":"참고 자료와 그 출처","mis":"K4-2-u2-X44"}],"explanation":["처음은 과정이에요.","끝은 생각과 출처예요.","가운데는 알아낸 사실이에요."],"asset":{"type":"passage","lines":["조사 대상 — 우리 학교 3·4층 복도 게시물 20장","조사 방법 — 직접 보고 기록하기, 게시물을 만든 사람 면담하기","결과 ① — 외국어가 들어간 것 8장, 우리말로만 쓴 것 12장","결과 ② — 「클린 데이」 3장 · 「이벤트」 2장 · 「버스」 2장 · 「컴퓨터」 1장","면담 — 게시물을 만든 6학년 두 명: 「눈에 잘 띄어서」, 「다들 그렇게 써서」"],"title":"하준이의 조사 자료 「우리 학교 복도 게시물에 쓰인 외국어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_challenge#8','kor',4,2,'u2','L10','g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C48',4,'mc','auto','도겸이 첫 글의 출처 「인터넷」을 두고 한 조언 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X37','K4-2-u2-X41']::text[],false,'{"seq":8,"concept":"K4-2-u2-C48","difficulty":4,"kind":"mc","stem":"도겸이 첫 글의 출처 「인터넷」을 두고 한 조언 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"「누리집 이름과 찾아본 낱말을 적어야 읽는 사람이 다시 확인할 수 있어.」","correct":true},{"t":"「출처는 길면 지루하니 빼자.」","mis":"K4-2-u2-X37"},{"t":"「인터넷이라고 쓰면 충분해.」","mis":"K4-2-u2-X37"},{"t":"「찾아보지 않은 책 이름도 적어 두면 더 믿음이 가.」","mis":"K4-2-u2-X41"}],"explanation":["인터넷은 너무 넓어요.","다시 찾아볼 수 있어야 해요.","찾지 않은 것은 적지 않아요."],"asset":{"type":"passage","lines":["조사한 내용 — 설문 조사 결과, 우리 반은 거의 모두 「안녕」이라고 인사한다.","(막대그래프 있음)","조사 방법 — 설문 조사, 면담 조사","참고 자료와 그 출처 — 인터넷"],"title":"도겸이의 첫 글 일부"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_challenge#9','kor',4,2,'u2','L10','g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C46',4,'mc','auto','하준이의 결과에서 「우리말로 바꿔 쓸 수 있는 말」만 바르게 고른 것은 무엇인가요?',ARRAY['K4-2-u2-X24','K4-2-u2-X25']::text[],false,'{"seq":9,"concept":"K4-2-u2-C46","difficulty":4,"kind":"mc","stem":"하준이의 결과에서 「우리말로 바꿔 쓸 수 있는 말」만 바르게 고른 것은 무엇인가요?","options":[{"t":"「클린 데이」 · 「이벤트」","correct":true},{"t":"「버스」 · 「컴퓨터」","mis":"K4-2-u2-X24"},{"t":"「클린 데이」 · 「이벤트」 · 「버스」 · 「컴퓨터」","mis":"K4-2-u2-X24"},{"t":"바꿔 쓸 수 있는 말은 하나도 없다","mis":"K4-2-u2-X25"}],"explanation":["굳은 말을 빼요.","버스와 컴퓨터는 굳은 말이에요.","두 가지가 남아요."],"asset":{"type":"passage","lines":["조사 대상 — 우리 학교 3·4층 복도 게시물 20장","조사 방법 — 직접 보고 기록하기, 게시물을 만든 사람 면담하기","결과 ① — 외국어가 들어간 것 8장, 우리말로만 쓴 것 12장","결과 ② — 「클린 데이」 3장 · 「이벤트」 2장 · 「버스」 2장 · 「컴퓨터」 1장","면담 — 게시물을 만든 6학년 두 명: 「눈에 잘 띄어서」, 「다들 그렇게 써서」"],"title":"하준이의 조사 자료 「우리 학교 복도 게시물에 쓰인 외국어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L10_challenge#10','kor',4,2,'u2','L10','g4_2_kor_u2_L10_challenge','lesson_challenge','K4-2-u2-C47',4,'essay','teacher','하준이의 조사 자료로 보고하는 글의 「가운데」를 두세 문장으로 쓰세요. 결과를 부풀리거나 줄이지 말고 수를 정확히 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u2-C47","difficulty":4,"kind":"essay","stem":"하준이의 조사 자료로 보고하는 글의 「가운데」를 두세 문장으로 쓰세요. 결과를 부풀리거나 줄이지 말고 수를 정확히 쓰세요.","answer_guide":{"answer":"예: 복도 게시물 20장 가운데 외국어가 들어간 것은 8장이고, 우리말로만 쓴 것은 12장이었다. 외국어 8장 가운데 「클린 데이」가 3장, 「이벤트」가 2장, 「버스」가 2장, 「컴퓨터」가 1장이었다. 게시물을 만든 6학년 두 명은 「눈에 잘 띄어서」, 「다들 그렇게 써서」라고 답했다.","scoring_points":["조사한 수를 정확히 썼는가","부풀리거나 줄이는 낱말을 쓰지 않았는가","면담 결과를 들은 그대로 옮겼는가"]},"explanation":["수를 그대로 써요.","「거의」를 쓰지 않아요.","면담도 그대로 옮겨요."],"asset":{"type":"passage","lines":["조사 대상 — 우리 학교 3·4층 복도 게시물 20장","조사 방법 — 직접 보고 기록하기, 게시물을 만든 사람 면담하기","결과 ① — 외국어가 들어간 것 8장, 우리말로만 쓴 것 12장","결과 ② — 「클린 데이」 3장 · 「이벤트」 2장 · 「버스」 2장 · 「컴퓨터」 1장","면담 — 게시물을 만든 6학년 두 명: 「눈에 잘 띄어서」, 「다들 그렇게 써서」"],"title":"하준이의 조사 자료 「우리 학교 복도 게시물에 쓰인 외국어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_basic#1','kor',4,2,'u2','L12','g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C49',1,'mc','auto','한글을 아끼는 마음이 가장 잘 담긴 시는 무엇인가요?',ARRAY['K4-2-u2-X45']::text[],false,'{"seq":1,"concept":"K4-2-u2-C49","difficulty":1,"kind":"mc","stem":"한글을 아끼는 마음이 가장 잘 담긴 시는 무엇인가요?","options":[{"t":"「받침 하나 바꾸면 / 뜻이 달라져서 / 오늘도 한 번 더 들여다봐요」","correct":true},{"t":"급식 메뉴와 운동장 놀이를 열 줄 넘게 늘어놓은 시","mis":"K4-2-u2-X45"},{"t":"뜻을 모르는 어려운 낱말만 골라 이어 붙인 시","mis":"K4-2-u2-X45"},{"t":"행이 가장 많은 시","mis":"K4-2-u2-X45"}],"explanation":["길이를 보지 않아요.","어려운 낱말도 아니에요.","한글에 대한 마음을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_basic#2','kor',4,2,'u2','L12','g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C50',1,'mc','auto','「우리 집 과자·음료 포장지에 쓰인 이름 조사」의 조사 동기로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X50']::text[],false,'{"seq":2,"concept":"K4-2-u2-C50","difficulty":1,"kind":"mc","stem":"「우리 집 과자·음료 포장지에 쓰인 이름 조사」의 조사 동기로 알맞은 것은 무엇인가요?","options":[{"t":"과자 이름에 외국어가 많아 보여서 우리말 이름은 얼마나 되는지 알고 싶어서","correct":true},{"t":"과자를 더 많이 먹고 싶어서","mis":"K4-2-u2-X50"},{"t":"가장 비싼 과자를 찾아내고 싶어서","mis":"K4-2-u2-X50"},{"t":"가장 맛있는 과자를 고르고 싶어서","mis":"K4-2-u2-X50"}],"explanation":["이 단원의 주제를 떠올려요.","우리말 사용이에요.","이름에 쓰인 말을 알고 싶어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_basic#3','kor',4,2,'u2','L12','g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C52',1,'mc','auto','ㄼ 받침 낱말을 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-2-u2-X48','K4-2-u2-X47']::text[],false,'{"seq":3,"concept":"K4-2-u2-C52","difficulty":1,"kind":"mc","stem":"ㄼ 받침 낱말을 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"떫지 [떨찌]","correct":true},{"t":"떫지 [떱찌]","mis":"K4-2-u2-X48"},{"t":"엷고 [엽꼬]","mis":"K4-2-u2-X48"},{"t":"밟고 [발꼬]","mis":"K4-2-u2-X47"}],"explanation":["ㄼ 뒤에 자음이 와요.","대부분 [ㄹ]로 나요.","밟-만 따로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_basic#4','kor',4,2,'u2','L12','g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C56',1,'ox','auto','「앉다」는 받침 ㄵ을 바르게 쓴 낱말이에요.',ARRAY['K4-2-u2-X49']::text[],false,'{"seq":4,"concept":"K4-2-u2-C56","difficulty":1,"kind":"ox","stem":"「앉다」는 받침 ㄵ을 바르게 쓴 낱말이에요.","answer":"O","reason_options":[{"t":"앉다는 ㄴ과 ㅈ 두 받침을 함께 쓰는 낱말이기 때문에","correct":true},{"t":"소리 나는 대로 「안따」로 써야 하기 때문에","mis":"K4-2-u2-X49"}],"mis":"K4-2-u2-X49","explanation":["앉아, 앉고를 떠올려요.","ㄴ과 ㅈ이 함께 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_basic#5','kor',4,2,'u2','L12','g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C51',2,'mc','auto','우리말로 쓸 수 있는데 외국어로만 지은 이름을 바르게 모은 것은 무엇인가요?',ARRAY['K4-2-u2-X46','K4-2-u2-X24','K4-2-u2-X25']::text[],false,'{"seq":5,"concept":"K4-2-u2-C51","difficulty":2,"kind":"mc","stem":"우리말로 쓸 수 있는데 외국어로만 지은 이름을 바르게 모은 것은 무엇인가요?","options":[{"t":"허니 크런치 스낵 · 프레시 스위트 드링크 · 해피 초코 볼","correct":true},{"t":"달콤 누룽지 · 햇살 보리차 · 바삭 김부각","mis":"K4-2-u2-X46"},{"t":"여섯 개 모두","mis":"K4-2-u2-X24"},{"t":"하나도 없다","mis":"K4-2-u2-X25"}],"explanation":["달콤·햇살·바삭은 우리말이에요.","나머지를 봐요.","조사한 대로 나눠요."],"asset":{"type":"passage","lines":["달콤 누룽지 · 허니 크런치 스낵 · 햇살 보리차","프레시 스위트 드링크 · 바삭 김부각 · 해피 초코 볼"],"title":"포장지에서 찾은 이름 여섯 개 (지어낸 이름)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_basic#6','kor',4,2,'u2','L12','g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C51',2,'mc','auto','동생에게 해 줄 알맞은 말은 무엇인가요?',ARRAY['K4-2-u2-X46','K4-2-u2-X25']::text[],false,'{"seq":6,"concept":"K4-2-u2-C51","difficulty":2,"kind":"mc","stem":"동생에게 해 줄 알맞은 말은 무엇인가요?","options":[{"t":"과자가 나쁜 게 아니야. 이름에 우리말을 살려 쓸 수 있었는지를 알아본 거야.","correct":true},{"t":"맞아. 외국어 이름 과자는 이제 사지 말자.","mis":"K4-2-u2-X46"},{"t":"외국어 이름이 더 멋지니 우리말 이름도 바꾸자.","mis":"K4-2-u2-X25"},{"t":"조사한 과자는 모두 버리자.","mis":"K4-2-u2-X46"}],"explanation":["조사 주제를 떠올려요.","물건이 아니에요.","이름에 쓰인 말이에요."],"asset":{"type":"speech","turns":[{"who":"동생","text":"외국어 이름 과자는 나쁜 과자니까 이제 사지 말자!"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_basic#7','kor',4,2,'u2','L12','g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C53',2,'mc','auto','「밟고」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-2-u2-X47','K4-2-u2-X48']::text[],false,'{"seq":7,"concept":"K4-2-u2-C53","difficulty":2,"kind":"mc","stem":"「밟고」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[밥꼬]","correct":true},{"t":"[발꼬]","mis":"K4-2-u2-X47"},{"t":"[발고]","mis":"K4-2-u2-X47"},{"t":"[밥고]","mis":"K4-2-u2-X48"}],"explanation":["밟-은 따로 정해 둔 말이에요.","[ㅂ]으로 소리 나요.","뒤는 된소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_basic#8','kor',4,2,'u2','L12','g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C55',2,'match','auto','「리플·네티즌·팝업창」과 그 말을 다듬은 우리말을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"K4-2-u2-C55","difficulty":2,"kind":"match","stem":"「리플·네티즌·팝업창」과 그 말을 다듬은 우리말을 알맞게 이으세요.","pairs":[{"l":"리플","r":"댓글"},{"l":"네티즌","r":"누리꾼"},{"l":"팝업창","r":"알림창"}],"mis":"K4-2-u2-X19","explanation":["글에 다는 글이에요.","누리 + 꾼이에요.","알려 주는 창이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_basic#9','kor',4,2,'u2','L12','g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C54',2,'mc','auto','「밟고」를 소리 나는 대로 「밥고」라고 적어도 될까요?',ARRAY['K4-2-u2-X15','K4-2-u2-X02','K4-2-u2-X47']::text[],false,'{"seq":9,"concept":"K4-2-u2-C54","difficulty":2,"kind":"mc","stem":"「밟고」를 소리 나는 대로 「밥고」라고 적어도 될까요?","options":[{"t":"뜻을 알아보기 쉽게 글자는 「밟고」로 적고, 소리만 [밥꼬]로 낸다","correct":true},{"t":"소리대로 「밥고」라고 적는 것이 더 정확하다","mis":"K4-2-u2-X15"},{"t":"어떻게 적어도 뜻은 똑같이 통한다","mis":"K4-2-u2-X02"},{"t":"「발고」라고 적는다","mis":"K4-2-u2-X47"}],"explanation":["밟다 · 밟아 · 밟고를 나란히 봐요.","같은 모양이라 뜻이 보여요.","소리만 바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_basic#10','kor',4,2,'u2','L12','g4_2_kor_u2_L12_basic','lesson_basic','K4-2-u2-C56',3,'error','auto','겹받침 낱말을 넣어 문장을 썼어요. 잘못 쓴 친구는 누구인가요?',ARRAY['K4-2-u2-X49']::text[],false,'{"seq":10,"concept":"K4-2-u2-C56","difficulty":3,"kind":"error","stem":"겹받침 낱말을 넣어 문장을 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"친구 나 — 「갑진 우리글을 아껴 써요.」","correct":true,"mis_target":"K4-2-u2-X49"},{"t":"친구 가 — 「넋을 놓고 노을을 바라보았다.」","mis":"K4-2-u2-X49"},{"t":"친구 다 — 「의자에 바르게 앉아 써요.」","mis":"K4-2-u2-X49"}],"explanation":["값이 있는 것이 값지다예요.","ㅂ과 ㅅ이 함께 있어요.","친구 나가 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_challenge#1','kor',4,2,'u2','L12','g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C55',2,'sa','auto','「네티즌」을 다듬은 우리말을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"K4-2-u2-C55","difficulty":2,"kind":"sa","stem":"「네티즌」을 다듬은 우리말을 쓰세요.","answer":["누리꾼"],"explanation":["누리는 세상이에요.","꾼은 어떤 일을 하는 사람이에요.","‘누리꾼’이에요."],"mis":"K4-2-u2-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_challenge#2','kor',4,2,'u2','L12','g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C52',2,'blank','auto','ㄼ 받침 뒤에 자음이 오면 대부분 [  ]으로 소리 나요. 빈칸에 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X48']::text[],false,'{"seq":2,"concept":"K4-2-u2-C52","difficulty":2,"kind":"blank","stem":"ㄼ 받침 뒤에 자음이 오면 대부분 [  ]으로 소리 나요. 빈칸에 알맞은 것은 무엇인가요?","options":[{"t":"ㄹ","correct":true},{"t":"ㅂ","mis":"K4-2-u2-X48"},{"t":"ㄴ","mis":"K4-2-u2-X48"},{"t":"ㅁ","mis":"K4-2-u2-X48"}],"explanation":["떫다 [떨따]를 읽어요.","엷고 [열꼬]도 읽어요.","[ㄹ]이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_challenge#3','kor',4,2,'u2','L12','g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C53',3,'mc','auto','「ㄼ은 언제나 [ㄹ]로 소리 난다」라고 외운 친구에게 해 줄 말은 무엇인가요?',ARRAY['K4-2-u2-X47','K4-2-u2-X48']::text[],false,'{"seq":3,"concept":"K4-2-u2-C53","difficulty":3,"kind":"mc","stem":"「ㄼ은 언제나 [ㄹ]로 소리 난다」라고 외운 친구에게 해 줄 말은 무엇인가요?","options":[{"t":"대부분은 [ㄹ]이지만 「밟-」은 [ㅂ]으로 소리 내기로 정해 둔 말이야. 밟다는 [밥따]야.","correct":true},{"t":"맞아. 그러니 밟다는 [발따]야.","mis":"K4-2-u2-X47"},{"t":"아니야. ㄼ은 언제나 [ㅂ]이라 떫다는 [떱따]야.","mis":"K4-2-u2-X48"},{"t":"ㄼ 받침은 소리 내지 않고 읽으면 돼.","mis":"K4-2-u2-X48"}],"explanation":["대부분은 [ㄹ]이에요.","밟-은 따로 정했어요.","「언제나」를 조심해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_challenge#4','kor',4,2,'u2','L12','g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C54',3,'mc','auto','「국물 → [궁물]」과 「밟고 → [밥꼬]」의 공통점으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X15','K4-2-u2-X14','K4-2-u2-X13']::text[],false,'{"seq":4,"concept":"K4-2-u2-C54","difficulty":3,"kind":"mc","stem":"「국물 → [궁물]」과 「밟고 → [밥꼬]」의 공통점으로 알맞은 것은 무엇인가요?","options":[{"t":"적힌 글자와 소리가 조금 다르지만, 글자는 뜻을 알아보기 쉽게 원래 모양대로 적는다","correct":true},{"t":"둘 다 소리대로 고쳐 적어야 한다","mis":"K4-2-u2-X15"},{"t":"둘 다 한글이 짜임새 없는 글자라는 증거다","mis":"K4-2-u2-X14"},{"t":"둘 다 적힌 대로 소리 내야 한다","mis":"K4-2-u2-X13"}],"explanation":["글자와 소리를 견줘요.","소리가 조금 달라요.","글자는 원래 모양대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_challenge#5','kor',4,2,'u2','L12','g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C49',3,'mc','auto','친구의 「가나다」 시를 읽고 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X45']::text[],false,'{"seq":5,"concept":"K4-2-u2-C49","difficulty":3,"kind":"mc","stem":"친구의 「가나다」 시를 읽고 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「‘다정하게 글자 속에 살고 있어요’에서 한글을 아끼는 마음이 느껴져.」","correct":true},{"t":"「줄이 세 줄뿐이라 좋은 시가 아니야.」","mis":"K4-2-u2-X45"},{"t":"「어려운 낱말을 더 넣으면 좋은 시가 될 거야.」","mis":"K4-2-u2-X45"},{"t":"「한글과 상관없는 이야기도 더 늘어놓자.」","mis":"K4-2-u2-X45"}],"explanation":["한 줄을 콕 집어요.","마음이 느껴진 곳이에요.","길이를 따지지 않아요."],"asset":{"type":"passage","lines":["가 — 가만히 소리 내어 읽어 보면","나 — 나를 닮은 목소리가","다 — 다정하게 글자 속에 살고 있어요"],"title":"「가나다」로 지은 시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_challenge#6','kor',4,2,'u2','L12','g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C51',3,'mc','auto','우리말로 쓸 수 있는데 외국어로만 지은 문구 이름을 모두 바르게 고른 것은 무엇인가요?',ARRAY['K4-2-u2-X46','K4-2-u2-X24']::text[],false,'{"seq":6,"concept":"K4-2-u2-C51","difficulty":3,"kind":"mc","stem":"우리말로 쓸 수 있는데 외국어로만 지은 문구 이름을 모두 바르게 고른 것은 무엇인가요?","options":[{"t":"스마일 펜슬 · 해피 스쿨 백 · 드림 노트","correct":true},{"t":"반짝 지우개 · 쓱쓱 연필 · 소복 공책","mis":"K4-2-u2-X46"},{"t":"스마일 펜슬 하나뿐","mis":"K4-2-u2-X46"},{"t":"여섯 개 모두","mis":"K4-2-u2-X24"}],"explanation":["반짝·쓱쓱·소복은 우리말이에요.","나머지 셋을 봐요.","조사한 대로 모두 골라요."],"asset":{"type":"passage","lines":["반짝 지우개 · 스마일 펜슬 · 쓱쓱 연필","해피 스쿨 백 · 소복 공책 · 드림 노트"],"title":"문구점 진열대에서 찾은 이름 여섯 개 (지어낸 이름)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_challenge#7','kor',4,2,'u2','L12','g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C50',3,'error','auto','우리 반 실천 활동을 정했어요. 단원과 이어지지 않는 활동을 정한 친구는 누구인가요?',ARRAY['K4-2-u2-X50']::text[],false,'{"seq":7,"concept":"K4-2-u2-C50","difficulty":3,"kind":"error","stem":"우리 반 실천 활동을 정했어요. 단원과 이어지지 않는 활동을 정한 친구는 누구인가요?","options":[{"t":"친구 다 — 「우리 반에서 가장 빨리 달리는 친구 조사하기」","correct":true,"mis_target":"K4-2-u2-X50"},{"t":"친구 가 — 「학교 게시판 안내문에 쓰인 말 조사하기」","mis":"K4-2-u2-X50"},{"t":"친구 나 — 「받침이 헷갈리는 낱말을 모은 카드 만들기」","mis":"K4-2-u2-X50"}],"explanation":["한글 사랑과 이어지나요?","우리말 사용과 이어지나요?","친구 다는 상관없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_challenge#8','kor',4,2,'u2','L12','g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C51',4,'mc','auto','포장지 조사 결과를 정리한 말 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X46','K4-2-u2-X35']::text[],false,'{"seq":8,"concept":"K4-2-u2-C51","difficulty":4,"kind":"mc","stem":"포장지 조사 결과를 정리한 말 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"「여섯 개 가운데 셋은 우리말을 살린 이름, 셋은 우리말로 쓸 수 있는데 외국어로만 지은 이름이었다.」","correct":true},{"t":"「대부분이 외국어 이름이라 나쁜 과자가 많았다.」","mis":"K4-2-u2-X46"},{"t":"「외국어 이름 과자가 더 맛있었다.」","mis":"K4-2-u2-X46"},{"t":"「모든 과자 이름이 외국어였다.」","mis":"K4-2-u2-X35"}],"explanation":["수를 그대로 써요.","물건을 평가하지 않아요.","쓰인 말을 나눠요."],"asset":{"type":"passage","lines":["달콤 누룽지 · 허니 크런치 스낵 · 햇살 보리차","프레시 스위트 드링크 · 바삭 김부각 · 해피 초코 볼"],"title":"포장지에서 찾은 이름 여섯 개 (지어낸 이름)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_challenge#9','kor',4,2,'u2','L12','g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C56',4,'mc','auto','겹받침을 모두 바르게 쓴 문장은 무엇인가요?',ARRAY['K4-2-u2-X49']::text[],false,'{"seq":9,"concept":"K4-2-u2-C56","difficulty":4,"kind":"mc","stem":"겹받침을 모두 바르게 쓴 문장은 무엇인가요?","options":[{"t":"「흙이 묻은 의자에 앉지 말고 값진 물건을 챙겨요.」","correct":true},{"t":"「흑이 묻은 의자에 앉지 말고 값진 물건을 챙겨요.」","mis":"K4-2-u2-X49"},{"t":"「흙이 묻은 의자에 안지 말고 값진 물건을 챙겨요.」","mis":"K4-2-u2-X49"},{"t":"「흙이 묻은 의자에 앉지 말고 갑진 물건을 챙겨요.」","mis":"K4-2-u2-X49"}],"explanation":["흙은 ㄺ이에요.","앉다는 ㄵ이에요.","값지다는 ㅄ이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_L12_challenge#10','kor',4,2,'u2','L12','g4_2_kor_u2_L12_challenge','lesson_challenge','K4-2-u2-C50',4,'essay','teacher','「우리 둘레의 말 조사하기」 계획을 세우세요. 조사 대상·기간·동기·방법을 쓰고, 조사 결과를 정리할 때 지킬 점 한 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K4-2-u2-C50","difficulty":4,"kind":"essay","stem":"「우리 둘레의 말 조사하기」 계획을 세우세요. 조사 대상·기간·동기·방법을 쓰고, 조사 결과를 정리할 때 지킬 점 한 가지를 쓰세요.","answer_guide":{"answer":"예: 조사 대상은 우리 동네 상가에 붙은 안내문 열 개, 기간은 이번 주 토요일, 동기는 안내문에 외국어가 많아 보여서 우리말로 쓸 수 있는 말이 얼마나 되는지 알고 싶어서이다. 방법은 직접 보고 기록하고 사진을 찍는 것이다. 정리할 때는 본 그대로 수를 세어 부풀리지 않고, 가게가 좋은지 나쁜지가 아니라 쓰인 말을 나눈다.","scoring_points":["조사 대상과 기간을 구체적으로 썼는가","우리말 사용과 이어진 동기와 방법을 썼는가","결과를 정리할 때 지킬 점을 썼는가"]},"explanation":["대상 · 기간을 정해요.","동기는 우리말과 이어져요.","있는 그대로 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#1','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C2',1,'mc','auto','「한글」을 바르게 설명한 것은 무엇인가요?',ARRAY['K4-2-u2-X01','K4-2-u2-X06']::text[],false,'{"seq":1,"concept":"K4-2-u2-C2","difficulty":1,"kind":"mc","stem":"「한글」을 바르게 설명한 것은 무엇인가요?","options":[{"t":"우리말을 눈에 보이게 적는 글자","correct":true},{"t":"우리가 입으로 하는 말 그 자체","mis":"K4-2-u2-X01"},{"t":"옛날에만 쓰고 지금은 쓰지 않는 글자","mis":"K4-2-u2-X06"},{"t":"다른 나라에서 빌려 온 글자","mis":"K4-2-u2-X01"}],"explanation":["말이 아니에요.","지금도 날마다 써요.","우리말을 적는 글자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#2','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C6',1,'ox','auto','오늘 정한 모둠 약속을 한 달 뒤에도 정확하게 지키려면 글로 적어 두는 것이 좋아요.',ARRAY['K4-2-u2-X03']::text[],false,'{"seq":2,"concept":"K4-2-u2-C6","difficulty":1,"kind":"ox","stem":"오늘 정한 모둠 약속을 한 달 뒤에도 정확하게 지키려면 글로 적어 두는 것이 좋아요.","answer":"O","reason_options":[{"t":"말은 잊히기 쉽고, 적어 두면 오래 정확하게 남길 수 있기 때문에","correct":true},{"t":"말을 할 수 없을 때만 글로 적기 때문에","mis":"K4-2-u2-X03"}],"mis":"K4-2-u2-X03","explanation":["한 달은 길어요.","말은 잊혀요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#3','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C8',1,'mc','auto','장면 ㉮에서 문자가 한 역할은 무엇인가요?',ARRAY['K4-2-u2-X05','K4-2-u2-X03','K4-2-u2-X04']::text[],false,'{"seq":3,"concept":"K4-2-u2-C8","difficulty":1,"kind":"mc","stem":"장면 ㉮에서 문자가 한 역할은 무엇인가요?","options":[{"t":"지난 일을 알 수 있게 한다","correct":true},{"t":"멀리 있는 사람에게 생각을 전한다","mis":"K4-2-u2-X05"},{"t":"목이 아플 때 말을 대신한다","mis":"K4-2-u2-X03"},{"t":"보는 사람마다 뜻을 다르게 짐작하게 한다","mis":"K4-2-u2-X04"}],"explanation":["할아버지가 젊었을 때 공책이에요.","그때 동네를 알았어요.","지난 일이에요."],"asset":{"type":"passage","lines":["㉮ 할아버지가 젊었을 때 쓴 공책을 읽고 그때 동네 모습을 알게 되었다","㉯ 다른 도시로 이사 간 친구에게 편지를 보내 소식을 전했다","㉰ 책을 돌려줄 날짜를 달력에 적어 두었다"],"title":"문자가 쓰인 또 다른 세 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#4','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C12',1,'mc','auto','자음자 ㅅ이 본뜬 것은 무엇인가요?',ARRAY['K4-2-u2-X09']::text[],false,'{"seq":4,"concept":"K4-2-u2-C12","difficulty":1,"kind":"mc","stem":"자음자 ㅅ이 본뜬 것은 무엇인가요?","options":[{"t":"이의 모양","correct":true},{"t":"입의 모양","mis":"K4-2-u2-X09"},{"t":"목구멍의 모양","mis":"K4-2-u2-X09"},{"t":"평평한 땅","mis":"K4-2-u2-X09"}],"explanation":["ㅁ은 입이에요.","ㅇ은 목구멍이에요.","ㅅ은 이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#5','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C21',1,'mc','auto','조선어학회 사람들이 모은 것은 무엇인가요?',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":5,"concept":"K4-2-u2-C21","difficulty":1,"kind":"mc","stem":"조선어학회 사람들이 모은 것은 무엇인가요?","options":[{"t":"우리말 낱말과 그 뜻","correct":true},{"t":"일본어 낱말","mis":"K4-2-u2-X18"},{"t":"옛날 그림","mis":"K4-2-u2-X18"},{"t":"외국 노래","mis":"K4-2-u2-X18"}],"explanation":["2번 줄을 봐요.","사전을 만들려고 했어요.","우리말 낱말과 뜻이에요."],"asset":{"type":"passage","lines":["1 일제 강점기에는 우리말을 마음껏 쓰기 어려운 때가 있었어요.","2 조선어학회 사람들은 우리말 낱말과 뜻을 모아 사전을 만들기로 했어요.","3 여러 해 동안 낱말을 모으고 뜻을 적어 사전 원고를 쌓아 갔어요.","4 1942년, 일본 경찰이 학회 사람들을 잡아가고 원고도 빼앗아 갔어요.","5 학회 사람들은 감옥에 갇혀 큰 고생을 했어요.","6 광복을 맞은 1945년 가을, 서울역의 한 창고에서 원고 뭉치가 다시 발견되었어요.","7 학회 사람들은 원고를 다시 다듬어 마침내 우리말 사전을 펴내기 시작했어요."],"title":"「원고 상자를 지킨 사람들」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#6','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C30',1,'mc','auto','「뉴 아이템 입고!」를 우리말로 바르게 고친 것은 무엇인가요?',ARRAY['K4-2-u2-X25']::text[],false,'{"seq":6,"concept":"K4-2-u2-C30","difficulty":1,"kind":"mc","stem":"「뉴 아이템 입고!」를 우리말로 바르게 고친 것은 무엇인가요?","options":[{"t":"「새 물건 들어옴!」","correct":true},{"t":"「뉴 물건 들어옴!」","mis":"K4-2-u2-X25"},{"t":"「새 아이템 입고!」","mis":"K4-2-u2-X25"},{"t":"「NEW ITEM 입고!」","mis":"K4-2-u2-X25"}],"explanation":["뉴는 새예요.","아이템은 물건이에요.","둘 다 바꿔요."],"asset":{"type":"passage","lines":["뉴 아이템 입고!","오픈 기념 세일 — 모든 펜 할인"],"title":"학교 앞 문구점 안내문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#7','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C36',1,'mc','auto','보고하는 글의 「처음」에 들어갈 것은 무엇인가요?',ARRAY['K4-2-u2-X44','K4-2-u2-X41']::text[],false,'{"seq":7,"concept":"K4-2-u2-C36","difficulty":1,"kind":"mc","stem":"보고하는 글의 「처음」에 들어갈 것은 무엇인가요?","options":[{"t":"조사 대상·기간·동기·방법","correct":true},{"t":"조사 소감","mis":"K4-2-u2-X44"},{"t":"참고 자료의 출처만","mis":"K4-2-u2-X44"},{"t":"조사하지 않은 짐작","mis":"K4-2-u2-X41"}],"explanation":["어떻게 조사했나요?","처음은 과정이에요.","대상·기간·동기·방법이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#8','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C52',1,'mc','auto','「엷고」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-2-u2-X48']::text[],false,'{"seq":8,"concept":"K4-2-u2-C52","difficulty":1,"kind":"mc","stem":"「엷고」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[열꼬]","correct":true},{"t":"[엽꼬]","mis":"K4-2-u2-X48"},{"t":"[열고]","mis":"K4-2-u2-X48"},{"t":"[엷꼬]","mis":"K4-2-u2-X48"}],"explanation":["ㄼ 뒤에 자음이 와요.","[ㄹ]로 나요.","뒤는 된소리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#9','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C4',2,'mc','auto','받아쓰기에서 「하지 안았다」를 「하지 않았다」로 고쳐야 하는 까닭은 무엇인가요?',ARRAY['K4-2-u2-X02','K4-2-u2-X29']::text[],false,'{"seq":9,"concept":"K4-2-u2-C4","difficulty":2,"kind":"mc","stem":"받아쓰기에서 「하지 안았다」를 「하지 않았다」로 고쳐야 하는 까닭은 무엇인가요?","options":[{"t":"받침 하나 때문에 「껴안았다」는 뜻으로 읽힐 수 있기 때문에","correct":true},{"t":"소리가 같으니 고치지 않아도 되기 때문에","mis":"K4-2-u2-X02"},{"t":"글씨를 예쁘게 쓰기 위해서이기 때문에","mis":"K4-2-u2-X29"},{"t":"받침은 빼고 써도 되기 때문에","mis":"K4-2-u2-X02"}],"explanation":["안았다는 껴안았다예요.","뜻이 바뀌어요.","받침을 바르게 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#10','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C18',2,'mc','auto','외국 친구가 자기 나라 글자를 소개했어요. 알맞은 태도는 무엇인가요?',ARRAY['K4-2-u2-X16','K4-2-u2-X17']::text[],false,'{"seq":10,"concept":"K4-2-u2-C18","difficulty":2,"kind":"mc","stem":"외국 친구가 자기 나라 글자를 소개했어요. 알맞은 태도는 무엇인가요?","options":[{"t":"그 글자도 자기 말을 적어 온 소중한 글자로 존중하며 듣는다","correct":true},{"t":"한글보다 못한 글자라고 말해 준다","mis":"K4-2-u2-X16"},{"t":"글자는 다 비슷하니 한글 자랑은 하지 않는다","mis":"K4-2-u2-X17"},{"t":"그 글자는 배울 필요가 없다고 말한다","mis":"K4-2-u2-X16"}],"explanation":["다른 글자도 소중해요.","깎아내리지 않아요.","존중하며 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#11','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C27',2,'mc','auto','한글을 아끼는 마음을 가장 잘 보여 주는 모습은 무엇인가요?',ARRAY['K4-2-u2-X22','K4-2-u2-X21']::text[],false,'{"seq":11,"concept":"K4-2-u2-C27","difficulty":2,"kind":"mc","stem":"한글을 아끼는 마음을 가장 잘 보여 주는 모습은 무엇인가요?","options":[{"t":"모르는 낱말은 사전에서 찾고, 받침까지 바르게 적으려고 애쓴다","correct":true},{"t":"외국어를 쓰는 친구를 보면 크게 꾸짖는다","mis":"K4-2-u2-X22"},{"t":"사전을 만들 수 없으니 나와는 상관없다고 여긴다","mis":"K4-2-u2-X21"},{"t":"한글날 하루만 한글을 아낀다","mis":"K4-2-u2-X21"}],"explanation":["내 생활에서 해요.","꾸짖는 일이 아니에요.","꾸준히 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#12','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C32',2,'mc','auto','할머니가 「수익」을 알아듣지 못하신 까닭은 무엇인가요?',ARRAY['K4-2-u2-X26','K4-2-u2-X27','K4-2-u2-X02']::text[],false,'{"seq":12,"concept":"K4-2-u2-C32","difficulty":2,"kind":"mc","stem":"할머니가 「수익」을 알아듣지 못하신 까닭은 무엇인가요?","options":[{"t":"지아가 할머니께서 모르시는 줄임말을 썼기 때문에","correct":true},{"t":"할머니께서 문자를 잘못 읽으셨기 때문에","mis":"K4-2-u2-X26"},{"t":"줄임말은 친구끼리도 절대 쓰면 안 되기 때문에","mis":"K4-2-u2-X27"},{"t":"지아가 받침을 틀리게 썼기 때문에","mis":"K4-2-u2-X02"}],"explanation":["수익은 수학 익힘책이에요.","할머니는 모르세요.","듣는 사람을 살펴요."],"asset":{"type":"speech","turns":[{"who":"지아","text":"할머니, 오늘 수익 다 했어요!"},{"who":"할머니","text":"수익? 우리 지아가 장사라도 했니?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#13','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C41',2,'error','auto','하준이의 결과를 옮긴 문장이에요. 결과를 부풀린 친구는 누구인가요?',ARRAY['K4-2-u2-X35','K4-2-u2-X40']::text[],false,'{"seq":13,"concept":"K4-2-u2-C41","difficulty":2,"kind":"error","stem":"하준이의 결과를 옮긴 문장이에요. 결과를 부풀린 친구는 누구인가요?","options":[{"t":"친구 가 — 「거의 모든 게시물에 외국어가 쓰여 있었다.」","correct":true,"mis_target":"K4-2-u2-X35"},{"t":"친구 나 — 「20장 가운데 8장에 외국어가 들어 있었다.」","mis":"K4-2-u2-X35"},{"t":"친구 다 — 「우리말로만 쓴 게시물은 12장이었다.」","mis":"K4-2-u2-X40"}],"explanation":["8장은 20장 가운데예요.","「거의 모든」일까요?","친구 가가 부풀렸어요."],"asset":{"type":"passage","lines":["조사 대상 — 우리 학교 3·4층 복도 게시물 20장","조사 방법 — 직접 보고 기록하기, 게시물을 만든 사람 면담하기","결과 ① — 외국어가 들어간 것 8장, 우리말로만 쓴 것 12장","결과 ② — 「클린 데이」 3장 · 「이벤트」 2장 · 「버스」 2장 · 「컴퓨터」 1장","면담 — 게시물을 만든 6학년 두 명: 「눈에 잘 띄어서」, 「다들 그렇게 써서」"],"title":"하준이의 조사 자료 「우리 학교 복도 게시물에 쓰인 외국어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#14','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C38',2,'mc','auto','하준이가 「게시물에 외국어를 쓴 까닭」을 알아보려면 알맞은 방법은 무엇인가요?',ARRAY['K4-2-u2-X33','K4-2-u2-X31']::text[],false,'{"seq":14,"concept":"K4-2-u2-C38","difficulty":2,"kind":"mc","stem":"하준이가 「게시물에 외국어를 쓴 까닭」을 알아보려면 알맞은 방법은 무엇인가요?","options":[{"t":"게시물을 만든 사람을 면담한다","correct":true},{"t":"게시물 수를 세기만 한다","mis":"K4-2-u2-X33"},{"t":"사전에서 「게시물」을 찾는다","mis":"K4-2-u2-X33"},{"t":"조사 방법을 다섯 가지 모두 쓴다","mis":"K4-2-u2-X31"}],"explanation":["까닭은 직접 물어요.","만든 사람이 알아요.","면담이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#15','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C43',2,'mc','auto','하준이 글의 「조사 소감」 칸에 들어갈 문장은 무엇인가요?',ARRAY['K4-2-u2-X39']::text[],false,'{"seq":15,"concept":"K4-2-u2-C43","difficulty":2,"kind":"mc","stem":"하준이 글의 「조사 소감」 칸에 들어갈 문장은 무엇인가요?","options":[{"t":"우리말로 바꿀 수 있는 말이 생각보다 많아서 놀랐다","correct":true},{"t":"20장 가운데 8장에 외국어가 들어 있었다","mis":"K4-2-u2-X39"},{"t":"6학년 두 명을 면담했다","mis":"K4-2-u2-X39"},{"t":"「클린 데이」가 3장이었다","mis":"K4-2-u2-X39"}],"explanation":["소감은 내 생각이에요.","사실은 조사한 내용 칸이에요.","놀란 마음이 소감이에요."],"asset":{"type":"passage","lines":["조사 대상 — 우리 학교 3·4층 복도 게시물 20장","조사 방법 — 직접 보고 기록하기, 게시물을 만든 사람 면담하기","결과 ① — 외국어가 들어간 것 8장, 우리말로만 쓴 것 12장","결과 ② — 「클린 데이」 3장 · 「이벤트」 2장 · 「버스」 2장 · 「컴퓨터」 1장","면담 — 게시물을 만든 6학년 두 명: 「눈에 잘 띄어서」, 「다들 그렇게 써서」"],"title":"하준이의 조사 자료 「우리 학교 복도 게시물에 쓰인 외국어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#16','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C51',2,'mc','auto','문구 이름 가운데 우리말을 살려 지은 이름은 무엇인가요?',ARRAY['K4-2-u2-X46']::text[],false,'{"seq":16,"concept":"K4-2-u2-C51","difficulty":2,"kind":"mc","stem":"문구 이름 가운데 우리말을 살려 지은 이름은 무엇인가요?","options":[{"t":"쓱쓱 연필","correct":true},{"t":"스마일 펜슬","mis":"K4-2-u2-X46"},{"t":"드림 노트","mis":"K4-2-u2-X46"},{"t":"해피 스쿨 백","mis":"K4-2-u2-X46"}],"explanation":["쓱쓱은 우리말이에요.","연필도 우리말이에요.","쓱쓱 연필이에요."],"asset":{"type":"passage","lines":["반짝 지우개 · 스마일 펜슬 · 쓱쓱 연필","해피 스쿨 백 · 소복 공책 · 드림 노트"],"title":"문구점 진열대에서 찾은 이름 여섯 개 (지어낸 이름)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#17','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C14',3,'mc','auto','ㄷ과 ㄹ을 두고 한 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X10']::text[],false,'{"seq":17,"concept":"K4-2-u2-C14","difficulty":3,"kind":"mc","stem":"ㄷ과 ㄹ을 두고 한 말로 알맞은 것은 무엇인가요?","options":[{"t":"모양은 닮았지만 ㄹ은 ㄷ에 획을 더한 글자가 아니다","correct":true},{"t":"모양이 닮았으니 ㄹ은 ㄷ에 획을 더한 글자다","mis":"K4-2-u2-X10"},{"t":"ㄷ에 획을 더한 글자는 ㄴ이다","mis":"K4-2-u2-X10"},{"t":"ㄹ에 획을 더하면 소리가 약해진다","mis":"K4-2-u2-X10"}],"explanation":["ㄷ에 획을 더하면 ㅌ이에요.","ㄴ은 ㄷ보다 먼저예요.","ㄹ은 닮았을 뿐이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#18','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C24',3,'mc','auto','감옥에서 고생하고도 원고를 다시 다듬어 사전을 펴낸 사람들이 가장 소중하게 여긴 것은 무엇인가요?',ARRAY['K4-2-u2-X20','K4-2-u2-X22']::text[],false,'{"seq":18,"concept":"K4-2-u2-C24","difficulty":3,"kind":"mc","stem":"감옥에서 고생하고도 원고를 다시 다듬어 사전을 펴낸 사람들이 가장 소중하게 여긴 것은 무엇인가요?","options":[{"t":"우리말과 글","correct":true},{"t":"자기 이름","mis":"K4-2-u2-X20"},{"t":"많은 돈","mis":"K4-2-u2-X20"},{"t":"일본어","mis":"K4-2-u2-X22"}],"explanation":["고생해도 멈추지 않았어요.","끝까지 한 일이 무엇인가요?","우리말과 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#19','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C31',3,'error','auto','문구점 안내문을 고치는 방법을 말했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K4-2-u2-X24','K4-2-u2-X25']::text[],false,'{"seq":19,"concept":"K4-2-u2-C31","difficulty":3,"kind":"error","stem":"문구점 안내문을 고치는 방법을 말했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 다 — 「‘펜’도 외국어니까 새 우리말을 지어 바꾸자.」","correct":true,"mis_target":"K4-2-u2-X24"},{"t":"친구 가 — 「‘오픈 기념 세일’은 ‘문 연 기념 할인’으로 바꿀 수 있어.」","mis":"K4-2-u2-X24"},{"t":"친구 나 — 「‘펜’은 굳은 말이라 그대로 둬도 돼.」","mis":"K4-2-u2-X25"}],"explanation":["펜은 굳은 말이에요.","무리하게 새말을 짓지 않아요.","친구 다가 알맞지 않아요."],"asset":{"type":"passage","lines":["뉴 아이템 입고!","오픈 기념 세일 — 모든 펜 할인"],"title":"학교 앞 문구점 안내문"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#20','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C48',3,'mc','auto','하준이의 메모 가운데 고치지 않아도 되는 것은 무엇인가요?',ARRAY['K4-2-u2-X35','K4-2-u2-X36','K4-2-u2-X37']::text[],false,'{"seq":20,"concept":"K4-2-u2-C48","difficulty":3,"kind":"mc","stem":"하준이의 메모 가운데 고치지 않아도 되는 것은 무엇인가요?","options":[{"t":"④ 외국어가 들어간 게시물 수는 표로 나타내자","correct":true},{"t":"① 8장을 「거의 모든 게시물」이라고 쓰자","mis":"K4-2-u2-X35"},{"t":"② 한 명의 말을 모두의 까닭으로 쓰자","mis":"K4-2-u2-X36"},{"t":"③ 찾은 곳을 적지 않고 옮기자","mis":"K4-2-u2-X37"}],"explanation":["①은 부풀렸어요.","②는 넓혔어요.","③은 출처가 없어요."],"asset":{"type":"passage","lines":["① 「8장은 많아 보이니까 ‘거의 모든 게시물’에 외국어가 있다고 쓰자.」","② 「6학년 한 명이 ‘눈에 잘 띄어서’라고 했으니 모두 그렇다고 쓰자.」","③ 「‘클린 데이’를 바꿀 우리말은 찾은 곳을 적지 않고 옮기자.」","④ 「외국어가 들어간 게시물 수는 표로 나타내자.」"],"title":"하준이가 쓰기 전에 적은 메모 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#21','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C44',3,'mc','auto','도겸이가 ㉮·㉰가 아니라 ㉯를 고른 까닭으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X07','K4-2-u2-X41']::text[],false,'{"seq":21,"concept":"K4-2-u2-C44","difficulty":3,"kind":"mc","stem":"도겸이가 ㉮·㉰가 아니라 ㉯를 고른 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"일주일 안에 내가 직접 묻고 보고 찾을 수 있는 주제이기 때문에","correct":true},{"t":"가장 크고 멋진 주제이기 때문에","mis":"K4-2-u2-X07"},{"t":"짝이 정한 주제를 따랐기 때문에","mis":"K4-2-u2-X07"},{"t":"조사하지 않아도 답을 알기 때문에","mis":"K4-2-u2-X41"}],"explanation":["㉮는 너무 넓어요.","㉰는 직접 물을 수 없어요.","㉯는 직접 할 수 있어요."],"asset":{"type":"passage","lines":["㉮ 전 세계 어린이가 쓰는 모든 인사말","㉯ 우리 반 친구들이 아침에 쓰는 인사말","㉰ 조선 시대 사람들이 날마다 쓴 모든 말"],"title":"도겸이가 떠올린 주제 후보"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#22','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C49',3,'mc','auto','좋은 한글 사랑 시를 가르는 기준으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X45']::text[],false,'{"seq":22,"concept":"K4-2-u2-C49","difficulty":3,"kind":"mc","stem":"좋은 한글 사랑 시를 가르는 기준으로 알맞은 것은 무엇인가요?","options":[{"t":"길이보다 한글에 대한 내 마음이 또렷하게 담겼는가","correct":true},{"t":"행이 몇 줄인가","mis":"K4-2-u2-X45"},{"t":"어려운 낱말을 몇 개 썼는가","mis":"K4-2-u2-X45"},{"t":"한글과 상관없어도 재미있는가","mis":"K4-2-u2-X45"}],"explanation":["줄 수가 아니에요.","어려운 낱말도 아니에요.","마음이 담겼나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#23','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C17',4,'mc','auto','「국물」과 「밟고」를 함께 보고 한 말 가운데 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X14','K4-2-u2-X15','K4-2-u2-X47']::text[],false,'{"seq":23,"concept":"K4-2-u2-C17","difficulty":4,"kind":"mc","stem":"「국물」과 「밟고」를 함께 보고 한 말 가운데 가장 알맞은 것은 무엇인가요?","options":[{"t":"「둘 다 소리는 바뀌지만 뜻을 알아보기 쉽게 글자는 원래대로 적어. 그래서 바른 발음도 따로 익혀야 해.」","correct":true},{"t":"「소리가 바뀌니 한글은 규칙 없는 글자야.」","mis":"K4-2-u2-X14"},{"t":"「앞으로 ‘궁물’, ‘밥고’로 적자.」","mis":"K4-2-u2-X15"},{"t":"「‘밟고’도 대부분의 ㄼ처럼 [ㄹ]로 소리 나니 [발꼬]야.」","mis":"K4-2-u2-X47"}],"explanation":["짜임은 그대로예요.","적기와 소리가 달라요.","바른 발음도 익혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#24','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C6',4,'essay','teacher','문자가 없다면 어려워질 일 두 가지를 쓰고, 「문자는 말을 할 수 없을 때만 필요하다」는 생각이 왜 알맞지 않은지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u2-C6","difficulty":4,"kind":"essay","stem":"문자가 없다면 어려워질 일 두 가지를 쓰고, 「문자는 말을 할 수 없을 때만 필요하다」는 생각이 왜 알맞지 않은지 쓰세요.","answer_guide":{"answer":"예: 문자가 없다면 책을 돌려줄 날짜를 잊어버리기 쉽고, 다른 도시로 이사 간 친구에게 소식을 정확하게 전하기 어렵다. 말을 할 수 있어도 말은 전해지는 동안 바뀌고 잊히기 때문에, 오래 남기고 멀리 정확하게 전하려면 문자가 필요하다. 그래서 「말을 할 수 없을 때만」은 알맞지 않다.","scoring_points":["문자가 없을 때 어려워질 일 두 가지를 썼는가","말이 바뀌고 잊힌다는 점을 들었는가","「말을 할 수 없을 때만」이 알맞지 않은 까닭을 썼는가"]},"explanation":["기억 · 멀리 · 지난 일을 떠올려요.","말은 바뀌고 잊혀요.","말을 할 수 있어도 필요해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_a#25','kor',4,2,'u2','','g4_2_kor_u2_review_a','unit_review','K4-2-u2-C41',4,'essay','teacher','하준이의 메모 ①~③을 바르게 고쳐 쓰고, 각각 왜 고쳐야 하는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u2-C41","difficulty":4,"kind":"essay","stem":"하준이의 메모 ①~③을 바르게 고쳐 쓰고, 각각 왜 고쳐야 하는지 쓰세요.","answer_guide":{"answer":"예: ①은 「20장 가운데 8장에 외국어가 있었다」로 고친다. 8장을 「거의 모든」이라고 하면 결과를 부풀리기 때문이다. ②는 「6학년 한 명은 ‘눈에 잘 띄어서’, 다른 한 명은 ‘다들 그렇게 써서’라고 했다」로 고친다. 한 명의 말을 모두의 까닭으로 넓히면 안 되기 때문이다. ③은 우리말을 찾은 곳의 이름과 찾아본 낱말을 출처로 적는다. 남의 자료를 내 것처럼 쓰면 안 되기 때문이다.","scoring_points":["①을 수대로 고치고 까닭을 썼는가","②를 들은 그대로 고치고 까닭을 썼는가","③에 출처를 밝히고 까닭을 썼는가"]},"explanation":["부풀리지 않아요.","넓히지 않아요.","출처를 밝혀요."],"asset":{"type":"passage","lines":["① 「8장은 많아 보이니까 ‘거의 모든 게시물’에 외국어가 있다고 쓰자.」","② 「6학년 한 명이 ‘눈에 잘 띄어서’라고 했으니 모두 그렇다고 쓰자.」","③ 「‘클린 데이’를 바꿀 우리말은 찾은 곳을 적지 않고 옮기자.」","④ 「외국어가 들어간 게시물 수는 표로 나타내자.」"],"title":"하준이가 쓰기 전에 적은 메모 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#1','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C3',1,'ox','auto','한글날은 세종 대왕이 만든 우리 글자를 널리 알린 것을 기념하는 날이에요.',ARRAY['K4-2-u2-X06']::text[],false,'{"seq":1,"concept":"K4-2-u2-C3","difficulty":1,"kind":"ox","stem":"한글날은 세종 대왕이 만든 우리 글자를 널리 알린 것을 기념하는 날이에요.","answer":"O","reason_options":[{"t":"한글을 널리 알린 일을 기념하고 소중함을 되새기는 날이기 때문에","correct":true},{"t":"세종 대왕이 태어난 날이기 때문에","mis":"K4-2-u2-X06"}],"mis":"K4-2-u2-X06","explanation":["10월 9일이에요.","널리 알린 일을 기념해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#2','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C5',1,'mc','auto','문자를 바르게 설명한 것은 무엇인가요?',ARRAY['K4-2-u2-X03','K4-2-u2-X04','K4-2-u2-X01']::text[],false,'{"seq":2,"concept":"K4-2-u2-C5","difficulty":1,"kind":"mc","stem":"문자를 바르게 설명한 것은 무엇인가요?","options":[{"t":"말을 눈에 보이게 적는 약속된 기호","correct":true},{"t":"말을 할 수 없을 때만 쓰는 손짓","mis":"K4-2-u2-X03"},{"t":"바위에 그린 사냥 그림","mis":"K4-2-u2-X04"},{"t":"입으로 하는 말 그 자체","mis":"K4-2-u2-X01"}],"explanation":["말과 문자는 달라요.","눈에 보이게 적어요.","약속된 기호예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#3','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C8',1,'mc','auto','장면 ㉯에서 문자가 한 역할은 무엇인가요?',ARRAY['K4-2-u2-X05','K4-2-u2-X03']::text[],false,'{"seq":3,"concept":"K4-2-u2-C8","difficulty":1,"kind":"mc","stem":"장면 ㉯에서 문자가 한 역할은 무엇인가요?","options":[{"t":"멀리 있는 사람에게 생각을 전한다","correct":true},{"t":"지난 일을 알 수 있게 한다","mis":"K4-2-u2-X05"},{"t":"잊지 않게 기억을 돕는다","mis":"K4-2-u2-X05"},{"t":"말을 못 할 때만 쓰인다","mis":"K4-2-u2-X03"}],"explanation":["친구는 이사 갔어요.","멀리 있어요.","편지로 전했어요."],"asset":{"type":"passage","lines":["㉮ 할아버지가 젊었을 때 쓴 공책을 읽고 그때 동네 모습을 알게 되었다","㉯ 다른 도시로 이사 간 친구에게 편지를 보내 소식을 전했다","㉰ 책을 돌려줄 날짜를 달력에 적어 두었다"],"title":"문자가 쓰인 또 다른 세 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#4','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C13',1,'mc','auto','ㅅ에 획을 하나 더한 글자는 무엇인가요?',ARRAY['K4-2-u2-X10']::text[],false,'{"seq":4,"concept":"K4-2-u2-C13","difficulty":1,"kind":"mc","stem":"ㅅ에 획을 하나 더한 글자는 무엇인가요?","options":[{"t":"ㅈ","correct":true},{"t":"ㅊ","mis":"K4-2-u2-X10"},{"t":"ㅇ","mis":"K4-2-u2-X10"},{"t":"ㄹ","mis":"K4-2-u2-X10"}],"explanation":["ㅅ → ㅈ → ㅊ 이에요.","하나만 더해요.","ㅈ이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#5','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C25',1,'ox','auto','한글날의 처음 이름은 「가갸날」이었어요.',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":5,"concept":"K4-2-u2-C25","difficulty":1,"kind":"ox","stem":"한글날의 처음 이름은 「가갸날」이었어요.","answer":"O","reason_options":[{"t":"글자를 「가, 갸, 거, 겨……」 하고 익히던 모습에서 따온 이름이기 때문에","correct":true},{"t":"가게 이름을 한글로 바꾼 날이기 때문에","mis":"K4-2-u2-X18"}],"mis":"K4-2-u2-X18","explanation":["2번 줄을 봐요.","3번 줄이 까닭이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["1 1926년, 조선어연구회 사람들은 훈민정음을 기리는 날을 정했어요.","2 그 날의 처음 이름은 「가갸날」이었어요.","3 「가, 갸, 거, 겨……」 하고 글자를 익히던 모습에서 따온 이름이에요.","4 2년 뒤인 1928년에 이름을 「한글날」로 바꾸었어요.","5 오늘날 우리는 10월 9일을 한글날로 기념해요."],"title":"「한글날이 생긴 날」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#6','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C34',1,'mc','auto','「내비게이션」을 다듬은 우리말은 무엇인가요?',ARRAY['K4-2-u2-X19']::text[],false,'{"seq":6,"concept":"K4-2-u2-C34","difficulty":1,"kind":"mc","stem":"「내비게이션」을 다듬은 우리말은 무엇인가요?","options":[{"t":"길도우미","correct":true},{"t":"안전문","mis":"K4-2-u2-X19"},{"t":"누리집","mis":"K4-2-u2-X19"},{"t":"알림창","mis":"K4-2-u2-X19"}],"explanation":["길을 알려 줘요.","도와주는 것이에요.","길도우미예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#7','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C37',1,'mc','auto','직접 만나 물어보는 조사 방법은 무엇인가요?',ARRAY['K4-2-u2-X33']::text[],false,'{"seq":7,"concept":"K4-2-u2-C37","difficulty":1,"kind":"mc","stem":"직접 만나 물어보는 조사 방법은 무엇인가요?","options":[{"t":"면담 조사","correct":true},{"t":"설문 조사","mis":"K4-2-u2-X33"},{"t":"사전 찾아보기","mis":"K4-2-u2-X33"},{"t":"책 조사","mis":"K4-2-u2-X33"}],"explanation":["질문지가 아니에요.","직접 만나요.","면담 조사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#8','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C55',1,'mc','auto','「팝업창」을 다듬은 우리말은 무엇인가요?',ARRAY['K4-2-u2-X19']::text[],false,'{"seq":8,"concept":"K4-2-u2-C55","difficulty":1,"kind":"mc","stem":"「팝업창」을 다듬은 우리말은 무엇인가요?","options":[{"t":"알림창","correct":true},{"t":"댓글","mis":"K4-2-u2-X19"},{"t":"누리꾼","mis":"K4-2-u2-X19"},{"t":"길도우미","mis":"K4-2-u2-X19"}],"explanation":["갑자기 뜨는 창이에요.","무언가 알려 줘요.","알림창이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#9','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C17',2,'ox','auto','「먹는다」가 [멍는다]로 소리 나는 것은 한글이 짜임새 없는 글자라는 뜻이에요.',ARRAY['K4-2-u2-X14']::text[],false,'{"seq":9,"concept":"K4-2-u2-C17","difficulty":2,"kind":"ox","stem":"「먹는다」가 [멍는다]로 소리 나는 것은 한글이 짜임새 없는 글자라는 뜻이에요.","answer":"X","reason_options":[{"t":"글자의 짜임은 그대로이고 말소리가 이어지면서 소리가 바뀌기도 하기 때문에","correct":true},{"t":"한 글자는 언제나 한 소리만 내야 하기 때문에","mis":"K4-2-u2-X14"}],"mis":"K4-2-u2-X14","explanation":["국물도 그랬어요.","짜임은 그대로예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#10','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C16',2,'mc','auto','비슷한 소리를 내는 ㅂ·ㅍ·ㅃ의 모양을 보고 알 수 있는 것은 무엇인가요?',ARRAY['K4-2-u2-X10','K4-2-u2-X12','K4-2-u2-X13']::text[],false,'{"seq":10,"concept":"K4-2-u2-C16","difficulty":2,"kind":"mc","stem":"비슷한 소리를 내는 ㅂ·ㅍ·ㅃ의 모양을 보고 알 수 있는 것은 무엇인가요?","options":[{"t":"비슷한 소리를 내는 글자는 모양도 닮았다","correct":true},{"t":"모양이 닮은 글자는 모두 획을 더한 사이다","mis":"K4-2-u2-X10"},{"t":"글자 모양은 소리와 아무 상관이 없다","mis":"K4-2-u2-X12"},{"t":"세 글자는 언제나 똑같은 소리를 낸다","mis":"K4-2-u2-X13"}],"explanation":["세 글자를 나란히 봐요.","모양이 닮았어요.","소리도 비슷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#11','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C27',2,'ox','auto','한글 사랑은 사전을 만들 만큼 대단한 사람만 할 수 있는 일이에요.',ARRAY['K4-2-u2-X21']::text[],false,'{"seq":11,"concept":"K4-2-u2-C27","difficulty":2,"kind":"ox","stem":"한글 사랑은 사전을 만들 만큼 대단한 사람만 할 수 있는 일이에요.","answer":"X","reason_options":[{"t":"받침까지 바르게 쓰기처럼 내 생활에서 할 수 있는 일도 한글 사랑이기 때문에","correct":true},{"t":"보통 사람이 하는 일은 한글에 아무 도움이 되지 않기 때문에","mis":"K4-2-u2-X21"}],"mis":"K4-2-u2-X21","explanation":["나도 할 수 있어요.","작은 실천도 한글 사랑이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#12','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C32',2,'ox','auto','뜻을 아는 같은 반 짝에게 「수익 몇 쪽까지야?」라고 묻는 것은 괜찮아요.',ARRAY['K4-2-u2-X27']::text[],false,'{"seq":12,"concept":"K4-2-u2-C32","difficulty":2,"kind":"ox","stem":"뜻을 아는 같은 반 짝에게 「수익 몇 쪽까지야?」라고 묻는 것은 괜찮아요.","answer":"O","reason_options":[{"t":"줄임말은 듣는 사람이 알아듣는지와 상황을 살펴 쓰면 되기 때문에","correct":true},{"t":"줄임말은 어디서든 절대 쓰면 안 되기 때문에","mis":"K4-2-u2-X27"}],"mis":"K4-2-u2-X27","explanation":["짝은 뜻을 알아요.","상황도 괜찮아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#13','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C46',2,'mc','auto','하준이의 면담 결과를 바르게 옮긴 것은 무엇인가요?',ARRAY['K4-2-u2-X36','K4-2-u2-X40']::text[],false,'{"seq":13,"concept":"K4-2-u2-C46","difficulty":2,"kind":"mc","stem":"하준이의 면담 결과를 바르게 옮긴 것은 무엇인가요?","options":[{"t":"6학년 두 명은 「눈에 잘 띄어서」, 「다들 그렇게 써서」라고 답했다","correct":true},{"t":"6학년 모두가 눈에 잘 띄어서 외국어를 쓴다고 답했다","mis":"K4-2-u2-X36"},{"t":"6학년 두 명은 외국어가 더 멋져서라고 답했다","mis":"K4-2-u2-X40"},{"t":"면담한 사람은 한 명도 없었다","mis":"K4-2-u2-X40"}],"explanation":["면담 줄을 봐요.","두 명이에요.","들은 그대로예요."],"asset":{"type":"passage","lines":["조사 대상 — 우리 학교 3·4층 복도 게시물 20장","조사 방법 — 직접 보고 기록하기, 게시물을 만든 사람 면담하기","결과 ① — 외국어가 들어간 것 8장, 우리말로만 쓴 것 12장","결과 ② — 「클린 데이」 3장 · 「이벤트」 2장 · 「버스」 2장 · 「컴퓨터」 1장","면담 — 게시물을 만든 6학년 두 명: 「눈에 잘 띄어서」, 「다들 그렇게 써서」"],"title":"하준이의 조사 자료 「우리 학교 복도 게시물에 쓰인 외국어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#14','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C39',2,'mc','auto','면담할 때 대답이 마음에 들지 않으면 어떻게 하나요?',ARRAY['K4-2-u2-X34']::text[],false,'{"seq":14,"concept":"K4-2-u2-C39","difficulty":2,"kind":"mc","stem":"면담할 때 대답이 마음에 들지 않으면 어떻게 하나요?","options":[{"t":"들은 말을 그대로 적는다","correct":true},{"t":"알맞게 바꾸어 적는다","mis":"K4-2-u2-X34"},{"t":"적지 않고 지운다","mis":"K4-2-u2-X34"},{"t":"내 생각을 덧붙여 대답처럼 적는다","mis":"K4-2-u2-X34"}],"explanation":["바꾸면 안 돼요.","지워도 안 돼요.","그대로 적어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#15','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C47',2,'match','auto','하준이 글의 짜임과 들어갈 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"K4-2-u2-C47","difficulty":2,"kind":"match","stem":"하준이 글의 짜임과 들어갈 내용을 알맞게 이으세요.","pairs":[{"l":"처음","r":"게시물 20장을 직접 보고 기록했다"},{"l":"가운데","r":"20장 가운데 8장에 외국어가 들어 있었다"},{"l":"끝","r":"앞으로 게시물을 만들 때 우리말을 먼저 떠올리겠다"}],"mis":"K4-2-u2-X44","explanation":["처음은 과정이에요.","가운데는 사실이에요.","끝은 내 생각이에요."],"asset":{"type":"passage","lines":["조사 대상 — 우리 학교 3·4층 복도 게시물 20장","조사 방법 — 직접 보고 기록하기, 게시물을 만든 사람 면담하기","결과 ① — 외국어가 들어간 것 8장, 우리말로만 쓴 것 12장","결과 ② — 「클린 데이」 3장 · 「이벤트」 2장 · 「버스」 2장 · 「컴퓨터」 1장","면담 — 게시물을 만든 6학년 두 명: 「눈에 잘 띄어서」, 「다들 그렇게 써서」"],"title":"하준이의 조사 자료 「우리 학교 복도 게시물에 쓰인 외국어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#16','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C54',2,'mc','auto','「밟아」·「밟고」·「밟지」를 모두 「밟-」으로 적는 까닭은 무엇인가요?',ARRAY['K4-2-u2-X13','K4-2-u2-X02','K4-2-u2-X15']::text[],false,'{"seq":16,"concept":"K4-2-u2-C54","difficulty":2,"kind":"mc","stem":"「밟아」·「밟고」·「밟지」를 모두 「밟-」으로 적는 까닭은 무엇인가요?","options":[{"t":"「밟다」에서 온 말임을 알아보기 쉽게 하려고","correct":true},{"t":"소리가 모두 똑같아서","mis":"K4-2-u2-X13"},{"t":"어떻게 적어도 뜻이 같아서","mis":"K4-2-u2-X02"},{"t":"소리 나는 대로 적은 것이라서","mis":"K4-2-u2-X15"}],"explanation":["소리는 저마다 달라요.","모양을 같게 적어요.","뜻이 보이게요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#17','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C17',3,'mc','auto','친구가 「한글은 짜임새 있게 만든 글자니까 어떤 말도 적힌 대로만 소리 나야 해.」라고 했어요. 해 줄 말은 무엇인가요?',ARRAY['K4-2-u2-X13','K4-2-u2-X14','K4-2-u2-X15']::text[],false,'{"seq":17,"concept":"K4-2-u2-C17","difficulty":3,"kind":"mc","stem":"친구가 「한글은 짜임새 있게 만든 글자니까 어떤 말도 적힌 대로만 소리 나야 해.」라고 했어요. 해 줄 말은 무엇인가요?","options":[{"t":"짜임은 규칙적이지만 「국물 → [궁물]」처럼 말소리가 이어지면 소리가 바뀌기도 해.","correct":true},{"t":"맞아. 적힌 대로 소리 나지 않는 말은 잘못 적은 거야.","mis":"K4-2-u2-X13"},{"t":"소리가 바뀌니 한글은 짜임새 없는 글자야.","mis":"K4-2-u2-X14"},{"t":"앞으로는 모두 소리 나는 대로 적어야 해.","mis":"K4-2-u2-X15"}],"explanation":["국물을 떠올려요.","짜임은 그대로예요.","소리가 바뀌기도 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#18','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C20',3,'mc','auto','외국어를 쉬운 우리말로 다듬는 일이 한글을 가꾸는 일인 까닭은 무엇인가요?',ARRAY['K4-2-u2-X22','K4-2-u2-X21','K4-2-u2-X25']::text[],false,'{"seq":18,"concept":"K4-2-u2-C20","difficulty":3,"kind":"mc","stem":"외국어를 쉬운 우리말로 다듬는 일이 한글을 가꾸는 일인 까닭은 무엇인가요?","options":[{"t":"누구나 쉽게 알아듣는 우리말을 살려 쓰게 돕기 때문에","correct":true},{"t":"외국어를 한마디도 못 쓰게 막기 때문에","mis":"K4-2-u2-X22"},{"t":"유명한 사람만 할 수 있는 일이기 때문에","mis":"K4-2-u2-X21"},{"t":"외국어를 더 많이 퍼뜨리기 때문에","mis":"K4-2-u2-X25"}],"explanation":["안전문, 길도우미를 떠올려요.","누구나 알아들어요.","우리말을 살려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#19','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C29',3,'mc','auto','우리말을 바르게 써야 하는 까닭 셋을 바르게 모은 것은 무엇인가요?',ARRAY['K4-2-u2-X29','K4-2-u2-X25','K4-2-u2-X26']::text[],false,'{"seq":19,"concept":"K4-2-u2-C29","difficulty":3,"kind":"mc","stem":"우리말을 바르게 써야 하는 까닭 셋을 바르게 모은 것은 무엇인가요?","options":[{"t":"뜻이 정확하게 통함 · 서로의 마음을 지킴 · 우리말을 아끼고 가꿈","correct":true},{"t":"글씨가 예뻐짐 · 점수가 오름 · 외국어를 몰아냄","mis":"K4-2-u2-X29"},{"t":"외국어를 많이 씀 · 줄임말을 많이 씀 · 말을 빨리 함","mis":"K4-2-u2-X25"},{"t":"듣는 사람은 생각하지 않음 · 내가 편함 · 줄여 씀","mis":"K4-2-u2-X26"}],"explanation":["뜻이 통해요.","마음을 지켜요.","우리말을 가꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#20','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C45',3,'mc','auto','하준이가 설문지를 만든다면 넣기 알맞은 질문은 무엇인가요?',ARRAY['K4-2-u2-X42']::text[],false,'{"seq":20,"concept":"K4-2-u2-C45","difficulty":3,"kind":"mc","stem":"하준이가 설문지를 만든다면 넣기 알맞은 질문은 무엇인가요?","options":[{"t":"복도 게시물에서 외국어를 본 적이 있나요?","correct":true},{"t":"외국어가 많은 게시물은 나쁘지요?","mis":"K4-2-u2-X42"},{"t":"게시물을 본 적이 있고, 좋아하는 색은 무엇인가요?","mis":"K4-2-u2-X42"},{"t":"외국어 게시물을 모두 없애야 하지요?","mis":"K4-2-u2-X42"}],"explanation":["답을 몰아주지 않아요.","하나씩 물어요.","첫째 질문이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#21','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C50',3,'mc','auto','「우리 학교 복도 게시물에 쓰인 외국어」 조사의 동기로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X50']::text[],false,'{"seq":21,"concept":"K4-2-u2-C50","difficulty":3,"kind":"mc","stem":"「우리 학교 복도 게시물에 쓰인 외국어」 조사의 동기로 알맞은 것은 무엇인가요?","options":[{"t":"게시물에 외국어가 많아 보여 우리말로 바꿀 수 있는 말이 얼마나 되는지 알고 싶어서","correct":true},{"t":"게시물 종이가 얼마인지 알고 싶어서","mis":"K4-2-u2-X50"},{"t":"가장 예쁜 게시물을 뽑고 싶어서","mis":"K4-2-u2-X50"},{"t":"게시물을 만든 사람을 혼내고 싶어서","mis":"K4-2-u2-X50"}],"explanation":["우리말 사용과 이어지나요?","알고 싶은 것이 무엇인가요?","외국어와 우리말이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#22','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C51',3,'error','auto','문구 이름 조사 결과를 정리했어요. 알맞지 않게 정리한 친구는 누구인가요?',ARRAY['K4-2-u2-X40','K4-2-u2-X46']::text[],false,'{"seq":22,"concept":"K4-2-u2-C51","difficulty":3,"kind":"error","stem":"문구 이름 조사 결과를 정리했어요. 알맞지 않게 정리한 친구는 누구인가요?","options":[{"t":"친구 다 — 「‘드림 노트’는 우리말을 살린 이름이다.」","correct":true,"mis_target":"K4-2-u2-X40"},{"t":"친구 가 — 「‘소복 공책’은 우리말을 살린 이름이다.」","mis":"K4-2-u2-X40"},{"t":"친구 나 — 「‘스마일 펜슬’은 우리말로 지을 수도 있었다.」","mis":"K4-2-u2-X46"}],"explanation":["드림 노트를 봐요.","드림도 노트도 외국어예요.","친구 다가 잘못 나눴어요."],"asset":{"type":"passage","lines":["반짝 지우개 · 스마일 펜슬 · 쓱쓱 연필","해피 스쿨 백 · 소복 공책 · 드림 노트"],"title":"문구점 진열대에서 찾은 이름 여섯 개 (지어낸 이름)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#23','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C41',4,'mc','auto','하준이의 조사 결과로 쓴 문장 가운데 가장 정확한 것은 무엇인가요?',ARRAY['K4-2-u2-X35','K4-2-u2-X24','K4-2-u2-X36']::text[],false,'{"seq":23,"concept":"K4-2-u2-C41","difficulty":4,"kind":"mc","stem":"하준이의 조사 결과로 쓴 문장 가운데 가장 정확한 것은 무엇인가요?","options":[{"t":"「20장 가운데 8장에 외국어가 들어 있었고, 그 가운데 5장은 우리말로 바꿔 쓸 수 있는 말이었다.」","correct":true},{"t":"「거의 모든 게시물이 외국어로 되어 있었다.」","mis":"K4-2-u2-X35"},{"t":"「외국어 게시물 8장은 모두 우리말로 바꿔야 한다.」","mis":"K4-2-u2-X24"},{"t":"「6학년 모두 외국어가 눈에 띄어서 좋다고 했다.」","mis":"K4-2-u2-X36"}],"explanation":["수를 그대로 써요.","굳은 말 3장을 빼면 5장이에요.","넓히지 않아요."],"asset":{"type":"passage","lines":["조사 대상 — 우리 학교 3·4층 복도 게시물 20장","조사 방법 — 직접 보고 기록하기, 게시물을 만든 사람 면담하기","결과 ① — 외국어가 들어간 것 8장, 우리말로만 쓴 것 12장","결과 ② — 「클린 데이」 3장 · 「이벤트」 2장 · 「버스」 2장 · 「컴퓨터」 1장","면담 — 게시물을 만든 6학년 두 명: 「눈에 잘 띄어서」, 「다들 그렇게 써서」"],"title":"하준이의 조사 자료 「우리 학교 복도 게시물에 쓰인 외국어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#24','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C54',4,'essay','teacher','「밟고」를 소리 나는 대로 「밥고」라고 적으면 안 되는 까닭을 쓰고, 「국물 → [궁물]」과 이어서 한글의 짜임과 말소리의 관계를 설명하세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u2-C54","difficulty":4,"kind":"essay","stem":"「밟고」를 소리 나는 대로 「밥고」라고 적으면 안 되는 까닭을 쓰고, 「국물 → [궁물]」과 이어서 한글의 짜임과 말소리의 관계를 설명하세요.","answer_guide":{"answer":"예: 「밟아」, 「밟고」, 「밟지」를 모두 「밟-」으로 적어야 「밟다」에서 온 말임을 알아보기 쉽기 때문에 「밥고」라고 적으면 안 된다. 「국물」도 [궁물]로 소리 나지만 「국물」로 적는다. 한글은 짜임새 있게 만든 글자이고, 말소리가 이어지면서 소리가 바뀌기도 할 뿐이다. 그래서 바르게 적기와 바른 발음을 함께 익혀야 한다.","scoring_points":["「밥고」로 적으면 안 되는 까닭(뜻을 알아보기)을 썼는가","「국물 → [궁물]」과 이어 설명했는가","짜임은 그대로이고 소리가 바뀌기도 한다고 썼는가"]},"explanation":["밟다 · 밟아 · 밟고를 나란히 봐요.","국물도 같아요.","짜임은 그대로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_b#25','kor',4,2,'u2','','g4_2_kor_u2_review_b','unit_review','K4-2-u2-C47',4,'essay','teacher','하준이의 조사 자료로 보고하는 글의 처음·가운데·끝에 들어갈 내용을 한두 문장씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u2-C47","difficulty":4,"kind":"essay","stem":"하준이의 조사 자료로 보고하는 글의 처음·가운데·끝에 들어갈 내용을 한두 문장씩 쓰세요.","answer_guide":{"answer":"예: 처음 — 복도 게시물에 외국어가 많아 보여서, 우리 학교 3·4층 복도 게시물 20장을 직접 보고 기록하고 만든 사람을 면담했다. 가운데 — 20장 가운데 8장에 외국어가 들어 있었고, 그 가운데 「클린 데이」와 「이벤트」 5장은 우리말로 바꿔 쓸 수 있는 말이었다. 끝 — 우리말로 바꿀 수 있는 말이 생각보다 많아 놀랐고, 앞으로 게시물을 만들 때 우리말을 먼저 떠올리겠다. 출처도 적는다.","scoring_points":["처음에 조사 대상·동기·방법을 썼는가","가운데에 조사한 사실을 수대로 썼는가","끝에 내 생각(소감)과 출처를 나누어 썼는가"]},"explanation":["처음은 과정이에요.","가운데는 사실이에요.","끝은 생각과 출처예요."],"asset":{"type":"passage","lines":["조사 대상 — 우리 학교 3·4층 복도 게시물 20장","조사 방법 — 직접 보고 기록하기, 게시물을 만든 사람 면담하기","결과 ① — 외국어가 들어간 것 8장, 우리말로만 쓴 것 12장","결과 ② — 「클린 데이」 3장 · 「이벤트」 2장 · 「버스」 2장 · 「컴퓨터」 1장","면담 — 게시물을 만든 6학년 두 명: 「눈에 잘 띄어서」, 「다들 그렇게 써서」"],"title":"하준이의 조사 자료 「우리 학교 복도 게시물에 쓰인 외국어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#1','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C2',1,'mc','auto','「한국어」와 「한글」을 바르게 나눈 것은 무엇인가요?',ARRAY['K4-2-u2-X01']::text[],false,'{"seq":1,"concept":"K4-2-u2-C2","difficulty":1,"kind":"mc","stem":"「한국어」와 「한글」을 바르게 나눈 것은 무엇인가요?","options":[{"t":"「안녕하세요」라고 소리 내어 하는 말은 한국어, 그 말을 종이에 적은 글자는 한글","correct":true},{"t":"소리 내어 하는 말은 한글, 종이에 적은 글자는 한국어","mis":"K4-2-u2-X01"},{"t":"둘 다 한글이라고 부른다","mis":"K4-2-u2-X01"},{"t":"둘 다 한국어라고 부른다","mis":"K4-2-u2-X01"}],"explanation":["소리는 말이에요.","종이에 적은 건 글자예요.","말은 한국어, 글자는 한글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#2','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C6',1,'mc','auto','문자가 꼭 필요한 경우는 언제인가요?',ARRAY['K4-2-u2-X05','K4-2-u2-X03']::text[],false,'{"seq":2,"concept":"K4-2-u2-C6","difficulty":1,"kind":"mc","stem":"문자가 꼭 필요한 경우는 언제인가요?","options":[{"t":"먼 곳에 사는 사람에게 정확하게 소식을 전해야 할 때","correct":true},{"t":"친구와 마주 보고 인사할 때","mis":"K4-2-u2-X05"},{"t":"노래를 흥얼거릴 때","mis":"K4-2-u2-X05"},{"t":"목이 아파 말을 못 할 때만","mis":"K4-2-u2-X03"}],"explanation":["말로 충분한 때는 빼요.","멀리 정확하게예요.","적어 보내요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#3','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C8',1,'mc','auto','장면 ㉰에서 문자가 한 역할은 무엇인가요?',ARRAY['K4-2-u2-X05','K4-2-u2-X03']::text[],false,'{"seq":3,"concept":"K4-2-u2-C8","difficulty":1,"kind":"mc","stem":"장면 ㉰에서 문자가 한 역할은 무엇인가요?","options":[{"t":"잊지 않고 정확하게 기억하게 돕는다","correct":true},{"t":"멀리 있는 사람에게 생각을 전한다","mis":"K4-2-u2-X05"},{"t":"지난 일을 알 수 있게 한다","mis":"K4-2-u2-X05"},{"t":"말을 못 할 때 손짓을 대신한다","mis":"K4-2-u2-X03"}],"explanation":["돌려줄 날짜예요.","잊으면 안 돼요.","기억을 도와요."],"asset":{"type":"passage","lines":["㉮ 할아버지가 젊었을 때 쓴 공책을 읽고 그때 동네 모습을 알게 되었다","㉯ 다른 도시로 이사 간 친구에게 편지를 보내 소식을 전했다","㉰ 책을 돌려줄 날짜를 달력에 적어 두었다"],"title":"문자가 쓰인 또 다른 세 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#4','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C15',1,'mc','auto','ㅡ 아래에 ㆍ를 붙이면 어떤 글자가 되나요?',ARRAY['K4-2-u2-X11']::text[],false,'{"seq":4,"concept":"K4-2-u2-C15","difficulty":1,"kind":"mc","stem":"ㅡ 아래에 ㆍ를 붙이면 어떤 글자가 되나요?","options":[{"t":"ㅜ","correct":true},{"t":"ㅏ","mis":"K4-2-u2-X11"},{"t":"ㅗ","mis":"K4-2-u2-X11"},{"t":"ㅓ","mis":"K4-2-u2-X11"}],"explanation":["ㅡ가 먼저예요.","아래에 점이 붙어요.","ㅜ예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#5','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C22',1,'mc','auto','「책으로 펴내려고 미리 쓴 글」을 뜻하는 낱말은 무엇인가요?',ARRAY['K4-2-u2-X19']::text[],false,'{"seq":5,"concept":"K4-2-u2-C22","difficulty":1,"kind":"mc","stem":"「책으로 펴내려고 미리 쓴 글」을 뜻하는 낱말은 무엇인가요?","options":[{"t":"원고","correct":true},{"t":"광복","mis":"K4-2-u2-X19"},{"t":"사전","mis":"K4-2-u2-X19"},{"t":"편지","mis":"K4-2-u2-X19"}],"explanation":["조선어학회가 쌓아 간 것이에요.","아직 책이 아니에요.","원고예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#6','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C31',1,'ox','auto','「버스」는 바꿔 쓸 알맞은 우리말이 없이 굳은 말이라 써도 돼요.',ARRAY['K4-2-u2-X25']::text[],false,'{"seq":6,"concept":"K4-2-u2-C31","difficulty":1,"kind":"ox","stem":"「버스」는 바꿔 쓸 알맞은 우리말이 없이 굳은 말이라 써도 돼요.","answer":"O","reason_options":[{"t":"우리말처럼 굳어 바꿔 쓸 알맞은 말이 없는 말은 써도 되기 때문에","correct":true},{"t":"외국어는 많이 쓸수록 좋기 때문에","mis":"K4-2-u2-X25"}],"mis":"K4-2-u2-X25","explanation":["버스를 바꿀 말이 있나요?","굳은 말이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#7','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C42',1,'ox','auto','인터넷에서 찾은 자료는 누가 만든 자료인지 확인하고 출처를 밝혀요.',ARRAY['K4-2-u2-X37']::text[],false,'{"seq":7,"concept":"K4-2-u2-C42","difficulty":1,"kind":"ox","stem":"인터넷에서 찾은 자료는 누가 만든 자료인지 확인하고 출처를 밝혀요.","answer":"O","reason_options":[{"t":"옮겨 온 자료는 어디서 왔는지 밝혀야 읽는 사람이 믿고 다시 찾아볼 수 있기 때문에","correct":true},{"t":"인터넷 자료는 누구나 쓸 수 있어 출처가 필요 없기 때문에","mis":"K4-2-u2-X37"}],"mis":"K4-2-u2-X37","explanation":["누가 만들었나요?","출처를 밝혀요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#8','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C56',1,'mc','auto','겹받침을 바르게 쓴 낱말은 무엇인가요?',ARRAY['K4-2-u2-X49']::text[],false,'{"seq":8,"concept":"K4-2-u2-C56","difficulty":1,"kind":"mc","stem":"겹받침을 바르게 쓴 낱말은 무엇인가요?","options":[{"t":"괜찮다","correct":true},{"t":"괜찬다","mis":"K4-2-u2-X49"},{"t":"괜잖다","mis":"K4-2-u2-X49"},{"t":"괜찮타","mis":"K4-2-u2-X49"}],"explanation":["ㄴ과 ㅎ이 함께예요.","괜찮아, 괜찮고를 떠올려요.","괜찮다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#9','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C4',2,'mc','auto','「문이 닫혔다」를 「문이 다쳤다」로 적으면 어떻게 될까요?',ARRAY['K4-2-u2-X02']::text[],false,'{"seq":9,"concept":"K4-2-u2-C4","difficulty":2,"kind":"mc","stem":"「문이 닫혔다」를 「문이 다쳤다」로 적으면 어떻게 될까요?","options":[{"t":"문이 아프게 되었다는 다른 뜻이 되어 버린다","correct":true},{"t":"소리가 비슷하니 뜻은 똑같다","mis":"K4-2-u2-X02"},{"t":"글씨만 예쁘면 뜻이 바르게 전해진다","mis":"K4-2-u2-X02"},{"t":"받침이 없으니 더 바른 글이 된다","mis":"K4-2-u2-X02"}],"explanation":["소리는 비슷해요.","다치다는 아프게 되는 거예요.","뜻이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#10','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C18',2,'error','auto','한글에 대해 말했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K4-2-u2-X16','K4-2-u2-X17']::text[],false,'{"seq":10,"concept":"K4-2-u2-C18","difficulty":2,"kind":"error","stem":"한글에 대해 말했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 나 — 「다른 나라 글자는 형편없으니까 한글만 최고야.」","correct":true,"mis_target":"K4-2-u2-X16"},{"t":"친구 가 — 「한글은 기본 글자를 넓혀 짜임새 있게 만들었어.」","mis":"K4-2-u2-X16"},{"t":"친구 다 — 「다른 글자도 저마다 자기 말을 적어 왔어.」","mis":"K4-2-u2-X17"}],"explanation":["한글의 짜임새는 소중해요.","다른 글자를 깎아내리진 않아요.","친구 나가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#11','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C27',2,'error','auto','한글 사랑을 실천하겠다고 말했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K4-2-u2-X22','K4-2-u2-X21']::text[],false,'{"seq":11,"concept":"K4-2-u2-C27","difficulty":2,"kind":"error","stem":"한글 사랑을 실천하겠다고 말했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 다 — 「외국 노래는 이제 절대 부르지 않을 거야.」","correct":true,"mis_target":"K4-2-u2-X22"},{"t":"친구 가 — 「가족 대화방에 줄임말 대신 풀어 쓴 말로 소식을 전할래.」","mis":"K4-2-u2-X22"},{"t":"친구 나 — 「동생에게 ㅁ → ㅂ → ㅍ 원리를 알려 줄래.」","mis":"K4-2-u2-X21"}],"explanation":["한글 사랑은 금지가 아니에요.","바르게 쓰고 알려 주는 거예요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#12','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C32',2,'mc','auto','줄임말을 풀어 써야 할 때는 언제인가요?',ARRAY['K4-2-u2-X26','K4-2-u2-X27']::text[],false,'{"seq":12,"concept":"K4-2-u2-C32","difficulty":2,"kind":"mc","stem":"줄임말을 풀어 써야 할 때는 언제인가요?","options":[{"t":"줄임말을 모르실 수 있는 할아버지께 문자를 보낼 때","correct":true},{"t":"뜻을 아는 친구와 쪽지를 주고받을 때만","mis":"K4-2-u2-X26"},{"t":"풀어 쓸 때는 따로 없다","mis":"K4-2-u2-X26"},{"t":"줄임말은 누구와도 쓰지 않으니 따로 풀 일이 없다","mis":"K4-2-u2-X27"}],"explanation":["누가 읽나요?","모를 수 있나요?","그때 풀어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#13','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C41',2,'mc','auto','하준이의 메모 ②의 문제점은 무엇인가요?',ARRAY['K4-2-u2-X30','K4-2-u2-X34','K4-2-u2-X36']::text[],false,'{"seq":13,"concept":"K4-2-u2-C41","difficulty":2,"kind":"mc","stem":"하준이의 메모 ②의 문제점은 무엇인가요?","options":[{"t":"한 명의 말을 모두의 까닭으로 넓혔다","correct":true},{"t":"수를 틀리게 적었다","mis":"K4-2-u2-X30"},{"t":"면담한 말을 그대로 적은 것이 잘못이다","mis":"K4-2-u2-X34"},{"t":"아무 문제가 없다","mis":"K4-2-u2-X36"}],"explanation":["면담한 사람은 두 명이에요.","한 명만 그렇게 말했어요.","모두로 넓히면 안 돼요."],"asset":{"type":"passage","lines":["① 「8장은 많아 보이니까 ‘거의 모든 게시물’에 외국어가 있다고 쓰자.」","② 「6학년 한 명이 ‘눈에 잘 띄어서’라고 했으니 모두 그렇다고 쓰자.」","③ 「‘클린 데이’를 바꿀 우리말은 찾은 곳을 적지 않고 옮기자.」","④ 「외국어가 들어간 게시물 수는 표로 나타내자.」"],"title":"하준이가 쓰기 전에 적은 메모 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#14','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C38',2,'ox','auto','보고하는 글에는 조사 방법을 반드시 한 가지만 써야 해요.',ARRAY['K4-2-u2-X32']::text[],false,'{"seq":14,"concept":"K4-2-u2-C38","difficulty":2,"kind":"ox","stem":"보고하는 글에는 조사 방법을 반드시 한 가지만 써야 해요.","answer":"X","reason_options":[{"t":"알아내려는 내용에 맞는 방법이면 한 가지여도 여러 가지여도 되기 때문에","correct":true},{"t":"방법이 둘 이상이면 보고서가 헷갈리기 때문에","mis":"K4-2-u2-X32"}],"mis":"K4-2-u2-X32","explanation":["보민이는 세 가지를 썼어요.","내용마다 맞는 방법이 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#15','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C43',2,'ox','auto','「외국어를 쓴 6학년은 우리말을 싫어할 것이다」는 조사한 내용 칸에 쓸 수 있어요.',ARRAY['K4-2-u2-X39']::text[],false,'{"seq":15,"concept":"K4-2-u2-C43","difficulty":2,"kind":"ox","stem":"「외국어를 쓴 6학년은 우리말을 싫어할 것이다」는 조사한 내용 칸에 쓸 수 있어요.","answer":"X","reason_options":[{"t":"조사로 확인한 사실이 아니라 근거 없는 짐작이기 때문에","correct":true},{"t":"내 생각도 사실과 같은 칸에 섞어 쓰기 때문에","mis":"K4-2-u2-X39"}],"mis":"K4-2-u2-X39","explanation":["그렇게 말한 사람이 있었나요?","확인하지 않은 짐작이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#16','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C53',2,'mc','auto','「밟지」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-2-u2-X47','K4-2-u2-X48']::text[],false,'{"seq":16,"concept":"K4-2-u2-C53","difficulty":2,"kind":"mc","stem":"「밟지」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[밥찌]","correct":true},{"t":"[발찌]","mis":"K4-2-u2-X47"},{"t":"[밥지]","mis":"K4-2-u2-X48"},{"t":"[발지]","mis":"K4-2-u2-X47"}],"explanation":["밟-은 [밥]이에요.","뒤는 된소리예요.","[밥찌]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#17','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C13',3,'ox','auto','ㄴ → ㄷ → ㅌ 처럼 획이 하나씩 늘면 소리가 더 세져요.',ARRAY['K4-2-u2-X10']::text[],false,'{"seq":17,"concept":"K4-2-u2-C13","difficulty":3,"kind":"ox","stem":"ㄴ → ㄷ → ㅌ 처럼 획이 하나씩 늘면 소리가 더 세져요.","answer":"O","reason_options":[{"t":"기본 글자에 획을 더해 소리가 더 센 글자를 만들었기 때문에","correct":true},{"t":"획이 늘면 소리가 약해지기 때문에","mis":"K4-2-u2-X10"}],"mis":"K4-2-u2-X10","explanation":["ㅁ → ㅂ → ㅍ 와 같아요.","획을 더하면 세져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#18','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C24',3,'error','auto','「원고 상자를 지킨 사람들」의 마음을 짐작했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K4-2-u2-X20']::text[],false,'{"seq":18,"concept":"K4-2-u2-C24","difficulty":3,"kind":"error","stem":"「원고 상자를 지킨 사람들」의 마음을 짐작했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 나 — 「유명해지고 싶어서 끝까지 사전을 만들었을 거야.」","correct":true,"mis_target":"K4-2-u2-X20"},{"t":"친구 가 — 「다음 사람들에게 우리말을 물려주고 싶었을 거야.」","mis":"K4-2-u2-X20"},{"t":"친구 다 — 「우리말이 사라질까 봐 걱정했을 거야.」","mis":"K4-2-u2-X20"}],"explanation":["행동을 근거로 짐작해요.","이름을 알리려던 게 아니에요.","친구 나가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#19','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C31',3,'mc','auto','하준이 자료의 「컴퓨터」를 두고 한 말로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X24','K4-2-u2-X25']::text[],false,'{"seq":19,"concept":"K4-2-u2-C31","difficulty":3,"kind":"mc","stem":"하준이 자료의 「컴퓨터」를 두고 한 말로 알맞은 것은 무엇인가요?","options":[{"t":"바꿔 쓸 알맞은 우리말이 없이 굳은 말이라 써도 된다","correct":true},{"t":"외국에서 온 말이니 새 우리말을 지어 바꿔야 한다","mis":"K4-2-u2-X24"},{"t":"외국어이니 게시물에서 모두 지워야 한다","mis":"K4-2-u2-X24"},{"t":"외국어라 멋지니 다른 말도 외국어로 바꾸자","mis":"K4-2-u2-X25"}],"explanation":["버스와 같아요.","바꿔 쓸 말이 마땅치 않아요.","그대로 써도 돼요."],"asset":{"type":"passage","lines":["조사 대상 — 우리 학교 3·4층 복도 게시물 20장","조사 방법 — 직접 보고 기록하기, 게시물을 만든 사람 면담하기","결과 ① — 외국어가 들어간 것 8장, 우리말로만 쓴 것 12장","결과 ② — 「클린 데이」 3장 · 「이벤트」 2장 · 「버스」 2장 · 「컴퓨터」 1장","면담 — 게시물을 만든 6학년 두 명: 「눈에 잘 띄어서」, 「다들 그렇게 써서」"],"title":"하준이의 조사 자료 「우리 학교 복도 게시물에 쓰인 외국어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#20','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C48',3,'error','auto','하준이의 글을 돌려 읽고 조언했어요. 알맞지 않은 조언을 한 친구는 누구인가요?',ARRAY['K4-2-u2-X41']::text[],false,'{"seq":20,"concept":"K4-2-u2-C48","difficulty":3,"kind":"error","stem":"하준이의 글을 돌려 읽고 조언했어요. 알맞지 않은 조언을 한 친구는 누구인가요?","options":[{"t":"친구 다 — 「면담을 두 명만 했으니 열 명에게 들은 것처럼 쓰자.」","correct":true,"mis_target":"K4-2-u2-X41"},{"t":"친구 가 — 「출처에 찾아본 누리집 이름을 적자.」","mis":"K4-2-u2-X41"},{"t":"친구 나 — 「굳은 말과 바꿀 수 있는 말을 나누어 쓰자.」","mis":"K4-2-u2-X41"}],"explanation":["지어내면 안 돼요.","믿을 수 있게 고쳐요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#21','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C10',3,'mc','auto','우리말 조사 주제를 떠올리는 방법으로 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X07','K4-2-u2-X50']::text[],false,'{"seq":21,"concept":"K4-2-u2-C10","difficulty":3,"kind":"mc","stem":"우리말 조사 주제를 떠올리는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"「생선」처럼 말 때문에 오해가 생겼던 때를 떠올려 조사할 거리를 찾는다","correct":true},{"t":"사전을 펼쳐 아무 낱말이나 고른다","mis":"K4-2-u2-X07"},{"t":"가장 크고 어려운 주제를 고른다","mis":"K4-2-u2-X07"},{"t":"우리말과 상관없는 놀이를 조사한다","mis":"K4-2-u2-X50"}],"explanation":["내 생활에서 찾아요.","불편했던 때예요.","오해가 생긴 때를 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#22','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C8',3,'mc','auto','할아버지 공책 덕분에 그때 동네 모습을 알게 된 일과 문자의 역할이 같은 것은 무엇인가요?',ARRAY['K4-2-u2-X05']::text[],false,'{"seq":22,"concept":"K4-2-u2-C8","difficulty":3,"kind":"mc","stem":"할아버지 공책 덕분에 그때 동네 모습을 알게 된 일과 문자의 역할이 같은 것은 무엇인가요?","options":[{"t":"몇백 년 전 사람이 쓴 일기를 읽고 그때 일을 알게 되었다","correct":true},{"t":"이모에게 전자 우편으로 소식을 보냈다","mis":"K4-2-u2-X05"},{"t":"달걀말이 만드는 순서를 공책에 적어 두었다","mis":"K4-2-u2-X05"},{"t":"친구와 마주 보고 이야기했다","mis":"K4-2-u2-X05"}],"explanation":["할아버지 공책은 지난 일이에요.","같은 역할을 찾아요.","옛 일기예요."],"asset":{"type":"passage","lines":["㉮ 할아버지가 젊었을 때 쓴 공책을 읽고 그때 동네 모습을 알게 되었다","㉯ 다른 도시로 이사 간 친구에게 편지를 보내 소식을 전했다","㉰ 책을 돌려줄 날짜를 달력에 적어 두었다"],"title":"문자가 쓰인 또 다른 세 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#23','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C27',4,'mc','auto','이 단원을 배운 뒤 우리말과 우리글을 대하는 생각으로 가장 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X16','K4-2-u2-X21','K4-2-u2-X17']::text[],false,'{"seq":23,"concept":"K4-2-u2-C27","difficulty":4,"kind":"mc","stem":"이 단원을 배운 뒤 우리말과 우리글을 대하는 생각으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「한글은 짜임새 있게 만든 소중한 글자야. 대단한 일이 아니어도 바르게 쓰고, 우리말로 쓸 수 있는 말은 우리말로 쓸래.」","correct":true},{"t":"「한글이 최고니 외국어와 다른 나라 글자는 모두 필요 없어.」","mis":"K4-2-u2-X16"},{"t":"「한글을 지키는 일은 옛날 사람들이 다 했으니 나는 할 일이 없어.」","mis":"K4-2-u2-X21"},{"t":"「글자는 다 비슷해서 한글도 특별할 게 없어.」","mis":"K4-2-u2-X17"}],"explanation":["한글의 짜임새를 떠올려요.","내 생활에서 해요.","두 끝을 조심해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#24','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C27',4,'essay','teacher','오늘의 내가 할 수 있는 한글 사랑 두 가지를 쓰고, 「한글 사랑은 대단한 사람만 하는 일」과 「외국어는 한마디도 쓰면 안 된다」가 왜 알맞지 않은지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u2-C27","difficulty":4,"kind":"essay","stem":"오늘의 내가 할 수 있는 한글 사랑 두 가지를 쓰고, 「한글 사랑은 대단한 사람만 하는 일」과 「외국어는 한마디도 쓰면 안 된다」가 왜 알맞지 않은지 쓰세요.","answer_guide":{"answer":"예: 모르는 낱말은 국어사전에서 찾아보고, 가족 대화방에 줄임말 대신 풀어 쓴 말로 소식을 전하겠다. 받침까지 바르게 쓰는 것처럼 내 생활에서 하는 작은 일도 한글을 아끼는 일이므로 대단한 사람만 하는 일이 아니다. 또 버스처럼 굳은 말도 있고, 한글 사랑은 무엇을 금지하는 것이 아니라 우리말을 아끼고 바르게 쓰는 것이므로 외국어를 한마디도 쓰면 안 된다는 것도 알맞지 않다.","scoring_points":["내가 할 수 있는 한글 사랑 두 가지를 썼는가","「대단한 사람만」이 알맞지 않은 까닭을 썼는가","「외국어는 한마디도 안 된다」가 알맞지 않은 까닭을 썼는가"]},"explanation":["내 생활에서 찾아요.","작은 일도 한글 사랑이에요.","금지하는 일이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_c#25','kor',4,2,'u2','','g4_2_kor_u2_review_c','unit_review','K4-2-u2-C38',4,'essay','teacher','「우리 반 친구들이 선생님께 쓰는 인사말」을 조사하려고 해요. 알아내려는 내용 두 가지와 각각에 알맞은 조사 방법을 쓰고, 그렇게 고른 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u2-C38","difficulty":4,"kind":"essay","stem":"「우리 반 친구들이 선생님께 쓰는 인사말」을 조사하려고 해요. 알아내려는 내용 두 가지와 각각에 알맞은 조사 방법을 쓰고, 그렇게 고른 까닭을 쓰세요.","answer_guide":{"answer":"예: 친구들이 선생님께 주로 어떤 인사말을 쓰는지는 여러 친구에게 같은 질문지로 묻는 설문 조사로 알아본다. 몇 명이 어떤 말을 쓰는지 세기 좋기 때문이다. 그 인사말을 쓰는 까닭은 친구 몇 명을 직접 만나 묻는 면담 조사로 알아본다. 까닭은 직접 이야기를 들어야 알 수 있기 때문이다.","scoring_points":["알아내려는 내용 두 가지를 썼는가","각각에 알맞은 조사 방법을 썼는가","그 방법을 고른 까닭을 썼는가"]},"explanation":["몇 명은 설문이에요.","까닭은 면담이에요.","내용에 맞게 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#1','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C3',1,'mc','auto','우리가 10월 9일을 한글날로 기념하는 것과 관계있는 일은 무엇인가요?',ARRAY['K4-2-u2-X18','K4-2-u2-X06']::text[],false,'{"seq":1,"concept":"K4-2-u2-C3","difficulty":1,"kind":"mc","stem":"우리가 10월 9일을 한글날로 기념하는 것과 관계있는 일은 무엇인가요?","options":[{"t":"세종 대왕이 만든 우리 글자를 널리 알린 일","correct":true},{"t":"조선어학회가 사전 원고를 빼앗긴 일","mis":"K4-2-u2-X18"},{"t":"우리나라가 광복을 맞은 일","mis":"K4-2-u2-X18"},{"t":"세종 대왕이 태어난 일","mis":"K4-2-u2-X06"}],"explanation":["한글날의 뜻을 떠올려요.","글자를 널리 알렸어요.","그 일을 기념해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#2','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C7',1,'mc','auto','나무 막대에 금을 그어 날짜를 센 기록의 불편한 점은 무엇인가요?',ARRAY['K4-2-u2-X04']::text[],false,'{"seq":2,"concept":"K4-2-u2-C7","difficulty":1,"kind":"mc","stem":"나무 막대에 금을 그어 날짜를 센 기록의 불편한 점은 무엇인가요?","options":[{"t":"무엇을 센 것인지 다른 사람이 알기 어렵다","correct":true},{"t":"누구나 똑같은 뜻으로 알아본다","mis":"K4-2-u2-X04"},{"t":"까닭과 마음까지 또렷하게 담긴다","mis":"K4-2-u2-X04"},{"t":"길고 복잡한 이야기도 쉽게 남긴다","mis":"K4-2-u2-X04"}],"explanation":["금은 수만 보여 줘요.","무엇을 셌을까요?","다른 사람은 알기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#3','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C9',1,'mc','auto','문자가 사람들의 지식을 쌓아 가게 해 준 까닭은 무엇인가요?',ARRAY['K4-2-u2-X03','K4-2-u2-X04','K4-2-u2-X05']::text[],false,'{"seq":3,"concept":"K4-2-u2-C9","difficulty":1,"kind":"mc","stem":"문자가 사람들의 지식을 쌓아 가게 해 준 까닭은 무엇인가요?","options":[{"t":"한 사람이 알아낸 것을 적어 두면 다음 사람이 이어받을 수 있기 때문에","correct":true},{"t":"문자를 쓰면 말을 할 필요가 없기 때문에","mis":"K4-2-u2-X03"},{"t":"문자는 그림이라 누구나 다르게 읽기 때문에","mis":"K4-2-u2-X04"},{"t":"문자는 옆 사람과 이야기할 때만 쓰기 때문에","mis":"K4-2-u2-X05"}],"explanation":["적어 두어요.","다음 사람이 읽어요.","이어받아 쌓여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#4','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C12',1,'mc','auto','모음자 ㅣ가 본뜬 것은 무엇인가요?',ARRAY['K4-2-u2-X09']::text[],false,'{"seq":4,"concept":"K4-2-u2-C12","difficulty":1,"kind":"mc","stem":"모음자 ㅣ가 본뜬 것은 무엇인가요?","options":[{"t":"곧게 선 사람","correct":true},{"t":"둥근 하늘","mis":"K4-2-u2-X09"},{"t":"평평한 땅","mis":"K4-2-u2-X09"},{"t":"입의 모양","mis":"K4-2-u2-X09"}],"explanation":["ㆍ는 하늘이에요.","ㅡ는 땅이에요.","ㅣ는 사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#5','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C21',1,'mc','auto','빼앗겼던 원고가 다시 발견된 곳은 어디인가요?',ARRAY['K4-2-u2-X18']::text[],false,'{"seq":5,"concept":"K4-2-u2-C21","difficulty":1,"kind":"mc","stem":"빼앗겼던 원고가 다시 발견된 곳은 어디인가요?","options":[{"t":"서울역의 한 창고","correct":true},{"t":"학회 사람들의 집","mis":"K4-2-u2-X18"},{"t":"다른 나라의 책방","mis":"K4-2-u2-X18"},{"t":"끝내 찾지 못했다","mis":"K4-2-u2-X18"}],"explanation":["6번 줄을 봐요.","광복을 맞은 가을이에요.","서울역 창고예요."],"asset":{"type":"passage","lines":["1 일제 강점기에는 우리말을 마음껏 쓰기 어려운 때가 있었어요.","2 조선어학회 사람들은 우리말 낱말과 뜻을 모아 사전을 만들기로 했어요.","3 여러 해 동안 낱말을 모으고 뜻을 적어 사전 원고를 쌓아 갔어요.","4 1942년, 일본 경찰이 학회 사람들을 잡아가고 원고도 빼앗아 갔어요.","5 학회 사람들은 감옥에 갇혀 큰 고생을 했어요.","6 광복을 맞은 1945년 가을, 서울역의 한 창고에서 원고 뭉치가 다시 발견되었어요.","7 학회 사람들은 원고를 다시 다듬어 마침내 우리말 사전을 펴내기 시작했어요."],"title":"「원고 상자를 지킨 사람들」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#6','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C30',1,'mc','auto','「오픈 타임: 오전 10시」를 우리말로 바르게 고친 것은 무엇인가요?',ARRAY['K4-2-u2-X25']::text[],false,'{"seq":6,"concept":"K4-2-u2-C30","difficulty":1,"kind":"mc","stem":"「오픈 타임: 오전 10시」를 우리말로 바르게 고친 것은 무엇인가요?","options":[{"t":"「여는 시간: 오전 10시」","correct":true},{"t":"「오픈 시간: 오전 10시」","mis":"K4-2-u2-X25"},{"t":"「여는 타임: 오전 10시」","mis":"K4-2-u2-X25"},{"t":"「OPEN TIME: 오전 10시」","mis":"K4-2-u2-X25"}],"explanation":["오픈은 여는이에요.","타임은 시간이에요.","둘 다 바꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#7','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C35',1,'mc','auto','청소를 마친 당번이 선생님께 어디까지 했는지 알리는 일은 무엇인가요?',ARRAY['K4-2-u2-X30']::text[],false,'{"seq":7,"concept":"K4-2-u2-C35","difficulty":1,"kind":"mc","stem":"청소를 마친 당번이 선생님께 어디까지 했는지 알리는 일은 무엇인가요?","options":[{"t":"보고","correct":true},{"t":"광고","mis":"K4-2-u2-X30"},{"t":"시 쓰기","mis":"K4-2-u2-X30"},{"t":"편지 쓰기","mis":"K4-2-u2-X30"}],"explanation":["한 일을 알려요.","있는 그대로예요.","보고예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#8','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C53',1,'mc','auto','「밟다」를 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-2-u2-X47','K4-2-u2-X48']::text[],false,'{"seq":8,"concept":"K4-2-u2-C53","difficulty":1,"kind":"mc","stem":"「밟다」를 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"[밥따]","correct":true},{"t":"[발따]","mis":"K4-2-u2-X47"},{"t":"[밥다]","mis":"K4-2-u2-X48"},{"t":"[발다]","mis":"K4-2-u2-X47"}],"explanation":["밟-은 따로 정했어요.","[ㅂ]으로 나요.","[밥따]예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#9','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C17',2,'mc','auto','「국물」을 바르게 적고 바르게 소리 낸 것은 무엇인가요?',ARRAY['K4-2-u2-X15','K4-2-u2-X13']::text[],false,'{"seq":9,"concept":"K4-2-u2-C17","difficulty":2,"kind":"mc","stem":"「국물」을 바르게 적고 바르게 소리 낸 것은 무엇인가요?","options":[{"t":"적을 때는 「국물」, 소리는 [궁물]","correct":true},{"t":"적을 때도 「궁물」, 소리도 [궁물]","mis":"K4-2-u2-X15"},{"t":"적을 때는 「국물」, 소리도 [국물]","mis":"K4-2-u2-X13"},{"t":"적을 때는 「궁물」, 소리는 [국물]","mis":"K4-2-u2-X15"}],"explanation":["글자는 원래대로예요.","소리는 바뀌어요.","「국물」 · [궁물]이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#10','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C16',2,'ox','auto','한글은 적은 수의 글자를 익히면 우리말을 두루 읽고 쓸 수 있어요.',ARRAY['K4-2-u2-X12']::text[],false,'{"seq":10,"concept":"K4-2-u2-C16","difficulty":2,"kind":"ox","stem":"한글은 적은 수의 글자를 익히면 우리말을 두루 읽고 쓸 수 있어요.","answer":"O","reason_options":[{"t":"소리와 모양이 짜임새 있게 이어지도록 만들었기 때문에","correct":true},{"t":"익혀야 할 글자가 수만 개로 아주 많기 때문에","mis":"K4-2-u2-X12"}],"mis":"K4-2-u2-X12","explanation":["기본 글자를 넓혀 만들었어요.","소리와 모양이 이어져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#11','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C26',2,'mc','auto','조선어학회 사람들과 가갸날을 정한 사람들에게서 배울 점은 무엇인가요?',ARRAY['K4-2-u2-X21','K4-2-u2-X22','K4-2-u2-X52']::text[],false,'{"seq":11,"concept":"K4-2-u2-C26","difficulty":2,"kind":"mc","stem":"조선어학회 사람들과 가갸날을 정한 사람들에게서 배울 점은 무엇인가요?","options":[{"t":"자기가 할 수 있는 일로 우리말과 한글을 아꼈다","correct":true},{"t":"한글 사랑은 옛날 사람들만의 일이다","mis":"K4-2-u2-X21"},{"t":"외국어를 쓰는 사람을 막아야 한글을 지킨다","mis":"K4-2-u2-X22"},{"t":"사전을 만든 사람만 한글을 사랑한 것이다","mis":"K4-2-u2-X52"}],"explanation":["방법은 달랐어요.","할 수 있는 일을 했어요.","나도 할 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#12','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C33',2,'error','auto','공놀이를 하다 친구가 공을 놓쳤을 때 한 말이에요. 알맞지 않은 친구는 누구인가요?',ARRAY['K4-2-u2-X28']::text[],false,'{"seq":12,"concept":"K4-2-u2-C33","difficulty":2,"kind":"error","stem":"공놀이를 하다 친구가 공을 놓쳤을 때 한 말이에요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 다 — 「장난인데 뭐 어때.」 하며 거친 말을 했다","correct":true,"mis_target":"K4-2-u2-X28"},{"t":"친구 가 — 「괜찮아, 다음에 잡으면 돼!」","mis":"K4-2-u2-X28"},{"t":"친구 나 — 「내가 더 천천히 던질게.」","mis":"K4-2-u2-X28"}],"explanation":["장난이어도 마음이 다쳐요.","고운 말을 골라요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#13','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C41',2,'ox','auto','메모 ①처럼 8장을 「거의 모든 게시물」이라고 써도 수를 틀리게 적은 것은 아니니 괜찮아요.',ARRAY['K4-2-u2-X35']::text[],false,'{"seq":13,"concept":"K4-2-u2-C41","difficulty":2,"kind":"ox","stem":"메모 ①처럼 8장을 「거의 모든 게시물」이라고 써도 수를 틀리게 적은 것은 아니니 괜찮아요.","answer":"X","reason_options":[{"t":"20장 가운데 8장인데 「거의 모든」이라는 낱말로 결과를 부풀렸기 때문에","correct":true},{"t":"수만 틀리지 않으면 정확한 보고이기 때문에","mis":"K4-2-u2-X35"}],"mis":"K4-2-u2-X35","explanation":["수가 없어도 낱말을 봐요.","8장은 절반도 안 돼요.","그래서 X예요."],"asset":{"type":"passage","lines":["① 「8장은 많아 보이니까 ‘거의 모든 게시물’에 외국어가 있다고 쓰자.」","② 「6학년 한 명이 ‘눈에 잘 띄어서’라고 했으니 모두 그렇다고 쓰자.」","③ 「‘클린 데이’를 바꿀 우리말은 찾은 곳을 적지 않고 옮기자.」","④ 「외국어가 들어간 게시물 수는 표로 나타내자.」"],"title":"하준이가 쓰기 전에 적은 메모 넷"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#14','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C37',2,'mc','auto','책이나 사전에서 찾는 방법과 관련 있는 곳에 가서 보고 듣는 방법을 차례대로 짝지은 것은 무엇인가요?',ARRAY['K4-2-u2-X33']::text[],false,'{"seq":14,"concept":"K4-2-u2-C37","difficulty":2,"kind":"mc","stem":"책이나 사전에서 찾는 방법과 관련 있는 곳에 가서 보고 듣는 방법을 차례대로 짝지은 것은 무엇인가요?","options":[{"t":"책 조사 · 방문 조사","correct":true},{"t":"설문 조사 · 면담 조사","mis":"K4-2-u2-X33"},{"t":"면담 조사 · 책 조사","mis":"K4-2-u2-X33"},{"t":"설문 조사 · 방문 조사","mis":"K4-2-u2-X33"}],"explanation":["책에서 찾아요.","가서 보고 들어요.","책 조사 · 방문 조사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#15','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C47',2,'mc','auto','보고하는 글의 「가운데」에 들어갈 것은 무엇인가요?',ARRAY['K4-2-u2-X44']::text[],false,'{"seq":15,"concept":"K4-2-u2-C47","difficulty":2,"kind":"mc","stem":"보고하는 글의 「가운데」에 들어갈 것은 무엇인가요?","options":[{"t":"조사한 내용(사실)과 매체 자료","correct":true},{"t":"조사 동기와 조사 방법","mis":"K4-2-u2-X44"},{"t":"조사 소감과 출처","mis":"K4-2-u2-X44"},{"t":"제목만","mis":"K4-2-u2-X44"}],"explanation":["처음은 과정이에요.","끝은 생각과 출처예요.","가운데는 사실이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#16','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C51',2,'error','auto','포장지 조사 결과를 보고 말했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K4-2-u2-X46']::text[],false,'{"seq":16,"concept":"K4-2-u2-C51","difficulty":2,"kind":"error","stem":"포장지 조사 결과를 보고 말했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 나 — 「외국어 이름 과자는 나쁜 과자니까 버리자.」","correct":true,"mis_target":"K4-2-u2-X46"},{"t":"친구 가 — 「‘햇살 보리차’는 우리말을 살린 이름이야.」","mis":"K4-2-u2-X46"},{"t":"친구 다 — 「‘허니 크런치 스낵’은 우리말로 지을 수도 있었겠다.」","mis":"K4-2-u2-X46"}],"explanation":["살펴본 것은 이름이에요.","과자를 평가하지 않아요.","친구 나가 알맞지 않아요."],"asset":{"type":"passage","lines":["달콤 누룽지 · 허니 크런치 스낵 · 햇살 보리차","프레시 스위트 드링크 · 바삭 김부각 · 해피 초코 볼"],"title":"포장지에서 찾은 이름 여섯 개 (지어낸 이름)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#17','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C17',3,'error','auto','「국물」을 두고 말했어요. 알맞지 않은 친구는 누구인가요?',ARRAY['K4-2-u2-X15','K4-2-u2-X14']::text[],false,'{"seq":17,"concept":"K4-2-u2-C17","difficulty":3,"kind":"error","stem":"「국물」을 두고 말했어요. 알맞지 않은 친구는 누구인가요?","options":[{"t":"친구 다 — 「[궁물]로 소리 나니까 공책에도 ‘궁물’이라고 써야 해.」","correct":true,"mis_target":"K4-2-u2-X15"},{"t":"친구 가 — 「글자는 ‘국물’로 적고 소리는 [궁물]로 내.」","mis":"K4-2-u2-X15"},{"t":"친구 나 — 「소리가 바뀌어도 글자의 짜임은 그대로야.」","mis":"K4-2-u2-X14"}],"explanation":["글자는 원래대로 적어요.","소리만 바뀌어요.","친구 다가 알맞지 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#18','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C26',3,'mc','auto','두 글의 사람들이 한 일과 오늘의 나를 이어 말한 것 가운데 알맞은 것은 무엇인가요?',ARRAY['K4-2-u2-X21','K4-2-u2-X22']::text[],false,'{"seq":18,"concept":"K4-2-u2-C26","difficulty":3,"kind":"mc","stem":"두 글의 사람들이 한 일과 오늘의 나를 이어 말한 것 가운데 알맞은 것은 무엇인가요?","options":[{"t":"그분들이 지켜 온 우리말을 내가 바르게 쓰고 가꾸면 그 일을 이어 가는 것이다","correct":true},{"t":"그분들의 일은 끝났으니 나는 할 일이 없다","mis":"K4-2-u2-X21"},{"t":"그분들처럼 감옥에 갈 만큼 큰일을 해야 한다","mis":"K4-2-u2-X21"},{"t":"그분들처럼 외국어를 쓰는 사람을 모두 꾸짖어야 한다","mis":"K4-2-u2-X22"}],"explanation":["지켜 온 것을 이어받아요.","큰일만이 아니에요.","바르게 쓰고 가꿔요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#19','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C30',3,'ox','auto','하준이 자료의 「클린 데이」는 우리말로 바꿔 쓸 수 있는 말이에요.',ARRAY['K4-2-u2-X25']::text[],false,'{"seq":19,"concept":"K4-2-u2-C30","difficulty":3,"kind":"ox","stem":"하준이 자료의 「클린 데이」는 우리말로 바꿔 쓸 수 있는 말이에요.","answer":"O","reason_options":[{"t":"「깨끗한 날」처럼 뜻이 통하는 우리말로 바꿔 쓸 수 있기 때문에","correct":true},{"t":"외국어는 무엇이든 바꿔 쓸 우리말이 없기 때문에","mis":"K4-2-u2-X25"}],"mis":"K4-2-u2-X25","explanation":["클린은 깨끗한이에요.","데이는 날이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["조사 대상 — 우리 학교 3·4층 복도 게시물 20장","조사 방법 — 직접 보고 기록하기, 게시물을 만든 사람 면담하기","결과 ① — 외국어가 들어간 것 8장, 우리말로만 쓴 것 12장","결과 ② — 「클린 데이」 3장 · 「이벤트」 2장 · 「버스」 2장 · 「컴퓨터」 1장","면담 — 게시물을 만든 6학년 두 명: 「눈에 잘 띄어서」, 「다들 그렇게 써서」"],"title":"하준이의 조사 자료 「우리 학교 복도 게시물에 쓰인 외국어」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#20','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C48',3,'ox','auto','보고하는 글이 짧으면 하지 않은 조사도 한 것처럼 적어 길게 만드는 것이 좋아요.',ARRAY['K4-2-u2-X41']::text[],false,'{"seq":20,"concept":"K4-2-u2-C48","difficulty":3,"kind":"ox","stem":"보고하는 글이 짧으면 하지 않은 조사도 한 것처럼 적어 길게 만드는 것이 좋아요.","answer":"X","reason_options":[{"t":"좋은 보고하는 글은 긴 글이 아니라 조사한 대로 써서 믿을 수 있는 글이기 때문에","correct":true},{"t":"길게 쓴 보고서가 더 믿음이 가기 때문에","mis":"K4-2-u2-X41"}],"mis":"K4-2-u2-X41","explanation":["길이가 기준이 아니에요.","지어내면 믿을 수 없어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#21','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C44',3,'error','auto','보고하는 글의 주제를 정했어요. 직접 조사하기 어려운 주제를 정한 친구는 누구인가요?',ARRAY['K4-2-u2-X07']::text[],false,'{"seq":21,"concept":"K4-2-u2-C44","difficulty":3,"kind":"error","stem":"보고하는 글의 주제를 정했어요. 직접 조사하기 어려운 주제를 정한 친구는 누구인가요?","options":[{"t":"친구 나 — 「세계 모든 나라 어린이의 별명」","correct":true,"mis_target":"K4-2-u2-X07"},{"t":"친구 가 — 「우리 반 친구들이 선생님께 쓰는 인사말」","mis":"K4-2-u2-X07"},{"t":"친구 다 — 「우리 집 과자 포장지에 쓰인 이름」","mis":"K4-2-u2-X07"}],"explanation":["직접 물을 수 있나요?","세계 모든 나라는 너무 넓어요.","친구 나예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#22','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C51',3,'ox','auto','외국어 이름을 조사한 까닭은 그 물건이 좋은지 나쁜지 가리기 위해서예요.',ARRAY['K4-2-u2-X46']::text[],false,'{"seq":22,"concept":"K4-2-u2-C51","difficulty":3,"kind":"ox","stem":"외국어 이름을 조사한 까닭은 그 물건이 좋은지 나쁜지 가리기 위해서예요.","answer":"X","reason_options":[{"t":"우리가 살펴보는 것은 물건이 아니라 이름에 쓰인 말이기 때문에","correct":true},{"t":"외국어 이름 물건은 품질이 나쁘기 때문에","mis":"K4-2-u2-X46"}],"mis":"K4-2-u2-X46","explanation":["조사 주제를 떠올려요.","이름에 쓰인 말이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#23','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C43',4,'mc','auto','보고하는 글을 쓰는 방법을 가장 바르게 말한 것은 무엇인가요?',ARRAY['K4-2-u2-X31','K4-2-u2-X38','K4-2-u2-X35']::text[],false,'{"seq":23,"concept":"K4-2-u2-C43","difficulty":4,"kind":"mc","stem":"보고하는 글을 쓰는 방법을 가장 바르게 말한 것은 무엇인가요?","options":[{"t":"「알아내려는 내용에 맞게 조사하고, 결과는 부풀리지 않고, 사실과 내 생각은 칸을 나누고, 출처를 밝혀.」","correct":true},{"t":"「방법을 많이 쓰고 길게 쓸수록 좋은 보고서야.」","mis":"K4-2-u2-X31"},{"t":"「보고하는 글에는 내 생각을 한 줄도 쓰면 안 돼.」","mis":"K4-2-u2-X38"},{"t":"「결과가 놀라워 보이게 낱말을 조금 부풀려도 돼.」","mis":"K4-2-u2-X35"}],"explanation":["알맞은 방법이에요.","있는 그대로예요.","칸을 나누고 출처를 밝혀요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#24','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C32',4,'essay','teacher','지아와 할머니의 문자를 보고, 줄임말을 쓸 때 살펴야 할 것을 쓰세요. 「줄임말은 친구끼리도 절대 쓰면 안 된다」가 왜 알맞지 않은지도 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K4-2-u2-C32","difficulty":4,"kind":"essay","stem":"지아와 할머니의 문자를 보고, 줄임말을 쓸 때 살펴야 할 것을 쓰세요. 「줄임말은 친구끼리도 절대 쓰면 안 된다」가 왜 알맞지 않은지도 쓰세요.","answer_guide":{"answer":"예: 줄임말을 쓸 때는 듣는 사람이 그 뜻을 아는지와 어떤 상황인지 살펴야 한다. 할머니는 「수익」을 모르셨으니 「수학 익힘책」이라고 풀어 써야 했다. 하지만 뜻을 아는 짝과 이야기할 때는 줄임말을 써도 뜻이 통하므로, 친구끼리도 절대 쓰면 안 된다는 것은 알맞지 않다.","scoring_points":["듣는 사람과 상황을 살펴야 한다고 썼는가","할머니께는 풀어 써야 했던 까닭을 썼는가","「절대 안 된다」가 알맞지 않은 까닭을 썼는가"]},"explanation":["누가 듣나요?","할머니는 모르셨어요.","친구는 알 수도 있어요."],"asset":{"type":"speech","turns":[{"who":"지아","text":"할머니, 오늘 수익 다 했어요!"},{"who":"할머니","text":"수익? 우리 지아가 장사라도 했니?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_kor_u2_review_d#25','kor',4,2,'u2','','g4_2_kor_u2_review_d','unit_review','K4-2-u2-C19',4,'essay','teacher','한글의 특성 세 가지를 예를 들어 설명하고, 다른 나라 글자를 대하는 알맞은 태도도 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"K4-2-u2-C19","difficulty":4,"kind":"essay","stem":"한글의 특성 세 가지를 예를 들어 설명하고, 다른 나라 글자를 대하는 알맞은 태도도 쓰세요.","answer_guide":{"answer":"예: 첫째, 기본 글자가 무엇을 본떴는지 알려져 있다. ㅁ은 입, ㅣ는 곧게 선 사람을 본떴다. 둘째, 기본 글자에 획을 더하거나 합쳐 다른 글자를 만들었다. ㅅ에 획을 더하면 ㅈ, 또 더하면 ㅊ이 된다. 셋째, 비슷한 소리는 비슷한 모양으로 적어 적은 수의 글자로 우리말을 두루 읽고 쓸 수 있다. 다른 나라 글자도 저마다 자기 말을 적어 왔으니 깎아내리지 않고 존중해야 한다.","scoring_points":["한글의 특성 세 가지를 썼는가","특성마다 예를 들었는가","다른 나라 글자를 존중하는 태도를 썼는가"]},"explanation":["본뜸 · 더함 · 짜임이에요.","예를 들어요.","다른 글자도 존중해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
